    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        if (intent != null) {
            setIntent(intent);
            lastSeenHomeIntent = intent;
            // Before handlers strip TITLE / SHARE_REDIRECT_ID.
            noteIncomingIntentSkipsBackgroundFeedRefresh(intent);
            handleFooterTabExtra(intent);
            applySearchQueryExtra(intent);
            applyCategorySessionExtra(intent);
            applyDailyUpdatesOpenExtra(intent);
            // FCM push first (owns seating). Share only when no push TITLE.
            applyPushRedirectFromIntent(intent);
            applyShareRedirectFromIntent(intent);
        }
    }

    /**
     * Warm push open (app already on Home): pin {@code TITLE} via push_post_id
     * without stacking another HomePage. Mirrors onCreate TITLE / sticky wire.
     */
    private void applyPushRedirectFromIntent(@Nullable Intent intent) {
        if (intent == null) {
            return;
        }
        if (isPushOpenIntent(intent)) {
            MyFirebaseMessagingService.dismissOpenedPush(this, intent);
        }
        String pushRaw = pushPostIdFromIntent(intent);
        // PENDING only when this onNewIntent is a push tap (not every warm resume).
        if (!isPositivePostId(pushRaw) && isPushOpenIntent(intent)) {
            try {
                String pendingPush = SharedPrefsData.getString(
                        getApplicationContext(), Constants.PENDING_PUSH_POST, Constants.PREF_NAME);
                if (isPositivePostId(pendingPush)) {
                    pushRaw = pendingPush.trim();
                }
            } catch (Exception ignored) {
            }
        }
        if (!isPositivePostId(pushRaw)) {
            return;
        }
        long pushId;
        try {
            pushId = Long.parseLong(pushRaw.trim());
        } catch (NumberFormatException e) {
            showLog("push onNewIntent bad id=" + pushRaw);
            return;
        }
        if (pushId <= 0) {
            return;
        }
        // Shade + history can deliver the same tap twice (onNewIntent and the
        // deferred background check). Do not start a second page-0.
        if (pushOpenWireConsumed
                && isPositivePostId(pushUpdatedID)
                && pushUpdatedID.trim().equals(String.valueOf(pushId))
                && isApiRequested) {
            suppressFeedRefreshForIncomingIntent = true;
            showLog("push onNewIntent already seating " + pushId);
            return;
        }
        try {
            // Sticky for this tap only (process death while feed loads).
            SharedPrefsData.putString(
                    getApplicationContext(),
                    Constants.PENDING_PUSH_POST,
                    String.valueOf(pushId),
                    Constants.PREF_NAME);
            SharedPrefsData.putString(
                    getApplicationContext(), Constants.PENDING_SHARE_POST, "", Constants.PREF_NAME);
        } catch (Exception ignored) {
        }
        pushUpdatedID = String.valueOf(pushId);
        pushOpenWireConsumed = false;
        TITLE_VALUE = 0;
        deepLinkShareRescueAttempted = false;
        // Push owns seating over any in-memory share sticky.
        SHARE_ID = 0;
        SHARE_REDIRECT_ID = "0";
        // onStart may already have started the "first article" reload (it runs
        // before onNewIntent on some devices), or it may run next. That reload
        // clears this id and paints page 0. A 70-minute-old post is not in that
        // window, so the tap looked like it opened article 1. Drop the in-flight
        // reload, and tell onStart not to start another.
        feedModeEpoch++;
        suppressFeedRefreshForIncomingIntent = true;
        showLog("push onNewIntent TITLE=" + pushUpdatedID);
        try {
            intent.putExtra("notification", true);
            intent.putExtra("TITLE", pushUpdatedID);
            intent.putExtra("TITILE", pushUpdatedID);
            intent.putExtra(MyFirebaseMessagingService.EXTRA_PUSH_POST_ID, pushUpdatedID);
            intent.removeExtra("SHARE_REDIRECT_ID");
        } catch (Exception ignored) {
        }
        try {
            clearSearchFeedMode();
        } catch (Exception ignored) {
        }
        try {
            // A push is an open, not a return from the share sheet.
            FeedPositionKeepConfig.clear(this);
        } catch (Exception ignored) {
        }
        try {
            bookmarksModeSelected = false;
            // explicitSpecialOpen is checked before the mode flag. Leaving it
            // set would request special_posts. A full_image / full_video /
            // gallery / magazine push is still the main news feed.
            explicitSpecialOpen = false;
            setFeedModeFlags(false, false);
            applyHomeModeContentVisibility();
            refreshHomeModeToggleUi();
        } catch (Exception ignored) {
        }
        try {
            clearPendingFlipRestore();
        } catch (Exception ignored) {
        }
        try {
            // Same surface as a cold open: main My Feed, not Daily Updates,
            // Special, Local, or the calendar deck the user happened to be on.
            localFeedFromDailyUpdates = false;
            hideLocalFeedChrome();
            hideHomeCalendarMode();
            restoreDailyUpdatesOnCreate = false;
            hideHomeDailyUpdatesMode();
            showNewsFooterFromDailyUpdatesHub();
            category_id = 0;
            softMergeOnNextPage0 = false;
            positionx = 0;
            lastSettledFlipIndex = -1;
            requestSize = 0;
            requestPostition = 1;
            last_post_id = 0;
            skip = 0;
            actual_skip = 0;
            isFromLocalArticles = true;
            OpenPathCache.forceNextFeedNetwork(this);
            isApiRequested = true;
            isDataParsed = true;
            dummyResponse = null;
            ShowNews_Data_Values(0, 0);
        } catch (Exception e) {
            showLog("push onNewIntent land failed: " + e.getMessage());
        }
    }

    /**
     * Positive post id on a push tap. Non-numeric {@code TITLE} (the visible
     * headline) does not count — history rebuilds put that string in TITLE.
     */
    @Nullable
    private String pushPostIdFromIntent(@Nullable Intent intent) {
        String resolved = MyFirebaseMessagingService.resolvePushPostId(this, intent);
        if (isPositivePostId(resolved)) {
            return resolved.trim();
        }
        return null;
    }

    /**
     * True when this Intent is a notification tray tap (not splash forwarding a
     * blank TITLE). Splash always puts {@code TITLE}; only FCM sets
     * {@code notification}, {@code TITILE}, {@code anynews://push/…}, or
     * {@code OPEN_PUSH}.
     */
    private static boolean isPushOpenIntent(@Nullable Intent intent) {
        if (intent == null) {
            return false;
        }
        try {
            if (intent.getBooleanExtra("notification", false)) {
                return true;
            }
        } catch (Exception ignored) {
        }
        if (MyFirebaseMessagingService.isOpenPushAction(intent.getAction())) {
            return true;
        }
        if (postIdFromPushIntentUri(intent.getData()) != null) {
            return true;
        }
        try {
            String titile = intent.getStringExtra("TITILE");
            if (titile != null && !titile.trim().isEmpty()
                    && !"null".equalsIgnoreCase(titile.trim())
                    && !"0".equals(titile.trim())) {
                return Long.parseLong(titile.trim()) > 0L;
            }
        } catch (Exception ignored) {
        }
        return false;
    }

    /** Post id from FCM uniqueness URI {@code anynews://push/{postId}/…}. */
    @Nullable
    private static String postIdFromPushIntentUri(@Nullable Uri uri) {
        if (uri == null) {
            return null;
        }
        try {
            if (!"anynews".equalsIgnoreCase(uri.getScheme())
                    || !"push".equalsIgnoreCase(uri.getHost())) {
                return null;
            }
            String path = uri.getPath();
            if (path == null || path.length() < 2) {
                return null;
            }
            String seg = path.startsWith("/") ? path.substring(1) : path;
            int slash = seg.indexOf('/');
            if (slash > 0) {
                seg = seg.substring(0, slash);
            }
            if (seg.isEmpty() || "0".equals(seg) || "null".equalsIgnoreCase(seg)) {
                return null;
            }
            Long.parseLong(seg);
            return seg;
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Warm share open (app already on Home): pin the shared post without stacking
     * another HomePage. Mirrors onCreate SHARE_REDIRECT_ID / PENDING_SHARE_POST.
     */
    private void applyShareRedirectFromIntent(@Nullable Intent intent) {
        if (intent == null) {
            return;
        }
        // FCM push TITLE / anynews://push owns this open — do not steal with share sticky.
        try {
            String pushCheck = intent.getStringExtra("TITLE");
            if (pushCheck == null || pushCheck.trim().isEmpty()
                    || "null".equalsIgnoreCase(pushCheck.trim())) {
                pushCheck = intent.getStringExtra("TITILE");
            }
            if (pushCheck == null || pushCheck.trim().isEmpty()
                    || "null".equalsIgnoreCase(pushCheck.trim())
                    || "0".equals(pushCheck.trim())) {
                pushCheck = postIdFromPushIntentUri(intent.getData());
            }
            if (pushCheck != null && !pushCheck.trim().isEmpty()
                    && !"null".equalsIgnoreCase(pushCheck.trim())
                    && !"0".equals(pushCheck.trim())
                    && Long.parseLong(pushCheck.trim()) > 0) {
                return;
            }
        } catch (Exception ignored) {
        }
        String shareRedirect = intent.getStringExtra("SHARE_REDIRECT_ID");
        if (shareRedirect == null || shareRedirect.trim().isEmpty()
                || "null".equalsIgnoreCase(shareRedirect.trim())
                || "0".equals(shareRedirect.trim())) {
            try {
                String pendingShare = SharedPrefsData.getString(
                        getApplicationContext(), Constants.PENDING_SHARE_POST, Constants.PREF_NAME);
                if (pendingShare != null && !pendingShare.trim().isEmpty()
                        && !"0".equals(pendingShare.trim())
                        && !"null".equalsIgnoreCase(pendingShare.trim())) {
                    shareRedirect = pendingShare.trim();
                }
            } catch (Exception ignored) {
            }
        }
        try {
            SharedPrefsData.putString(
                    getApplicationContext(), Constants.PENDING_SHARE_POST, "", Constants.PREF_NAME);
        } catch (Exception ignored) {
        }
        if (shareRedirect == null || shareRedirect.trim().isEmpty()
                || "null".equalsIgnoreCase(shareRedirect.trim())
                || "0".equals(shareRedirect.trim())) {
            return;
        }
        long shareId;
        try {
            shareId = Long.parseLong(shareRedirect.trim());
        } catch (NumberFormatException e) {
            showLog("share onNewIntent bad id=" + shareRedirect);
            return;
        }
        if (shareId <= 0) {
            return;
        }
        SHARE_REDIRECT_ID = String.valueOf(shareId);
        SHARE_ID = shareId;
        deepLinkShareRescueAttempted = false;
        shareInviteRepairAttempts = 0;
        capturePendingShareGalleryPage(intent, shareId);
        // Captured before Daily Updates / Special are cleared. A magazine
        // already in the main news feed stays on that list so Share can blink
        // on the visible card. Special and Daily Updates are not that list.
        final boolean onMainNews = isPlainMainNewsFeed();
        try {
            FeedPositionKeepConfig.clear(this);
        } catch (Exception ignored) {
        }
        // Inbound share opens on News. A full/special card does not keep Special.
        explicitSpecialOpen = false;
        restoreDailyUpdatesOnCreate = false;
        leaveDailyUpdatesForShareOpen();
        // Drop an in-flight plain page-0 (background "first article" refresh)
        // so it cannot replace this share target after we seat it.
        feedModeEpoch++;
        showLog("share onNewIntent SHARE_ID=" + SHARE_ID);
        try {
            intent.removeExtra("SHARE_REDIRECT_ID");
        } catch (Exception ignored) {
        }
        // Leave Read / Special / Flash so News land + share_post_id pin can run.
        try {
            bookmarksModeSelected = false;
            explicitSpecialOpen = false;
            setFeedModeFlags(false, false);
            applyHomeModeContentVisibility();
            refreshHomeModeToggleUi();
        } catch (Exception ignored) {
        }
        try {
            clearPendingFlipRestore();
        } catch (Exception ignored) {
        }
        try {
            if (!onMainNews) {
                // The list on screen is Special, Daily Updates, or another
                // surface. Pinning here would keep that deck. Load main News.
                try {
                    clearSearchFeedMode();
                } catch (Exception ignored) {
                }
                localFeedFromDailyUpdates = false;
                hideLocalFeedChrome();
                category_id = 0;
                softMergeOnNextPage0 = false;
                positionx = 0;
                lastSettledFlipIndex = -1;
                last_post_id = 0;
                skip = 0;
                actual_skip = 0;
                isApiRequested = true;
                isDataParsed = true;
                dummyResponse = null;
                try {
                    OpenPathCache.forceNextFeedNetwork(this);
                } catch (Exception ignored) {
                }
                ShowNews_Data_Values(0, 0);
            } else if (indexOfRealDeepLinkTarget(list, shareId) >= 0) {
                maybeLandDeepLinkPostOnNews(false);
            } else if (!scheduleDeepLinkShareRescue(shareId)) {
                // Force a page-0 refresh with share sticky so List_All_Articles pins it.
                last_post_id = 0;
                skip = 0;
                actual_skip = 0;
                isApiRequested = true;
                isDataParsed = true;
                dummyResponse = null;
                ShowNews_Data_Values(category_id, 0);
            }
        } catch (Exception e) {
            showLog("share onNewIntent land failed: " + e.getMessage());
            android.util.Log.e("MagazineCrash", "share onNewIntent: " + e.getMessage());
        }
    }

    /** Enter FlipView keyword / single-article search mode from {@link InAppSearchActivity}. */
    private void applySearchQueryExtra(@Nullable Intent intent) {
        if (intent == null) {
            return;
        }
        long postIdExtra = 0L;
        if (intent.hasExtra(EXTRA_SEARCH_POST_ID)) {
            try {
                postIdExtra = intent.getLongExtra(EXTRA_SEARCH_POST_ID, 0L);
            } catch (Exception ignored) {
                postIdExtra = 0L;
            }
            intent.removeExtra(EXTRA_SEARCH_POST_ID);
        }
        boolean singleOnly = intent.getBooleanExtra(EXTRA_SEARCH_SINGLE_ONLY, false);
        intent.removeExtra(EXTRA_SEARCH_SINGLE_ONLY);
        String storyLabel = "";
        int storyCount = 0;
        if (intent.hasExtra(EXTRA_SEARCH_STORY)) {
            storyLabel = intent.getStringExtra(EXTRA_SEARCH_STORY);
            intent.removeExtra(EXTRA_SEARCH_STORY);
        }
        if (intent.hasExtra(EXTRA_SEARCH_STORY_COUNT)) {
            storyCount = intent.getIntExtra(EXTRA_SEARCH_STORY_COUNT, 0);
            intent.removeExtra(EXTRA_SEARCH_STORY_COUNT);
        }
        if (storyLabel == null) storyLabel = "";
        storyLabel = storyLabel.trim();
        boolean hasQuery = intent.hasExtra(EXTRA_SEARCH_QUERY);
        String q = hasQuery ? intent.getStringExtra(EXTRA_SEARCH_QUERY) : null;
        if (hasQuery) {
            intent.removeExtra(EXTRA_SEARCH_QUERY);
        }
        if (q == null) q = "";
        q = softenSearchQuery(q);
        if (q.isEmpty() && postIdExtra <= 0L) return;
        if (q.isEmpty() && postIdExtra > 0L) {
            q = String.valueOf(postIdExtra);
        }
        showLog("ANYNEWS_SEARCH open query=\"" + q + "\" postId=" + postIdExtra
                + " singleOnly=" + (singleOnly || postIdExtra > 0L));
        activeSearchQuery = q;
        activeSearchPostId = postIdExtra > 0L ? postIdExtra : 0L;
        activeSearchStoryLabel = storyLabel;
        activeSearchStoryCount = storyLabel.isEmpty() ? 0 : Math.max(0, storyCount);
        if (!storyLabel.isEmpty()) {
            singleOnly = false;
            activeSearchPostId = 0L;
        }
        activeSearchSingleOnly = singleOnly || activeSearchPostId > 0L;
        searchContentLanded = false;
        searchFeedActive = true;
        searchOpenHandledInCreate = true;
        // Allow one post_id→keyword retry; never soften single-only into multi stacks
        // (empty handler already skips soften when activeSearchSingleOnly).
        searchSoftRetryUsed = false;
        positionx = 0;
        // Leave Read / Special / Flash so search is not skipped by those gates.
        try {
            bookmarksModeSelected = false;
            setFeedModeFlags(false, false);
        } catch (Exception ignored) {
        }
        try {
            clearPendingFlipRestore();
        } catch (Exception ignored) {
        }
        // Drop in-flight main-feed responses that would paint over search hits.
        feedModeEpoch++;
        try {
            OpenPathCache.forceNextFeedNetwork(this);
        } catch (Exception ignored) {
        }
        updateSearchContextBar();
        // Never circular-reveal android.R.id.content — 3.41.64 set it INVISIBLE and
        // left footer/back dead when the reveal did not complete. Keep chrome live.
        ensureSearchChromeInteractive();
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        dummyResponse = null;
        isApiRequested = false;
        category_id = 0;
        // Tear down any previous News/hub FlipView immediately — never leave
        // Continue-reading visible while Search_Stories is in flight.
        try {
            if (list == null) {
                list = new ArrayList<>();
            } else {
                list.clear();
            }
            FeedEndHelper.stripAll(list);
            // Reset seat BEFORE empty notify so a mid-flip scheduleRestoreAfterFlip
            // cannot clamp the prior News index onto Continue-reading later.
            if (mFlipView != null) {
                mFlipView.resetSeatForNewFeed();
                mFlipView.setVisibility(View.VISIBLE);
            }
            if (adapter != null) {
                // Immediate notify — deferred settle left FlipView on a stale
                // News pageCount and crashed flipTo / painted hub-only.
                adapter.setCurrentFlipPage(0);
                adapter.setDataImmediate(list);
            }
            showHomeFeedLoadingReveal();
            ensureSearchChromeInteractive();
        } catch (Exception ignored) {
            list = new ArrayList<>();
        }
        try {
            inlist(0);
        } catch (Exception e) {
            ShowNews_Data_Values(0, -1);
        }
    }

    /**
     * Strip suggestion ellipsis / trailing punctuation so Search_Stories title
     * match aligns with what Suggestions indexed.
     */
    @NonNull
    private static String softenSearchQuery(@Nullable String raw) {
        if (raw == null) return "";
        String q = raw.trim();
        q = q.replace("\u2026", " ").replace("...", " ").replace('\u00A0', ' ');
        q = q.replaceAll("^[\\?\\[\\](){}:;!.,\\s\\-\\u2026]+|[\\?\\[\\](){}:;!.,\\s\\-\\u2026]+$", "");
        q = q.replaceAll("\\s+", " ").trim();
        q = q.replaceAll("\\.{2,}", " ").replaceAll("\\s+", " ").trim();
        return q;
    }

    /** Drop last token (or last char) when page-0 Search_Stories returned empty. */
    @Nullable
    private static String softenSearchQueryFurther(@Nullable String raw) {
        String q = softenSearchQuery(raw);
        if (q.length() < 4) return null;
        String[] parts = q.split("\\s+");
        if (parts.length > 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < parts.length - 1; i++) {
                if (i > 0) sb.append(' ');
                sb.append(parts[i]);
            }
            String out = sb.toString().trim();
            return out.isEmpty() ? null : out;
        }
        String out = q.substring(0, q.length() - 1).trim();
        return out.isEmpty() ? null : out;
    }

    /** JSON/Java null and the literal word {@code null} are not article copy. */
    private static boolean isNullishCopy(@Nullable String raw) {
        if (raw == null) return true;
        String t = raw.trim();
        return t.isEmpty()
                || "null".equalsIgnoreCase(t)
                || "undefined".equalsIgnoreCase(t);
    }

    @NonNull
    private static String blankNullishCopy(@Nullable String raw) {
        return isNullishCopy(raw) ? "" : raw.trim();
    }

    /** Stop {@code "" + null} from painting the word null on the opened search card. */
    private static void sanitizeSearchDatumCopy(@Nullable ModelClass.Datum d) {
        if (d == null) return;
        d.setTitle(blankNullishCopy(d.getTitle()));
        d.setDescription(blankNullishCopy(d.getDescription()));
        d.setWriterName(blankNullishCopy(d.getWriterName()));
        d.setRole(blankNullishCopy(d.getRole()));
        d.setStrip_content(blankNullishCopy(d.getStrip_content()));
        try {
            d.setPost_date_time(blankNullishCopy(d.getPost_date_time()));
        } catch (Exception ignored) {
        }
    }

    /**
     * A search row with no real title is a blank card from null fields.
     * The opened post ({@code pinnedPostId}) stays so the tapped article still shows.
     */
    private static boolean isJunkNullSearchCard(
            @Nullable ModelClass.Datum d, long pinnedPostId) {
        if (d == null) return true;
        if (FeedEndHelper.isFeedEnd(d)) return false;
        if (!isNullishCopy(d.getTitle())) return false;
        return !(pinnedPostId > 0L
                && d.getPostId() != null
                && d.getPostId() == pinnedPostId);
    }

    /**
     * Ensure a Search_Stories row has a FlipView layout key so getView never
     * paints Continue-reading for a real article (blank post_type → hub-on-every-page).
     */
    private static void ensureSearchHitPostType(@Nullable ModelClass.Datum d) {
        if (d == null || FeedEndHelper.isFeedEnd(d)) return;
        String existing = d.getPostType();
        if (existing != null && !existing.trim().isEmpty()) {
            String t = existing.trim();
            if ("greetings".equalsIgnoreCase(t) || "greeting".equalsIgnoreCase(t)) {
                d.setPostType("full_image");
            }
            return;
        }
        String media = d.getMediaType();
        if (media != null) {
            media = media.trim();
            if ("5".equals(media) || "6".equals(media)) {
                d.setPostType("full_video");
                return;
            }
            if ("3".equals(media) || "4".equals(media)) {
                d.setPostType("normal_video");
                return;
            }
        }
        if (d.getVideoUrl() != null && !d.getVideoUrl().trim().isEmpty()) {
            d.setPostType("normal_video");
            return;
        }
        d.setPostType("normal_image");
    }

    /**
     * Search deck invariant: real hits only, then exactly one Continue-reading hub.
     * Zero ads/share/ratings. Never hub-first when hits exist. Never hub-alone when
     * paintables == 0 — bounce to in-app search empty UI instead (Enter/Search with
     * no suggestion tap must not dump to Continue Reading). Suggestion / post_id
     * open ({@link #activeSearchSingleOnly}) →
     * {@code [chosen article, similar siblings…, Continue-reading hub]} — server
     * already ranked exact then similar; never hub-first; no News pagination.
     */
    private void finalizeSearchFeedSeating(boolean landOnHits) {
        if (!searchFeedActive) return;
        if (list == null) {
            list = new ArrayList<>();
        }
        try {
            ReadArticleStore.stripAdFeedSlots(list);
        } catch (Exception ignored) {
        }
        for (int i = list.size() - 1; i >= 0; i--) {
            ModelClass.Datum d = list.get(i);
            if (FeedEndHelper.isFeedEnd(d)) {
                continue;
            }
            if (d == null || d.getPostId() == null || d.getPostId() <= 0) {
                list.remove(i);
                continue;
            }
            try {
                sanitizeSearchDatumCopy(d);
            } catch (Exception ignored) {
            }
            // Null title/description used to seat a blank card (and paint "null")
            // under the opened hit. Keep only the pinned article when copy is empty.
            if (isJunkNullSearchCard(d, activeSearchPostId)) {
                showLog("ANYNEWS_SEARCH drop null/blank card postId=" + d.getPostId());
                list.remove(i);
                continue;
            }
            try {
                ensureSearchHitPostType(d);
            } catch (Exception ignored) {
            }
        }
        // Hard stop: zero paintables must never become Continue-reading hub alone.
        if (ReadArticleStore.countPaintableArticles(list) <= 0) {
            showLog("ANYNEWS_SEARCH finalize zero paintables — abort to search UI");
            abortKeywordSearchNoHits();
            return;
        }
        // Suggestion / post_id open: pin chosen article first, keep server-ranked
        // similar siblings below, then Continue-reading hub. Missing primary →
        // abort to search UI (never hub-only).
        if (activeSearchSingleOnly) {
            ModelClass.Datum keep = null;
            ArrayList<ModelClass.Datum> siblings = new ArrayList<>();
            for (int i = 0; i < list.size(); i++) {
                ModelClass.Datum d = list.get(i);
                if (d == null || FeedEndHelper.isFeedEnd(d)) continue;
                if (d.getPostId() == null || d.getPostId() <= 0) continue;
                if (activeSearchPostId > 0L
                        && d.getPostId() != null
                        && d.getPostId() == activeSearchPostId) {
                    keep = d;
                    continue;
                }
                if (keep == null && activeSearchPostId <= 0L) {
                    keep = d;
                    continue;
                }
                if (isJunkNullSearchCard(d, activeSearchPostId)) {
                    continue;
                }
                siblings.add(d);
            }
            // post_id not in payload yet — first strong hit is primary; rest similar.
            if (keep == null && !siblings.isEmpty()) {
                keep = siblings.remove(0);
            }
            list.clear();
            if (keep == null) {
                showLog("ANYNEWS_SEARCH single-only miss postId=" + activeSearchPostId
                        + " — abort to search UI");
                abortKeywordSearchNoHits();
                return;
            }
            list.add(keep);
            // Cap similar seats so FlipView stays finite (server already ≤12).
            int similarCap = 11;
            for (int i = 0; i < siblings.size() && i < similarCap; i++) {
                ModelClass.Datum s = siblings.get(i);
                if (s == null || s.getPostId() == null) continue;
                if (keep.getPostId() != null && s.getPostId().equals(keep.getPostId())) {
                    continue;
                }
                list.add(s);
            }
            // Pin context bar to the opened article title (not a stale keyword).
            try {
                String title = keep.getTitle();
                if (title != null && !title.trim().isEmpty()
                        && !"null".equalsIgnoreCase(title.trim())) {
                    activeSearchQuery = title.trim();
                }
            } catch (Exception ignored) {
            }
            FeedEndHelper.ensureAtEnd(list, this);
            // Finite deck — block near-end / overflip pagination forever in this mode.
            try {
                skip = Integer.MAX_VALUE / 4;
                actual_skip = skip;
                dummyResponse = null;
                isApiRequested = false;
                requestSize = list.size();
                requestPostition = Math.max(0, list.size()); // never == positionx on hub
            } catch (Exception ignored) {
            }
            showLog("ANYNEWS_SEARCH single seat=[primary,similar…,hub] postId="
                    + (keep.getPostId() != null ? keep.getPostId() : 0)
                    + " hits=" + ReadArticleStore.countPaintableArticles(list)
                    + " listSize=" + list.size());
            try {
                updateSearchContextBar();
            } catch (Exception ignored) {
            }
        } else {
            // Keyword multi-hit: exact then similar (server order), one hub last.
            FeedEndHelper.ensureAtEnd(list, this);
            // Finite first Search_Stories page only — park cursors so a stale
            // News requestPostition cannot fire page-N into this deck.
            try {
                skip = Integer.MAX_VALUE / 4;
                actual_skip = skip;
                dummyResponse = null;
                isApiRequested = false;
                requestSize = list.size();
                requestPostition = Math.max(requestSize, 99);
            } catch (Exception ignored) {
            }
        }
        int paintables = ReadArticleStore.countPaintableArticles(list);
        if (paintables <= 0) {
            showLog("ANYNEWS_SEARCH finalize post-seat zero — abort to search UI");
            abortKeywordSearchNoHits();
            return;
        }
        // Hard rule: while search content has not landed on page 0, ALWAYS force
        // hits-first — keyword and single alike. FlipView used to clamp a prior
        // News index onto list.size()-1 (Continue-reading hub). Once landed, do
        // not yank the user back from a deliberate hub swipe.
        boolean forceHits = landOnHits || !searchContentLanded;
        showLog("ANYNEWS_SEARCH finalize paintables=" + paintables
                + " listSize=" + list.size()
                + " land=" + landOnHits
                + " forceHits=" + forceHits
                + " contentLanded=" + searchContentLanded);
        try {
            if (mFlipView != null) {
                mFlipView.setVisibility(View.VISIBLE);
                if (forceHits) {
                    mFlipView.beginForcedPage0Seat();
                }
            }
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null && !list.isEmpty()) {
                txtNoData.setVisibility(View.GONE);
            }
            hideHomeFeedLoadingReveal(true);
            ensureSearchChromeInteractive();
        } catch (Exception ignored) {
        }
        if (forceHits) {
            forceSearchHitsOnPage0();
        } else if (paintables > 0) {
            // Multi-hit EOF / already scrolled: refresh deck without yanking to page 0.
            // Never keep a hub seat while hits exist — that was hub-first after EOF.
            try {
                int keepPage = 0;
                try {
                    if (mFlipView != null) {
                        keepPage = Math.max(0, mFlipView.getCurrentPage());
                    } else {
                        keepPage = Math.max(0, positionx);
                    }
                } catch (Exception ignored) {
                }
                if (keepPage >= list.size()) {
                    keepPage = Math.max(0, list.size() - 2);
                }
                if (keepPage < 0) keepPage = 0;
                // If FlipView drifted onto the hub, reclaim the last real hit.
                if (keepPage < list.size()
                        && FeedEndHelper.isFeedEnd(list.get(keepPage))) {
                    keepPage = Math.max(0, list.size() - 2);
                    if (FeedEndHelper.isFeedEnd(list.get(keepPage))) {
                        keepPage = 0;
                    }
                }
                if (adapter != null) {
                    adapter.setCurrentFlipPage(keepPage);
                    adapter.setDataImmediate(list);
                }
                if (mFlipView != null && mFlipView.getPageCount() > 0) {
                    mFlipView.flipTo(Math.min(keepPage, mFlipView.getPageCount() - 1));
                }
                positionx = keepPage;
            } catch (Exception ignored) {
            }
        }
        ensureSearchChromeInteractive();
        assertSearchHubIsLast();
    }

    /** Regression guard: hub must be last when paintables exist; never at index 0. */
    private void assertSearchHubIsLast() {
        if (!searchFeedActive || list == null || list.isEmpty()) return;
        try {
            int paintables = ReadArticleStore.countPaintableArticles(list);
            if (paintables <= 0) return;
            if (FeedEndHelper.isFeedEnd(list.get(0))
                    || ReadArticleStore.isSyntheticFeedSlot(list.get(0))) {
                showLog("ANYNEWS_SEARCH ASSERT hub/synth at 0 — repairing");
                forceSearchHitsOnPage0();
                return;
            }
            if (!FeedEndHelper.hasAtEnd(list)) {
                showLog("ANYNEWS_SEARCH ASSERT hub missing at end — ensuring");
                FeedEndHelper.ensureAtEnd(list, this);
                if (adapter != null) {
                    adapter.setDataImmediate(list);
                }
            }
            // Deduplicate mid-list hubs.
            for (int i = list.size() - 2; i >= 0; i--) {
                if (FeedEndHelper.isFeedEnd(list.get(i))) {
                    showLog("ANYNEWS_SEARCH ASSERT mid-list hub at " + i + " — stripping");
                    list.remove(i);
                }
            }
            if (!FeedEndHelper.hasAtEnd(list)) {
                FeedEndHelper.ensureAtEnd(list, this);
            }
        } catch (Exception e) {
            showLog("ANYNEWS_SEARCH assert hub failed: " + e.getMessage());
        }
    }

    /**
     * Hard land: first FlipView page must be a real hit when paintables &gt; 0.
     * Never leave distance/index on the Continue-reading hub.
     */
    private void forceSearchHitsOnPage0() {
        if (!searchFeedActive || list == null || list.isEmpty() || mFlipView == null) {
            return;
        }
        try {
            ReadArticleStore.stripAdFeedSlots(list);
        } catch (Exception ignored) {
        }
        int paintables = ReadArticleStore.countPaintableArticles(list);
        if (paintables <= 0) {
            return;
        }
        // Hub / synthetic must never sit at index 0 when hits exist.
        while (!list.isEmpty()
                && (FeedEndHelper.isFeedEnd(list.get(0))
                        || ReadArticleStore.isSyntheticFeedSlot(list.get(0))
                        || ReadArticleStore.isAdFeedSlot(list.get(0)))) {
            showLog("ANYNEWS_SEARCH ASSERT hub/synth at index 0 — stripping");
            list.remove(0);
        }
        if (ReadArticleStore.countPaintableArticles(list) > 0) {
            // Exactly one hub last (dedupe any piled-up end cards).
            FeedEndHelper.ensureAtEnd(list, this);
        }
        if (list.isEmpty()
                || FeedEndHelper.isFeedEnd(list.get(0))
                || ReadArticleStore.isSyntheticFeedSlot(list.get(0))) {
            showLog("ANYNEWS_SEARCH ASSERT still hub/synth-first — abort land");
            return;
        }
        try {
            ensureSearchHitPostType(list.get(0));
        } catch (Exception ignored) {
        }
        positionx = 0;
        try {
            // Clear restore anchors BEFORE notify so dataSetChanged cannot clamp
            // onto the hub at list.size()-1. Also lock FlipView to page 0.
            mFlipView.resetSeatForNewFeed();
            mFlipView.beginForcedPage0Seat();
            if (adapter != null) {
                adapter.setCurrentFlipPage(0);
                adapter.setDataImmediate(list);
            }
            if (mFlipView.getPageCount() > 0) {
                mFlipView.flipTo(0);
            }
            showLog("ANYNEWS_SEARCH force page0 ok listSize=" + list.size()
                    + " page0Type="
                    + (list.get(0).getPostType() != null ? list.get(0).getPostType() : "?")
                    + " page0Id="
                    + (list.get(0).getPostId() != null ? list.get(0).getPostId() : 0)
                    + " seat=" + mFlipView.getCurrentPage()
                    + " forced=" + mFlipView.isForcedPage0Seat());
        } catch (Exception e) {
            showLog("ANYNEWS_SEARCH force page0 failed: " + e.getMessage());
        }
        try {
            int cur = mFlipView.getCurrentPage();
            if (cur != 0) {
                showLog("ANYNEWS_SEARCH ASSERT seat=" + cur + " — flipTo(0)");
                mFlipView.flipTo(0);
                positionx = 0;
                cur = 0;
            }
            if (cur == 0
                    && !list.isEmpty()
                    && !FeedEndHelper.isFeedEnd(list.get(0))) {
                markSearchContentLanded();
            }
        } catch (Exception ignored) {
        }
        // Multi-frame reclaim: deferred dataSetChanged / peakNext / scheduleRestore
        // used to snap onto the hub one frame after a successful flipTo(0).
        scheduleSearchPage0Reclaim(0);
        scheduleSearchPage0Reclaim(32L);
        scheduleSearchPage0Reclaim(96L);
    }

    private void markSearchContentLanded() {
        searchContentLanded = true;
    }

    private void scheduleSearchPage0Reclaim(long delayMs) {
        if (mFlipView == null) return;
        final Runnable reclaim = () -> {
            try {
                if (!searchFeedActive || mFlipView == null || list == null) return;
                if (ReadArticleStore.countPaintableArticles(list) <= 0) return;
                if (list.isEmpty() || FeedEndHelper.isFeedEnd(list.get(0))) return;
                int cur = mFlipView.getCurrentPage();
                if (cur == 0) {
                    markSearchContentLanded();
                    // Keep mForcePage0OnDataChange until the user flips away
                    // (flipTo(page>0) clears it). Releasing at 96ms let a deferred
                    // dataSetChanged / peakNext clamp onto Continue-reading hub.
                    return;
                }
                // User already left page 0 (hub or later hit) — stop reclaiming.
                if (searchContentLanded) {
                    mFlipView.releaseForcedPage0Seat();
                    return;
                }
                showLog("ANYNEWS_SEARCH ASSERT post-frame seat=" + cur
                        + " delay=" + delayMs + " — flipTo(0)");
                positionx = 0;
                mFlipView.beginForcedPage0Seat();
                mFlipView.flipTo(0);
                if (adapter != null) {
                    adapter.setCurrentFlipPage(0);
                }
                markSearchContentLanded();
            } catch (Exception ignored) {
            }
        };
        if (delayMs <= 0L) {
            mFlipView.post(reclaim);
        } else {
            mFlipView.postDelayed(reclaim, delayMs);
        }
    }

    /**
     * Profile / in-app Search category strip → open that category feed.
     * Cold open uses EXTRA_SESSION_ID in {@code onCreate}; this handles
     * {@link #onNewIntent} when HomePage is already alive (CLEAR_TOP / SINGLE_TOP).
     * <p>
     * Always seats at the <b>first</b> article (page 0) — including when the
     * user was mid-feed on the same category before opening Profile. Clears
     * flip-restore checkpoints and FlipView continuum anchors so settle-persist
     * / CLEAR_TOP recreate cannot re-land mid-list.
     */
    private void applyCategorySessionExtra(@Nullable Intent intent) {
        if (intent == null || !intent.hasExtra("EXTRA_SESSION_ID")) {
            return;
        }
        // Same intent also carrying a keyword / single-article search — search wins.
        if (intent.hasExtra(EXTRA_SEARCH_QUERY)
                || intent.hasExtra(EXTRA_SEARCH_POST_ID)
                || intent.getBooleanExtra(EXTRA_SEARCH_SINGLE_ONLY, false)) {
            return;
        }
        String raw = intent.getStringExtra("EXTRA_SESSION_ID");
        intent.removeExtra("EXTRA_SESSION_ID");
        if (raw == null) return;
        raw = raw.trim();
        if (raw.isEmpty() || "0".equals(raw) || "null".equalsIgnoreCase(raw)) {
            return;
        }
        int catId;
        try {
            catId = Integer.parseInt(raw.replaceAll("[^0-9-]", ""));
        } catch (Exception e) {
            return;
        }
        if (catId <= 0) return;
        // Intentional category pick from Profile/Search: always restart at item 0
        // (do not keep mid-feed when catId is unchanged).
        clearSearchFeedMode();
        rememberCategoryFeedNameFromIntent(intent, catId);
        try {
            bookmarksModeSelected = false;
            setFeedModeFlags(false, false);
            applyHomeModeContentVisibility();
            refreshHomeModeToggleUi();
        } catch (Exception ignored) {
        }
        try {
            clearPendingFlipRestore();
        } catch (Exception ignored) {
        }
        try {
            SharedPrefsData.putInt(this, Constants.CategoryID, catId, Constants.PREF_NAME);
        } catch (Exception ignored) {
        }
        feedModeEpoch++;
        positionx = 0;
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        lastSettledFlipIndex = -1;
        requestPostition = 1;
        requestSize = 0;
        isApiRequested = false;
        isDataParsed = true;
        isFromLocalArticles = true;
        list = new ArrayList<>();
        dummyResponse = null;
        category_id = catId;
        // After the list clear: Daily Updates must not stay the checked tab,
        // and the empty gap must not hide WhatsApp (that rebuild lands the
        // check back on Daily Updates).
        leavePriorSurfaceForCategoryOpen();
        try {
            if (mFlipView != null) {
                mFlipView.resetSeatForNewFeed();
                // Seat is already page 0; drop force-lock so later ad/pagination
                // notifies do not snap a gesture flip back to first.
                mFlipView.releaseForcedPage0Seat();
            }
        } catch (Exception ignored) {
        }
        try {
            OpenPathCache.forceNextFeedNetwork(this);
        } catch (Exception ignored) {
        }
        try {
            inlist(catId);
        } catch (Exception e) {
            ShowNews_Data_Values(catId, -1);
        }
    }

    /** True when this intent opens a Profile/Search category feed ({@code id > 0}). */
    private static boolean isPositiveCategorySession(@Nullable Intent intent) {
        if (intent == null || !intent.hasExtra("EXTRA_SESSION_ID")) {
            return false;
        }
        String raw = intent.getStringExtra("EXTRA_SESSION_ID");
        if (raw == null) {
            return false;
        }
        raw = raw.trim();
        if (raw.isEmpty() || "0".equals(raw) || "null".equalsIgnoreCase(raw)) {
            return false;
        }
        try {
            return Integer.parseInt(raw.replaceAll("[^0-9-]", "")) > 0;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Profile / Search category is News for that category. Daily Updates,
     * Special, or calendar was only the previous tab. Hide that surface, light
     * News, and keep footer WhatsApp through the empty list so a menu rebuild
     * cannot check Daily Updates again.
     * <p>
     * Does not treat Daily Updates as the parent. Back from the category stays
     * on this News feed (Panchangam opened from a Daily Updates tile still
     * returns to that hub).
     */
    private void leavePriorSurfaceForCategoryOpen() {
        localFeedFromDailyUpdates = false;
        try {
            hideLocalFeedChrome();
        } catch (Exception ignored) {
        }
        try {
            hideHomeCalendarMode();
            hideHomeDailyUpdatesMode();
        } catch (Exception ignored) {
        }
        try {
            if (mFlipView != null) {
                mFlipView.setVisibility(View.VISIBLE);
            }
            if (comment_page != null) {
                comment_page.setVisibility(View.GONE);
            }
            showHomeFeedLoadingReveal();
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.GONE);
            }
        } catch (Exception ignored) {
        }
        showNewsFooterFromDailyUpdatesHub();
    }

    /** Leave keyword search FlipView mode (footer / Special / Video / context back). */
    private void clearSearchFeedMode() {
        searchFeedActive = false;
        activeSearchQuery = "";
        activeSearchPostId = 0L;
        activeSearchSingleOnly = false;
        activeSearchStoryLabel = "";
        activeSearchStoryCount = 0;
        searchContentLanded = false;
        searchSoftRetryUsed = false;
        try {
            if (mFlipView != null) {
                mFlipView.releaseForcedPage0Seat();
            }
        } catch (Exception ignored) {
        }
        updateSearchContextBar();
    }

    /**
     * Enter/Search with no suggestion tap returned zero paintables (or fetch failed).
     * Never seat Continue-reading hub alone — restore Main News under the stack and
     * reopen {@link InAppSearchActivity} with the typed query + empty/similar UI.
     */
    private void abortKeywordSearchNoHits() {
        if (!searchFeedActive) {
            return;
        }
        final String q =
                activeSearchQuery != null ? activeSearchQuery.trim() : "";
        showLog("ANYNEWS_SEARCH zero hits → search UI (no hub) q=\"" + q + "\"");
        try {
            hideHomeFeedLoadingReveal(true);
        } catch (Exception ignored) {
        }
        try {
            if (list == null) {
                list = new ArrayList<>();
            } else {
                list.clear();
            }
            FeedEndHelper.stripAll(list);
            if (adapter != null) {
                adapter.setDataImmediate(list);
            }
            if (mFlipView != null) {
                mFlipView.releaseForcedPage0Seat();
                mFlipView.setVisibility(View.GONE);
            }
            if (txtNoData != null) {
                txtNoData.setVisibility(View.GONE);
            }
        } catch (Exception ignored) {
        }
        clearSearchFeedMode();
        ensureSearchChromeInteractive();
        try {
            performFeedReload();
        } catch (Exception e) {
            try {
                last_post_id = 0;
                skip = 0;
                actual_skip = 0;
                list = new ArrayList<>();
                inlist(0);
            } catch (Exception ignored) {
            }
        }
        try {
            Intent intent = new Intent(this, InAppSearchActivity.class);
            if (!q.isEmpty()) {
                intent.putExtra(InAppSearchActivity.EXTRA_QUERY, q);
            }
            intent.putExtra(InAppSearchActivity.EXTRA_SHOW_NO_RESULTS, true);
            startActivity(intent);
            overridePendingTransition(0, 0);
        } catch (Exception e) {
            showLog("ANYNEWS_SEARCH abort reopen search failed: " + e.getMessage());
        }
    }

    /** Public for FlipperAdapter end-hub + chrome. */
    public boolean isSearchFeedActive() {
        return searchFeedActive
                && ((activeSearchQuery != null && !activeSearchQuery.trim().isEmpty())
                        || activeSearchPostId > 0L);
    }

