    /** Admin search_icon_on_toggle + search_icon_size_dp on News|Read chrome. */
    private void applyHomeModeSearchIcon() {
        if (homeModeSearchIcon == null) return;
        boolean show = com.anyNews.anynews.Utils.SearchIconConfig.isOnToggle(this);
        homeModeSearchIcon.setVisibility(show ? View.VISIBLE : View.GONE);
        if (!show) return;
        // Distinct richer glyph vs engagement-row outline magnifier — soft dark
        // chip (not solid white key), white magnifier + orange accent.
        try {
            if (homeModeSearchIcon instanceof ImageView) {
                ImageView iv = (ImageView) homeModeSearchIcon;
                iv.setImageResource(R.drawable.ic_search_toggle_rich);
                iv.setBackgroundResource(R.drawable.bg_search_toggle_soft);
            }
        } catch (Exception ignored) {
        }
        int dp = com.anyNews.anynews.Utils.SearchIconConfig.sizeDp(this);
        float density = getResources().getDisplayMetrics().density;
        int px = Math.round(dp * density);
        int slot = Math.round((dp + 16) * density);
        ViewGroup.LayoutParams lp = homeModeSearchIcon.getLayoutParams();
        if (lp != null) {
            lp.width = slot;
            lp.height = slot;
            homeModeSearchIcon.setLayoutParams(lp);
        }
        int pad = Math.max(4, (slot - px) / 2);
        homeModeSearchIcon.setPadding(pad, pad, pad, pad);
        try {
            if (homeModeSearchIcon instanceof ImageView) {
                com.anyNews.anynews.Utils.EngagementCountHelper.applyIconTint(
                        this, (ImageView) homeModeSearchIcon);
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * Open Profile with no transition. Reuses a warm {@link newProfileDetails} instance
     * when it was left alive under Home (footer tab switches), so re-taps feel like
     * in-shell News/Special flips instead of a cold Activity inflate.
     */
    private void openProfileInstant() {
        // Never open Profile while a Special nested gallery FlipView owns the swipe —
        // leaked footer clicks used to jump here mid page-turn.
        if (SpecialGalleryFlipHelper.isNestedGalleryDriving()
                || suppressFooterClickFromGallerySwipe) {
            showLog("openProfileInstant blocked — gallery swipe in progress");
            return;
        }
        if (getApplicationContext() == null
                || !getApplicationContext().getPackageName().equals(BuildConfig.APPLICATION_ID)) {
            return;
        }
        try {
            ArticleTtsHelper.stopAll();
        } catch (Exception ignored) {
        }
        Intent profile = new Intent(HomePage.this, newProfileDetails.class);
        profile.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT
                | Intent.FLAG_ACTIVITY_SINGLE_TOP);
        startActivity(profile);
        overridePendingTransition(0, 0);
    }

    /**
     * Profile footer / post-login: open News, Daily Updates, Special, or Profile
     * without leaving the HomePage process (CLEAR_TOP + SINGLE_TOP).
     * Legacy Panchangam EXTRA still opens calendar in-host; footer tab is product-hidden.
     */
    private void handleFooterTabExtra(@Nullable Intent intent) {
        if (intent == null || bottomNavigationView == null) {
            return;
        }
        if (!intent.hasExtra(EXTRA_FOOTER_TAB)) {
            return;
        }
        final int tabId = intent.getIntExtra(EXTRA_FOOTER_TAB, 0);
        intent.removeExtra(EXTRA_FOOTER_TAB);
        if (tabId == 0) {
            return;
        }
        bottomNavigationView.post(() -> {
            if (isFinishing() || isDestroyed()) {
                return;
            }
            try {
                if (tabId == R.id.navigation_profile) {
                    openProfileInstant();
                    return;
                }
                suppressBottomNavCallbacks = true;
                try {
                    bottomNavigationView.setSelectedItemId(tabId);
                } finally {
                    suppressBottomNavCallbacks = false;
                }
                if (tabId == R.id.navigation_home) {
                    performFeedReload();
                } else if (tabId == R.id.navigation_catagiries) {
                    performSpecialFeedOpen();
                } else if (tabId == R.id.navigation_status) {
                    performDailyUpdatesOpen();
                } else if (tabId == R.id.navigation_stricker) {
                    performCalendarOpen(false);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });
    }

    /** Process-once guard so feed cache refreshes cannot re-ask wave in the same session. */
    private boolean notificationRepromptHandledThisProcess = false;
    /** Process-once for post-install/update permission (independent of admin wave). */
    private boolean installNotificationPermHandledThisProcess = false;
    /**
     * Ask-on-open: once per resume so mid-session Settings disable still re-prompts on return,
     * without re-firing from feed refreshes in the same foreground period.
     */
    private boolean askOnOpenHandledThisResume = false;
    /** Request code for install + re-prompt POST_NOTIFICATIONS (ActivityCompat). */
    private static final int REQ_POST_NOTIFICATIONS = 2901;
    /** Pending result of {@link #requestNotificationPermission(boolean)}. */
    private boolean pendingNotifPermViaAdminReprompt = false;
    /**
     * Campaign one-shot: only mark shown_wave / server ack after the OS permission
     * result (or Settings handoff). Never burn the wave before the sheet appears.
     */
    private boolean pendingCampaignRepromptAck = false;
    /**
     * After a campaign soft/shown-only burn, Soft-Allow may still open the OS
     * sheet — keep this so Accepted / Don't allow can be reported without a
     * live pendingCampaignRepromptAck. Cleared on OS result or soft Not now.
     */
    private boolean campaignSoftAwaitingOsOutcome = false;
    /** Avoid stacking multiple soft notification enable dialogs. */
    private boolean notificationSettingsDialogShowing = false;
    /**
     * After the user taps Allow (or Open settings) on the soft notification dialog,
     * suppress ask-on-open re-shows across the permission / Settings pause→resume
     * cycle so ALLOW cannot loop on the same open. Cleared on real Home stop
     * (not when leaving for the system permission UI / app notification Settings).
     * Not set for Not now — that may ask again on the next resume per config.
     */
    private boolean notificationSoftAllowSettledThisOpen = false;
    /** True while we expect pause/stop from POST_NOTIFICATIONS or Open settings. */
    private boolean expectNotifSettingsOrPermReturn = false;

    private boolean isSystemNotificationsEnabledSafe() {
        try {
            return NotificationManagerCompat.from(this).areNotificationsEnabled();
        } catch (Exception e) {
            return true;
        }
    }

    private boolean hasPostNotificationsPermission() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) {
            return true;
        }
        return checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)
                == PackageManager.PERMISSION_GRANTED;
    }

    private boolean hasEverAskedPostNotifications() {
        if (SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_RUNTIME_EVER_ASKED,
                Constants.PREF_NAME,
                false)) {
            return true;
        }
        return SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_RUNTIME_ASK_VERSION,
                Constants.PREF_NAME) > 0;
    }

    private void markEverAskedPostNotifications() {
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_RUNTIME_EVER_ASKED,
                true,
                Constants.PREF_NAME);
        markNotificationRuntimeAskedVersion();
    }

    private boolean isAdminNotificationRepromptDue() {
        // OS / runtime off is the product meaning of "notifications OFF" (Daily
        // Updates bell). Server notification_flag often stays true after deny —
        // do not require server due alone.
        if (isSystemNotificationsEnabledSafe() && hasPostNotificationsPermission()) {
            return false;
        }
        // Hard gate: one-time sending OFF → never treat as due (ignore sticky
        // notification_reprompt_due prefs from a prior ON window).
        boolean campaignActive = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_ENABLED,
                Constants.PREF_NAME,
                false);
        if (!campaignActive) {
            return false;
        }
        int globalWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_WAVE,
                Constants.PREF_NAME);
        int shownWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_SHOWN_WAVE,
                Constants.PREF_NAME);
        // Local one-shot: sheet already presented (or user responded) for this
        // wave — never re-ask until admin bumps wave / new ON cycle.
        if (globalWave > 0 && shownWave >= globalWave) {
            return false;
        }
        boolean serverDue = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_DUE,
                Constants.PREF_NAME,
                false);
        if (serverDue) {
            return true;
        }
        // Campaign Active (splash/feed) + OS off + not yet shown this wave.
        // Covers drafts whose notification_flag is still true while the tray is OFF.
        return globalWave > 0 && shownWave < globalWave;
    }

    /**
     * When both admin ask modes are OFF, drop sticky local due so resume/feed
     * cannot re-fire from a prior one-time window.
     */
    private void clearStaleNotificationAskPrefsIfModesOff() {
        boolean askOnOpen = isPromptNotificationsOnOpenEnabled();
        boolean campaignActive = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_ENABLED,
                Constants.PREF_NAME,
                false);
        if (askOnOpen || campaignActive) {
            return;
        }
        clearNotificationRepromptDueLocal();
    }

    /** Persist that this campaign wave was already shown (survives process death). */
    private void markNotificationRepromptShownLocally() {
        int globalWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_WAVE,
                Constants.PREF_NAME);
        if (globalWave > 0) {
            SharedPrefsData.putInt(
                    getApplicationContext(),
                    Constants.NOTIFICATION_REPROMPT_SHOWN_WAVE,
                    globalWave,
                    Constants.PREF_NAME);
        }
        clearNotificationRepromptDueLocal();
    }

    /**
     * Home open: (1) admin wave re-prompt when due, (2) continuous ask-on-open when
     * admin flag ON and OS notifications still off, (3) first-install
     * POST_NOTIFICATIONS system sheet once if never requested yet — even when
     * both admin modes are OFF. After that decision, both modes OFF → no
     * Settings / soft re-ask spam. Location soft-ask remains
     * {@link #maybeSoftRequestDraftGpsPermission}.
     */
    private void maybeRequestInstallAndRepromptPermissions() {
        if (isFinishing() || isDestroyed()) return;
        maybeRecoverPrematureRepromptAck();
        clearStaleNotificationAskPrefsIfModesOff();
        // Wave due wins once per process. If already handled (or feed already
        // showed it), fall through so ask-on-open is not permanently blocked
        // while notification_reprompt_due stays true in prefs.
        if (isAdminNotificationRepromptDue() && !notificationRepromptHandledThisProcess) {
            showNotificationAlert(false);
            return;
        }
        if (isPromptNotificationsOnOpenEnabled()) {
            maybePromptNotificationsOnOpen();
            return;
        }
        // Both admin flags OFF → still show the OS sheet once on first install
        // (never asked). After Don't allow / decided, no further auto-ask.
        maybeRequestInstallNotificationPermission();
    }

    /**
     * 3.41.92 burned {@code shown_wave} before the OS sheet appeared. Once per
     * install of this fix, clear local shown so an Active campaign can ask again
     * while notifications are still OFF.
     */
    private void maybeRecoverPrematureRepromptAck() {
        final String migratedKey = "notif_reprompt_ack_after_sheet_v321";
        if (SharedPrefsData.getBool(
                getApplicationContext(), migratedKey, Constants.PREF_NAME, false)) {
            return;
        }
        SharedPrefsData.putBool(
                getApplicationContext(), migratedKey, true, Constants.PREF_NAME);
        if (isSystemNotificationsEnabledSafe() && hasPostNotificationsPermission()) {
            return;
        }
        boolean campaignActive = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_ENABLED,
                Constants.PREF_NAME,
                false);
        int globalWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_WAVE,
                Constants.PREF_NAME);
        if (!campaignActive || globalWave <= 0) {
            return;
        }
        SharedPrefsData.putInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_SHOWN_WAVE,
                0,
                Constants.PREF_NAME);
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_DUE,
                true,
                Constants.PREF_NAME);
    }

    private boolean isPromptNotificationsOnOpenEnabled() {
        return SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.PROMPT_NOTIFICATIONS_ON_OPEN,
                Constants.PREF_NAME,
                false);
    }

    /**
     * Admin continuous flag: once per resume, if system notifications (or
     * POST_NOTIFICATIONS) are off → OS Allow/Don't allow when Android still shows it,
     * else a soft in-app dialog over the feed (never auto-open Settings).
     * Deny/dismiss does not block reading; next open/resume asks again while flag stays ON.
     */
    private void maybePromptNotificationsOnOpen() {
        if (askOnOpenHandledThisResume) {
            return;
        }
        boolean systemOn = isSystemNotificationsEnabledSafe();
        boolean runtimeOk = hasPostNotificationsPermission();
        if (systemOn && runtimeOk) {
            // Already fully on — no prompt; do NOT set process-once so a later Settings
            // disable + resume can still ask while the admin flag stays ON.
            askOnOpenHandledThisResume = true;
            ensureNotificationPrefAlignedWithSystem(false);
            return;
        }
        askOnOpenHandledThisResume = true;
        getWindow().getDecorView().postDelayed(() -> {
            if (isFinishing() || isDestroyed()) return;
            if (!isPromptNotificationsOnOpenEnabled()) return;
            if (isSystemNotificationsEnabledSafe() && hasPostNotificationsPermission()) {
                ensureNotificationPrefAlignedWithSystem(false);
                return;
            }
            // force=true → OS dialog if allowed; else soft in-app dialog (no Settings jump).
            requestNotificationPermission(true);
            logNotificationPermissionAsk("HomePage", "ask_on_open", false);
        }, 450L);
    }

    /**
     * First install / never requested POST_NOTIFICATIONS: show the OS Allow /
     * Don't allow sheet once. Independent of admin ask-on-open / one-time.
     * After that decision, admin campaigns own any re-prompt.
     */
    private void maybeRequestInstallNotificationPermission() {
        if (installNotificationPermHandledThisProcess || notificationRepromptHandledThisProcess) {
            return;
        }
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) {
            // Pre-13: ensure opt-in pref tracks system tray when not user-disabled.
            ensureNotificationPrefAlignedWithSystem(false);
            return;
        }
        if (hasPostNotificationsPermission()) {
            ensureNotificationPrefAlignedWithSystem(false);
            markNotificationRuntimeAskedVersion();
            return;
        }
        // Already showed the system sheet (Allow or Don't allow) → do not
        // re-ask via install when admin modes are OFF (no soft/Settings spam).
        if (hasEverAskedPostNotifications()) {
            return;
        }
        installNotificationPermHandledThisProcess = true;
        getWindow().getDecorView().postDelayed(() -> {
            if (isFinishing() || isDestroyed()) return;
            if (hasPostNotificationsPermission()) {
                ensureNotificationPrefAlignedWithSystem(false);
                markNotificationRuntimeAskedVersion();
                return;
            }
            if (hasEverAskedPostNotifications()) {
                return;
            }
            requestNotificationPermission(false /* force / viaAdminReprompt */);
            logNotificationPermissionAsk("HomePage", "install", false);
        }, 450L);
    }

    private void markNotificationRuntimeAskedVersion() {
        SharedPrefsData.putInt(
                getApplicationContext(),
                Constants.NOTIFICATION_RUNTIME_ASK_VERSION,
                BuildConfig.VERSION_CODE,
                Constants.PREF_NAME);
    }

    /**
     * After OS grant: keep pref ON and sync server. Do not force OFF before user is asked.
     */
    private void ensureNotificationPrefAlignedWithSystem(boolean viaAdminReprompt) {
        boolean systemOn = isSystemNotificationsEnabledSafe() && hasPostNotificationsPermission();
        if (!systemOn) {
            return;
        }
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_ENABLED,
                true,
                Constants.PREF_NAME);
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.switchNotification,
                true,
                Constants.PREF_NAME);
        syncNotificationFlagAfterReprompt(true, viaAdminReprompt);
    }

    /**
     * Shared install + admin ask path. Always use the first-install Play Store style
     * POST_NOTIFICATIONS system sheet (Allow / Don't allow). Never the custom
     * OPEN SETTINGS / NOT NOW / ALLOW AlertDialog.
     */
    private void requestNotificationPermission(boolean force) {
        requestPostNotificationsPermission(force);
    }

    /** True when Android may still show the POST_NOTIFICATIONS system dialog. */
    private boolean canShowPostNotificationsSystemDialog() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) {
            return false;
        }
        if (hasPostNotificationsPermission()) {
            return false;
        }
        if (!hasEverAskedPostNotifications()) {
            return true;
        }
        return ActivityCompat.shouldShowRequestPermissionRationale(
                this, Manifest.permission.POST_NOTIFICATIONS);
    }

    private void requestPostNotificationsPermission(final boolean viaAdminReprompt) {
        pendingNotifPermViaAdminReprompt = viaAdminReprompt;

        // First-ever POST_NOTIFICATIONS (fresh install) always allowed — same
        // as location. Admin ask-on-open / one-time are separate re-prompt paths.
        // When both admin modes are OFF and we already asked once, do not
        // requestPermissions or drop into soft/Settings.
        final boolean firstInstallNeverAsked =
                Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU
                        && !hasPostNotificationsPermission()
                        && !hasEverAskedPostNotifications();
        if (!viaAdminReprompt
                && !isPromptNotificationsOnOpenEnabled()
                && !isAdminNotificationRepromptDue()
                && !pendingCampaignRepromptAck
                && !firstInstallNeverAsked) {
            return;
        }

        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) {
            // Pre-13: no POST_NOTIFICATIONS system sheet. Never dump to Settings
            // as the "ask" — soft in-app dialog; Settings only on explicit tap.
            if (isSystemNotificationsEnabledSafe()) {
                finishPendingCampaignAckAccepted();
                onNotificationPermissionGrantedFromReprompt(viaAdminReprompt);
            } else {
                // Soft ask presented → burn wave as shown-only (not Don't allow).
                finishPendingCampaignAckShownOnly();
                showSoftNotificationEnableDialog();
            }
            return;
        }

        if (hasPostNotificationsPermission()) {
            if (isSystemNotificationsEnabledSafe()) {
                finishPendingCampaignAckAccepted();
                onNotificationPermissionGrantedFromReprompt(viaAdminReprompt);
            } else {
                // Tray master off with runtime granted: soft dialog; Settings only
                // if the user taps Allow / Open settings.
                finishPendingCampaignAckShownOnly();
                showSoftNotificationEnableDialog();
            }
            return;
        }

        // Permanent deny: OS will not show Allow/Don't allow again. Soft dialog
        // over the feed — never auto-open the system Allow notifications page.
        // Burn wave as shown-only; Don't allow is only OS POST_NOTIFICATIONS deny.
        if (hasEverAskedPostNotifications()
                && !ActivityCompat.shouldShowRequestPermissionRationale(
                        this, Manifest.permission.POST_NOTIFICATIONS)) {
            markNotificationRuntimeAskedVersion();
            finishPendingCampaignAckShownOnly();
            showSoftNotificationEnableDialog();
            return;
        }

        // Play Store / first-install system sheet (Allow / Don't allow).
        launchPostNotificationsSystemDialog();
    }

    /** Shows the install-style POST_NOTIFICATIONS system dialog over the feed. */
    private void launchPostNotificationsSystemDialog() {
        markEverAskedPostNotifications();
        expectNotifSettingsOrPermReturn = true;
        try {
            ActivityCompat.requestPermissions(
                    this,
                    new String[]{Manifest.permission.POST_NOTIFICATIONS},
                    REQ_POST_NOTIFICATIONS);
            // One-time: sheet was presented → local never-again for this wave
            // even if the process dies before the user responds.
            markCampaignShownOnSheetPresented();
        } catch (Exception e) {
            showLog("request POST_NOTIFICATIONS failed: " + e.getMessage());
            expectNotifSettingsOrPermReturn = false;
            // Do not burn campaign wave — leave pending so next open can retry.
        }
    }

    /**
     * One-time sending: once the OS sheet (or soft ask) is presented, burn local
     * shown_wave immediately so reopen never re-asks until a new ON/wave cycle.
     * Server ack with converted / Don't allow waits for
     * {@link #finishPendingCampaignAckOutcome} or shown-only burn.
     */
    private void markCampaignShownOnSheetPresented() {
        if (!pendingCampaignRepromptAck) {
            return;
        }
        markNotificationRepromptShownLocally();
    }

    private void handlePostNotificationsPermissionResult(boolean granted) {
        final boolean viaAdmin = pendingNotifPermViaAdminReprompt;
        pendingNotifPermViaAdminReprompt = false;
        expectNotifSettingsOrPermReturn = false;
        // Permission UI always causes pause/resume — keep ask-on-open settled so
        // we cannot immediately reappear after Allow/Deny.
        askOnOpenHandledThisResume = true;
        // Source-only Don't allow / Accepted: OS POST_NOTIFICATIONS result only.
        if (granted) {
            finishPendingCampaignAckAccepted();
            notificationSoftAllowSettledThisOpen = false;
            onNotificationPermissionGrantedFromReprompt(viaAdmin);
            return;
        }
        finishPendingCampaignAckDontAllow();
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_ENABLED,
                false,
                Constants.PREF_NAME);
        // Keep server draft aligned with OS OFF so one-time due can match.
        syncNotificationFlagAfterReprompt(false, false);
        // Soft-Allow → OS Don't allow: stay dismissed for this open (no soft loop).
        // Next real background→resume may ask again while admin ask-on-open is ON.
        notificationSoftAllowSettledThisOpen = true;
    }

    /** One-time: user Allowed (or already fully ON). */
    private void finishPendingCampaignAckAccepted() {
        finishPendingCampaignAckOutcome(/*accepted*/ true, /*dontAllow*/ false);
    }

    /** One-time: user tapped Don't allow on the OS POST_NOTIFICATIONS sheet. */
    private void finishPendingCampaignAckDontAllow() {
        finishPendingCampaignAckOutcome(/*accepted*/ false, /*dontAllow*/ true);
    }

    /**
     * Soft / permanent-deny / pre-13: burn the wave so we do not re-ask, but do
     * not count as Accepted or Don't allow (no OS Allow/Don't allow answer).
     */
    private void finishPendingCampaignAckShownOnly() {
        if (!pendingCampaignRepromptAck) {
            return;
        }
        pendingCampaignRepromptAck = false;
        // Soft Allow may still present the OS sheet — keep outcome reporting armed.
        campaignSoftAwaitingOsOutcome = true;
        markNotificationRepromptShownLocally();
        ackNotificationReprompt(
                false,
                false,
                false,
                "HomePage",
                "campaign",
                /*reportOutcome*/ false,
                /*dontAllow*/ false);
    }

    /**
     * Persist campaign outcome after OS Allow / Don't allow.
     * Soft-Allow may have already burned the wave as shown-only; still report
     * Accepted / Don't allow when the OS sheet returns for that campaign.
     */
    private void finishPendingCampaignAckOutcome(boolean accepted, boolean dontAllow) {
        final boolean report =
                pendingCampaignRepromptAck || campaignSoftAwaitingOsOutcome;
        pendingCampaignRepromptAck = false;
        campaignSoftAwaitingOsOutcome = false;
        if (!report) {
            // Ask-on-open / install OS deny — do not write one-time hub outcomes.
            return;
        }
        markNotificationRepromptShownLocally();
        ackNotificationReprompt(
                accepted,
                false,
                accepted,
                "HomePage",
                "campaign",
                /*reportOutcome*/ true,
                dontAllow);
    }

    /**
     * Soft in-app prompt when Android will not show Allow / Don't allow again
     * (permanent deny, pre-13, or tray toggled off while runtime is still granted).
     * Primary Allow retries the OS dialog when possible; Open settings is optional.
     * Never auto-starts Settings — only if the user taps that button.
     */
    private void showSoftNotificationEnableDialog() {
        if (isFinishing() || isDestroyed()) return;
        if (notificationSettingsDialogShowing) return;
        if (notificationSoftAllowSettledThisOpen) return;
        if (isSystemNotificationsEnabledSafe() && hasPostNotificationsPermission()) {
            ensureNotificationPrefAlignedWithSystem(pendingNotifPermViaAdminReprompt);
            return;
        }
        notificationSettingsDialogShowing = true;
        final boolean needSettingsForTray =
                hasPostNotificationsPermission() && !isSystemNotificationsEnabledSafe();
        try {
            AlertDialog.Builder builder = new AlertDialog.Builder(this)
                    .setTitle(R.string.app_name)
                    .setMessage(
                            needSettingsForTray
                                    ? "Notifications are turned off in system settings. Enable them to get breaking news alerts — or keep reading."
                                    : "Allow notifications to get breaking news alerts? You can keep reading either way.")
                    .setPositiveButton(
                            "Allow",
                            (dialog, which) -> {
                                // Advance state for this open so pause→resume from the
                                // OS dialog / Settings cannot re-show this soft prompt.
                                notificationSoftAllowSettledThisOpen = true;
                                askOnOpenHandledThisResume = true;
                                if (needSettingsForTray) {
                                    expectNotifSettingsOrPermReturn = true;
                                    campaignSoftAwaitingOsOutcome = false;
                                    openAppNotificationSettingsForReprompt();
                                    return;
                                }
                                if (canShowPostNotificationsSystemDialog()) {
                                    expectNotifSettingsOrPermReturn = true;
                                    pendingNotifPermViaAdminReprompt = true;
                                    // Keep campaignSoftAwaitingOsOutcome if set by
                                    // shown-only burn so OS Deny/Allow is counted.
                                    launchPostNotificationsSystemDialog();
                                    return;
                                }
                                // OS will not show POST_NOTIFICATIONS again — open
                                // Settings once from this user tap (not a loop).
                                campaignSoftAwaitingOsOutcome = false;
                                expectNotifSettingsOrPermReturn = true;
                                openAppNotificationSettingsForReprompt();
                            })
                    .setNeutralButton(
                            "Open settings",
                            (dialog, which) -> {
                                notificationSoftAllowSettledThisOpen = true;
                                askOnOpenHandledThisResume = true;
                                // Leaving for Settings — not an OS Don't allow.
                                campaignSoftAwaitingOsOutcome = false;
                                expectNotifSettingsOrPermReturn = true;
                                openAppNotificationSettingsForReprompt();
                            })
                    .setNegativeButton(
                            "Not now",
                            (dialog, which) -> {
                                // Dismiss until next open/resume — do not settle Allow.
                                // Shown-only burn already sent; no Don't allow.
                                campaignSoftAwaitingOsOutcome = false;
                                askOnOpenHandledThisResume = true;
                            })
                    .setOnDismissListener(d -> notificationSettingsDialogShowing = false);
            builder.show();
        } catch (Exception e) {
            // Do NOT auto-open Settings on dialog failure — leave user on the feed.
            notificationSettingsDialogShowing = false;
            showLog("soft notification dialog failed: " + e.getMessage());
        }
    }

    /** Only called after an explicit user tap on Open settings / Allow→Settings. */
    private void openAppNotificationSettingsForReprompt() {
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                Intent intent = new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS);
                intent.putExtra(android.provider.Settings.EXTRA_APP_PACKAGE, getPackageName());
                startActivity(intent);
            } else {
                Intent intent = new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
                intent.setData(Uri.parse("package:" + getPackageName()));
                startActivity(intent);
            }
        } catch (Exception ignored) {
        }
    }

    public void showNotificationAlert(boolean showPopup){
        boolean due = isAdminNotificationRepromptDue();
        // showPopup is campaign-only from feed (legacy daily prompt removed server-side).
        // Ignore feed showPopup when this wave was already shown locally, or when
        // one-time sending is OFF.
        boolean campaignActive = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_ENABLED,
                Constants.PREF_NAME,
                false);
        int globalWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_WAVE,
                Constants.PREF_NAME);
        int shownWave = SharedPrefsData.getInt(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_SHOWN_WAVE,
                Constants.PREF_NAME);
        boolean alreadyShownThisWave = globalWave > 0 && shownWave >= globalWave;
        boolean shouldConsider =
                due || (campaignActive && showPopup && !alreadyShownThisWave);
        if (!shouldConsider) {
            return;
        }
        // Once per process — do not re-ask on every feed refresh.
        if (notificationRepromptHandledThisProcess) {
            return;
        }

        boolean systemOn = isSystemNotificationsEnabledSafe();
        boolean prefOn = SharedPrefsData.getBool(
                getApplicationContext(),
                Constants.NOTIFICATION_ENABLED,
                Constants.PREF_NAME,
                true);
        boolean fullyOn = systemOn && prefOn && hasPostNotificationsPermission();
        // Feed campaign alert must ack even if local due pref was already cleared.
        final boolean isAdminDue =
                due || (campaignActive && showPopup && !alreadyShownThisWave);

        // Fully enabled: clear due without dialog (only once for this wave).
        if (fullyOn) {
            notificationRepromptHandledThisProcess = true;
            installNotificationPermHandledThisProcess = true;
            markNotificationRuntimeAskedVersion();
            if (isAdminDue) {
                markNotificationRepromptShownLocally();
                ackNotificationReprompt(false, true, true, "HomePage", "campaign");
            }
            ensureNotificationPrefAlignedWithSystem(isAdminDue);
            return;
        }

        notificationRepromptHandledThisProcess = true;
        installNotificationPermHandledThisProcess = true;
        // pending until sheet presented / soft dialog / result — then
        // markCampaignShownOnSheetPresented or finishPendingCampaignAck*.
        pendingCampaignRepromptAck = isAdminDue;

        // Keep draft flag aligned with OS OFF so server due matches next splash.
        if (!isSystemNotificationsEnabledSafe() || !hasPostNotificationsPermission()) {
            SharedPrefsData.putBool(
                    getApplicationContext(),
                    Constants.NOTIFICATION_ENABLED,
                    false,
                    Constants.PREF_NAME);
            syncNotificationFlagAfterReprompt(false, false);
        }

        // Admin force: install-style OS dialog when Android can show it; else
        // soft in-app dialog (never auto-open Settings as the ask).
        requestNotificationPermission(true);
    }

    private void clearNotificationRepromptDueLocal() {
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_REPROMPT_DUE,
                false,
                Constants.PREF_NAME);
    }

    private void onNotificationPermissionGrantedFromReprompt(boolean viaAdminReprompt) {
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.NOTIFICATION_ENABLED,
                true,
                Constants.PREF_NAME);
        SharedPrefsData.putBool(
                getApplicationContext(),
                Constants.switchNotification,
                true,
                Constants.PREF_NAME);
        // Campaign ack is handled in finishPendingCampaignAck* / fullyOn path.
        // Sync app opt-in flag (also marks converted when due/shown on server).
        syncNotificationFlagAfterReprompt(true, viaAdminReprompt);
    }

    private void ackNotificationReprompt(
            boolean converted,
            boolean alreadyEnabled,
            boolean notificationFlagOn,
            String screen,
            String reason) {
        ackNotificationReprompt(
                converted,
                alreadyEnabled,
                notificationFlagOn,
                screen,
                reason,
                /*reportOutcome*/ false,
                /*dontAllow*/ false);
    }

    /**
     * @param reportOutcome when true, send accepted/denied for hub Accepted /
     *     Don't allow counts (OS sheet only). Shown-only burns omit outcomes.
     */
    private void ackNotificationReprompt(
            boolean converted,
            boolean alreadyEnabled,
            boolean notificationFlagOn,
            String screen,
            String reason,
            boolean reportOutcome,
            boolean dontAllow) {
        try {
            int draftId = SharedPrefsData.getInt(
                    getApplicationContext(), Constants.DraftID, Constants.PREF_NAME);
            if (draftId <= 0) return;
            LanguageSelectionRequest requestModel = new LanguageSelectionRequest();
            requestModel.setDraftId(draftId);
            requestModel.setConverted(converted);
            requestModel.setAlreadyEnabled(alreadyEnabled);
            // One-time send outcome (source-only): OS Allow → accepted; OS Don't
            // allow → denied. Soft/shown-only burns leave both unset.
            if (reportOutcome && !alreadyEnabled) {
                requestModel.setAccepted(converted && !dontAllow);
                requestModel.setDenied(dontAllow);
            }
            if (notificationFlagOn || converted) {
                requestModel.setNotificationFlag(true);
            } else if (dontAllow || (!converted && !alreadyEnabled && reportOutcome)) {
                requestModel.setNotificationFlag(false);
            }
            if (screen != null && !screen.isEmpty()) {
                requestModel.setScreen(screen);
            }
            if (reason != null && !reason.isEmpty()) {
                requestModel.setReason(reason);
            }
            int wave = SharedPrefsData.getInt(
                    getApplicationContext(),
                    Constants.NOTIFICATION_REPROMPT_WAVE,
                    Constants.PREF_NAME);
            if (wave > 0) {
                requestModel.setWave(wave);
            }
            String jsonString = new Gson().toJson(requestModel);
            String encrpt_data = encrypt(jsonString);
            EncritonRequestData body = new EncritonRequestData();
            body.setData(encrpt_data);
            JsonObject payload = new Gson().toJsonTree(body).getAsJsonObject();
            APIService apiService = RestApiClient.getClient().create(APIService.class);
            apiService.ack_notification_reprompt("v3", payload).enqueue(new Callback<EncreptionRequest>() {
                @Override
                public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                }

                @Override
                public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                }
            });
        } catch (Exception e) {
            showLog("ack reprompt failed: " + e.getMessage());
        }
    }

    /** Best-effort analytics for non-campaign permission prompts (hub by-screen stats). */
    private void logNotificationPermissionAsk(String screen, String reason, boolean converted) {
        try {
            int draftId = SharedPrefsData.getInt(
                    getApplicationContext(), Constants.DraftID, Constants.PREF_NAME);
            if (draftId <= 0) return;
            LanguageSelectionRequest requestModel = new LanguageSelectionRequest();
            requestModel.setDraftId(draftId);
            requestModel.setScreen(screen != null ? screen : "HomePage");
            requestModel.setReason(reason != null ? reason : "other");
            requestModel.setConverted(converted);
            int wave = SharedPrefsData.getInt(
                    getApplicationContext(),
                    Constants.NOTIFICATION_REPROMPT_WAVE,
                    Constants.PREF_NAME);
            if (wave > 0) {
                requestModel.setWave(wave);
            }
            String jsonString = new Gson().toJson(requestModel);
            String encrpt_data = encrypt(jsonString);
            EncritonRequestData body = new EncritonRequestData();
            body.setData(encrpt_data);
            JsonObject payload = new Gson().toJsonTree(body).getAsJsonObject();
            APIService apiService = RestApiClient.getClient().create(APIService.class);
            apiService.log_notification_permission_ask("v3", payload).enqueue(new Callback<EncreptionRequest>() {
                @Override
                public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                }

                @Override
                public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                }
            });
        } catch (Exception e) {
            showLog("log notif ask failed: " + e.getMessage());
        }
    }

    private void syncNotificationFlagAfterReprompt(boolean enabled, boolean viaReprompt) {
        try {
            LanguageSelectionRequest requestModel = new LanguageSelectionRequest();
            requestModel.setDraftId(
                    SharedPrefsData.getInt(
                            getApplicationContext(), Constants.DraftID, Constants.PREF_NAME));
            requestModel.setProperty("notification_flag");
            requestModel.setValue(enabled);
            if (viaReprompt) {
                requestModel.setViaReprompt(true);
            }
            String jsonString = new Gson().toJson(requestModel);
            String encrpt_data = encrypt(jsonString);
            EncritonRequestData body = new EncritonRequestData();
            body.setData(encrpt_data);
            JsonObject payload = new Gson().toJsonTree(body).getAsJsonObject();
            APIService apiService = RestApiClient.getClient().create(APIService.class);
            apiService.update_settings("v3", payload).enqueue(new Callback<EncreptionRequest>() {
                @Override
                public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                }

                @Override
                public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                }
            });
        } catch (Exception e) {
            showLog("update notif after reprompt failed: " + e.getMessage());
        }
    }

    private void sendNotification(String title) {
        RemoteViews collapsedView = new RemoteViews(context.getPackageName(), R.layout.download_video_notification);
        final Uri uri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION);
        String GROUP_KEY_WORK_EMAIL = "com.anyNews.anynews.Services.WORK_EMAIL";
        try {
            Intent resultIntent = new Intent(Intent.ACTION_SEND);
            resultIntent.setAction(Intent.ACTION_SEND);
            resultIntent.setType("video/*");
            resultIntent.setPackage("com.whatsapp");;
            File file = new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOCUMENTS), title);
            file.setReadable(true, true);
            Uri uriForFile = FileProvider.getUriForFile(context, context.getPackageName() + ".provider", file);
            showLog("file uri:"+uriForFile.getPath());
            resultIntent.putExtra(Intent.EXTRA_STREAM, uriForFile);
            List<ResolveInfo> resInfoList = context.getPackageManager().queryIntentActivities(Intent.createChooser(resultIntent, title), PackageManager.MATCH_DEFAULT_ONLY);
            for (ResolveInfo resolveInfo : resInfoList) {
                String packageName = resolveInfo.activityInfo.packageName;
                context.grantUriPermission(packageName, uriForFile, Intent.FLAG_GRANT_WRITE_URI_PERMISSION | Intent.FLAG_GRANT_READ_URI_PERMISSION);
            }
            resultIntent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
            showLog("FLAG_GRANT_READ_URI_PERMISSION:");
            context.startActivity(Intent.createChooser(resultIntent, "Share Link"));
            PendingIntent pendingIntent;
            if (Build.VERSION.SDK_INT >= 31) {
                pendingIntent = PendingIntent.getActivity(
                        getApplicationContext(),
                        10,
                        resultIntent,
                        PendingIntent.FLAG_IMMUTABLE | PendingIntent.FLAG_UPDATE_CURRENT // setting the mutability flag
                );
            } else {
                pendingIntent = PendingIntent.getActivity(context,
                        Integer.parseInt("10"), resultIntent, PendingIntent.FLAG_UPDATE_CURRENT);

            }
            try {

                NotificationCompat.Builder builder = new NotificationCompat.Builder(getApplicationContext(), Constants.Channel_ID)
                        // use xxxhdpi
                        .setSmallIcon(R.drawable.ic_arman_notificatio)
                        .setCustomContentView(collapsedView)
                        .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                        .setVibrate(new long[]{1000, 1000, 1000, 1000})
                        .setSound(uri)
                        .setShowWhen(true)
                        .setGroup(GROUP_KEY_WORK_EMAIL)
                        .setGroupSummary(false)
                        .setStyle(new NotificationCompat.DecoratedCustomViewStyle())
                        .setContentIntent(pendingIntent)
                        .setAutoCancel(true);

                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                    builder.setSmallIcon(R.drawable.ic_arman_notificatio);
                    builder.setColor(context.getResources().getColor(R.color.colorPrimary));
                } else {
                    builder.setSmallIcon(R.drawable.ic_arman_notificatio);
                }
                NotificationManagerCompat notificationManager = NotificationManagerCompat.from(getApplicationContext());

                int m = (int) ((new Date().getTime() / 1000L) % Integer.MAX_VALUE);
                //notificationManager.notify(random.nextInt(), builder.build());
                notificationManager.notify(m, builder.build());
            } catch (Exception e) {
                Log.v("NotificationData", String.valueOf(e.getMessage()));
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Live FlipView page currently on screen (or null). Used by ad in-place paint
     * to re-find {@code fl_adplaceholder} after WeakReference loss without a full
     * adapter notify (avoids every-scroll blink).
     */
    @Nullable
    public View getCurrentFlipPageView() {
        try {
            if (mFlipView != null) {
                return mFlipView.getCurrentPageView();
            }
        } catch (Exception ignored) {
        }
        return null;
    }

    /**
     * True while FlipView is mid-gesture / scrolling. Ad fill rebinds must wait —
     * {@code notifyDataSetChanged} recycles all pages and hitchs the 3D flip.
     */
    public boolean isNewsFlipAnimating() {
        try {
            boolean animating = mFlipView != null && mFlipView.isFlipAnimating();
            FlipAdWorkGate.setFlipAnimating(animating);
            return animating;
        } catch (Exception e) {
            FlipAdWorkGate.setFlipAnimating(false);
            return false;
        }
    }

    /**
     * True while the user is dragging or the fling scroller is running.
     * Pagination / ad rebind must wait — a recycle in this window snaps to page 0.
     */
    public boolean isNewsUserDrivingFlip() {
        try {
            return mFlipView != null && mFlipView.isUserDrivingFlip();
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Feed append / soft-merge: update FlipView page count without recycling the
     * visible card ({@code dataSetChanged} → forceRebind blink).
     */
    public void notifyFlipPageCountGrewQuietly() {
        try {
            if (mFlipView != null) {
                mFlipView.pageCountGrewQuietly();
            }
        } catch (Exception ignored) {
        }
    }

    /** True while flip gesture / settle-grace says AdMob work must wait. */
    public boolean shouldDeferAdWork() {
        try {
            isNewsFlipAnimating(); // sync gate from FlipView
        } catch (Exception ignored) {
        }
        return FlipAdWorkGate.shouldDeferAdWork();
    }

    /** Cancel coalesced AdMob prefetch scheduled from settle / refill. */
    private void cancelPendingAdPrefetch() {
        try {
            if (pendingAdPrefetchRunnable != null) {
                adPrefetchHandler.removeCallbacks(pendingAdPrefetchRunnable);
                pendingAdPrefetchRunnable = null;
            }
        } catch (Exception ignored) {
        }
    }

    /** Cancel post-settle AdMob load / refill / MediaView bind. */
    private void cancelPendingSettledAdWork() {
        try {
            if (pendingSettledAdWorkRunnable != null) {
                adPrefetchHandler.removeCallbacks(pendingSettledAdWorkRunnable);
                pendingSettledAdWorkRunnable = null;
            }
            pendingSettledAdWorkPos = -1;
        } catch (Exception ignored) {
        }
    }

    /** Bumped only on genuine feed replace / destroy so obsolete deferred starts are dropped. */
    private int adLoaderGeneration = 0;
    /** Positions queued for AdLoader start but not yet marked in-flight / SDK-hit. */
    private final java.util.HashSet<Integer> pendingNativeLoadStarts = new java.util.HashSet<>();

    private void onNewFlipCancelPendingAdWork() {
        FlipAdWorkGate.noteFlipInteraction();
        // A flip makes work less urgent, not obsolete. Keeping valid queued/ready inventory
        // prevents a fast swipe from repeatedly cancelling paid native preloads.
        // Settled work is rescheduled on land via scheduleSettledAdWork — do not leave the
        // seat without an on-settle ensure.
        cancelPendingAdPrefetch();
        cancelPendingSettledAdWork();
        try {
            flipSettleHandler.removeCallbacks(flipSafeAdRebindRunnable);
            pendingFlipSafeAdRebind = false;
        } catch (Exception ignored) {
        }
        // Do NOT warm AdLoader / AdPreloader here. onFlippedToPage runs mid-animation
        // (FlipView.dispatchDraw); ensureFeedNativeAdLoaded on the UI thread hitchs
        // Camera flip frames. Reliability path is scheduleSettledAdWork after land.
    }

    /**
     * Best-effort mid-flip warm for the next upcoming ad seat only. Never mutates
     * {@code ad_req_position}, never marks a seat permanently failed, and never
     * replaces {@link #runSettledAdWork} — on-land ensure always runs after settle.
     * Prefer claiming an existing AdPreloader creative over starting a new AdLoader.
     */
    private void warmNextAdSeatDuringFlip() {
        // Never start AdLoader / ensureFeedNativeAdLoaded mid-gesture — that is a
        // primary hitch on fast flips. Shared pool soft-warm only; on-land
        // scheduleSettledAdWork owns the reliability seat request.
        if (isNewsFlipAnimating() || isNewsUserDrivingFlip()) {
            try {
                if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                    AdPreloader.get().prefetch(getApplicationContext());
                }
            } catch (Exception ignored) {
            }
            return;
        }
        if (list == null || list.isEmpty()) {
            return;
        }
        if (isSearchFeedActive() || searchFeedActive) {
            return;
        }
        if (FeedAdConfig.isInterstitial(this)) {
            return;
        }
        // Warm pool can cover the next seat — skip a duplicate AdLoader.
        // Do NOT bail merely because AdPreloader isLoading: that blocked the July
        // on-seat path while primary refill was in-flight/no-fill, leaving Share.
        if (AdPreloader.get().readyCount() > 0) {
            return;
        }
        int from = Math.max(0, positionx);
        try {
            if (mFlipView != null) {
                int cur = mFlipView.getCurrentPage();
                if (cur >= 0) from = cur;
            }
        } catch (Exception ignored) {
        }
        int look = getAdPrefetchLookahead();
        int end = Math.min(list.size() - 1, from + look);
        final int maxWarmSeats = 1;
        int warmed = 0;
        try {
            for (int i = from; i <= end && warmed < maxWarmSeats; i++) {
                ModelClass.Datum d = list.get(i);
                if (d == null || !ReadArticleStore.isAdFeedSlot(d)) {
                    continue;
                }
                if (hasLoadedNativeForSlot(d)) {
                    continue;
                }
                Integer pos = d.getAd_req_position();
                if (pos == null) {
                    continue;
                }
                String code = d.getAd_code();
                if (code == null || code.isEmpty()) {
                    code = d.getNext_req_ad_code();
                }
                showLog("warmNextAdSeatDuringFlip best-effort flip=" + i
                        + " reqPos=" + pos + " seat=" + (warmed + 1));
                ensureFeedNativeAdLoaded(code, pos, d.getAd_type());
                warmed++;
            }
            // If no concrete seat was in range, soft-warm the shared pool once.
            if (warmed == 0) {
                AdPreloader.get().prefetch(getApplicationContext());
            }
        } catch (Exception e) {
            showLog("warmNextAdSeatDuringFlip: " + e.getMessage());
        }
    }

    /**
     * After settle grace: current-seat ensure + lookahead prefetch + optional refill.
     * Cancelled if the user flips again before the delay elapses.
     */
    private void scheduleSettledAdWork(int position) {
        cancelPendingSettledAdWork();
        pendingSettledAdWorkPos = position;
        final int pos = position;
        pendingSettledAdWorkRunnable = new Runnable() {
            @Override
            public void run() {
                if (isFinishing() || isDestroyed()) {
                    pendingSettledAdWorkRunnable = null;
                    pendingSettledAdWorkPos = -1;
                    return;
                }
                if (pos != positionx) {
                    pendingSettledAdWorkRunnable = null;
                    pendingSettledAdWorkPos = -1;
                    return;
                }
                if (shouldDeferAdWork()) {
                    long wait = Math.max(48L, FlipAdWorkGate.millisUntilAdWorkSafe());
                    adPrefetchHandler.postDelayed(this, wait);
                    return;
                }
                pendingSettledAdWorkRunnable = null;
                pendingSettledAdWorkPos = -1;
                runSettledAdWork(pos);
            }
        };
        long wait = Math.max(
                AD_WORK_AFTER_SETTLE_MS, FlipAdWorkGate.millisUntilAdWorkSafe());
        adPrefetchHandler.postDelayed(pendingSettledAdWorkRunnable, wait);
    }

    /**
     * Idle-only ad path: fill current seat, prefetch lookahead, refill pool, paint
     * deferred MediaView. Must not run mid-fling. This is the reliability path —
     * always request the landed ad seat even if mid-flip warm failed or was capped.
     */
    private void runSettledAdWork(int position) {
        if (list == null || position < 0 || position >= list.size()) {
            return;
        }
        // Keyword search: no in-feed native seats / AdPreloader fills.
        if (isSearchFeedActive() || searchFeedActive) {
            return;
        }
        if (shouldDeferAdWork()) {
            scheduleSettledAdWork(position);
            return;
        }
        try {
            if (adapter != null) {
                // July-era: attach deferred buffer MediaView when user lands.
                adapter.bindPendingNativeAdMediaForPage(position);
            }
        } catch (Exception ignored) {
        }
        String postTypeAtPos = list.get(position).getPostType();
        if (postTypeAtPos != null && postTypeAtPos.equalsIgnoreCase("ad")) {
            showLog("SETTLED AD work Loading pos=" + position);
            try {
                ModelClass.Datum seat = list.get(position);
                String code = seat.getAd_code();
                if (code == null || code.isEmpty()) {
                    code = seat.getNext_req_ad_code();
                }
                Integer reqPos = seat.getAd_req_position();
                String type = seat.getAd_type();
                // Unlock prior warm/cap/backoff failures so land always gets a real request
                // unless an SDK load is already in flight for this seat.
                if (reqPos != null) {
                    boolean googleSeat = type == null
                            || "google".equalsIgnoreCase(type)
                            || "admanager".equalsIgnoreCase(type);
                    if (googleSeat) {
                        String resolved = resolveGoogleNativeAdUnit(code);
                        String coordType = type == null ? "google" : type;
                        NativeAdCacheCoordinator.get().allowSettleRetry(
                                coordType, resolved, reqPos);
                        // Orphan in-flight marker with no creative and no coordinator flight → clear.
                        if (nativeGoogleAdArray != null
                                && nativeGoogleAdArray.contains(reqPos)
                                && !hasExactLoadedNativeForSlot(seat)
                                && !NativeAdCacheCoordinator.get().isInFlight(
                                        coordType, resolved, reqPos)
                                && !pendingNativeLoadStarts.contains(reqPos)) {
                            nativeGoogleAdArray.remove(reqPos);
                            showLog("SETTLED AD cleared orphan in-flight marker reqPos=" + reqPos);
                        }
                    }
                }
                ensureFeedNativeAdLoaded(code, reqPos, type);
                // Interstitial: show full-screen when landed on an ad seat (cadence = every N).
                maybeShowFeedInterstitialForSlot(seat);
            } catch (Exception ignored) {
            }
            // Prefer paint of any ready warm creative onto the parked Share/house seat.
            try {
                if (adapter != null) {
                    scheduleFlipSafeAdRebind();
                }
            } catch (Exception ignored) {
            }
            // Do not loadAds(next_req) here — prefetchUpcoming covers the next 1–2
            // seats without a duplicate AdLoader for the same ahead inventory.
        }
        prefetchUpcomingNativeAds(position, getAdPrefetchLookahead());
        // Soft top-up of shared warm only when empty (refill after claim owns the rest).
        try {
            if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                AdPreloader.get().prefetch(getApplicationContext());
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * Coalesced ad rebind after fill/restore. Prefers in-place paint; never runs a
     * full FlipView recycle while the flip animation is active.
     */
    public void scheduleFlipSafeAdRebind() {
        scheduleFlipSafeAdRebind(0L);
    }

    private void scheduleFlipSafeAdRebind(long delayMs) {
        try {
            flipSettleHandler.removeCallbacks(flipSafeAdRebindRunnable);
            pendingFlipSafeAdRebind = true;
            long wait = Math.max(0L, delayMs);
            if (shouldDeferAdWork()) {
                wait = Math.max(wait, FlipAdWorkGate.millisUntilAdWorkSafe());
                if (wait < 64L) {
                    wait = 64L;
                }
            }
            flipSettleHandler.postDelayed(flipSafeAdRebindRunnable, wait);
        } catch (Exception ignored) {
        }
    }

    private void loadAds(String ad_code, Integer ad_req_position, String ad_type) {
        if (isSearchFeedActive() || searchFeedActive) {
            return;
        }
        if (ad_req_position == null) {
            Log.w(ADS_TAG, "request skip missing reqPos type=" + ad_type);
            return;
        }
        if (ad_type == null || ad_type.trim().isEmpty()) {
            ad_type = "google";
        }
        Log.d(ADS_TAG, "request route ad_type=" + ad_type + " server_ad_code="
                + (ad_code == null ? "" : ad_code.trim()) + " reqPos=" + ad_req_position);
       // ad_code="/21833905170,23071623886/Anynews_APP_Banner_300x600";
        //ad_code="/21833905170,23071623886/Anynews_New_Native_DU";
       //new RequestConfiguration.Builder().setTestDeviceIds(Arrays.asList("CEB66515B6C9B2ECD92786955DF252CD"));
//        showLog("Ad loading ad_code 2 :"+ad_code);
       // ad_type="google";
        if(ad_type.equalsIgnoreCase("google") || ad_type.equalsIgnoreCase("admanager")){
            // Gate only on ad_req_position (not flip index). Mixing positionx into
            // nativeGoogleAdArray caused false skips / duplicate loads after push land.
            if (nativeGoogleAdArray != null && nativeGoogleAdArray.contains(ad_req_position)) {
                return;
            }
            int reqType = FeedAdConfig.isInterstitial(this) ? 1 : 0;
            loadGoogleAds(ad_code, ad_req_position, reqType);
        }else{
            if (ad_code == null || ad_code.trim().isEmpty()) {
                Log.w(ADS_TAG, "request skip empty Facebook placement reqPos=" + ad_req_position);
                return;
            }
            if (nativeFBAdArray != null && nativeFBAdArray.contains(ad_req_position)) {
                return;
            }
            loadFBAds(ad_code, ad_req_position);
        }

    }

    /**
     * Public for FlipperAdapter ad shells: load a native creative for a concrete
     * slot. Avoids permanent share fallback. Does not re-fire while a request for
     * this position is already in-flight (tracked by {@link #nativeGoogleAdArray}).
     */
    public void ensureFeedNativeAdLoaded(
            @Nullable String adCode,
            @Nullable Integer adReqPosition,
            @Nullable String adType) {
        if (isSearchFeedActive() || searchFeedActive) {
            return;
        }
        if (adReqPosition == null) {
            Log.w(ADS_TAG, "ensure skip missing reqPos");
            return;
        }
        try {
            String type = adType != null ? adType : "google";
            if (!type.equalsIgnoreCase("google") && !type.equalsIgnoreCase("admanager")
                    && (adCode == null || adCode.trim().isEmpty())) {
                Log.w(ADS_TAG, "ensure skip empty Facebook placement reqPos=" + adReqPosition);
                return;
            }
            if (type.equalsIgnoreCase("google") || type.equalsIgnoreCase("admanager")) {
                final boolean interstitialMode = FeedAdConfig.isInterstitial(this);
                if (nativeGoogleAdList != null) {
                    for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                        FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                        if (packed != null
                                && packed.getReqPos() == adReqPosition
                                && (packed.getAd() != null
                                        || packed.getInterstitialAd() != null)) {
                            return;
                        }
                    }
                }
                // Already requested this position this session — wait for fill/fail.
                if (nativeGoogleAdArray != null && nativeGoogleAdArray.contains(adReqPosition)) {
                    return;
                }
                if (pendingNativeLoadStarts.contains(adReqPosition)) {
                    return;
                }
                // AdPreloader is best-effort warm only (Play Store / July fill path is
                // always per-seat AdLoader). Rebind may claim a warm creative for
                // faster paint — never skip loadAds because the pool looks ready.
                // Skipping the current seat when isReady() left Share forever when
                // rebind failed to claim / primary warm refill no-filled.
                if (!interstitialMode) {
                    try {
                        if (AdPreloader.get().isReady()) {
                            scheduleFlipSafeAdRebind();
                        }
                    } catch (Exception ignored) {
                    }
                }
            } else {
                if (nativeFBAdList != null) {
                    for (int i = 0; i < nativeFBAdList.size(); i++) {
                        FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                        if (packed != null
                                && packed.getReqPos() == adReqPosition
                                && packed.getFbAd() != null) {
                            return;
                        }
                    }
                }
                if (nativeFBAdArray != null && nativeFBAdArray.contains(adReqPosition)) {
                    return;
                }
            }
            String resetCode = adCode;
            if (type.equalsIgnoreCase("google") || type.equalsIgnoreCase("admanager")) {
                resetCode = resolveGoogleNativeAdUnit(adCode);
            }
            NativeAdCacheCoordinator.get().resetSlotFailure(type, resetCode, adReqPosition);
            loadAds(adCode, adReqPosition, type);
        } catch (Exception e) {
            showLog("ensureFeedNativeAdLoaded: " + e.getMessage());
        }
    }

    /**
     * FlipperAdapter: soft fill window elapsed with no creative. Keep the seat
     * as {@code ad} + house placeholder (never permanent {@code share_app} /
     * WhatsApp promo demotion — that thrashed FlipView and killed late fills).
     * Optionally nudge one more load for this seat when under the concurrent cap.
     */
    public void onUnfilledAdShellTimedOut(int listPosition) {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                keepUnfilledAdShellAsHousePlaceholder(listPosition);
            }
        });
    }

    private boolean hasLoadedNativeForSlot(@Nullable ModelClass.Datum slot) {
        if (slot == null) {
            return false;
        }
        Integer slotPos = slot.getAd_req_position();
        if (slotPos == null) {
            return false;
        }
        try {
            if (hasExactLoadedNativeForSlot(slot)) {
                return true;
            }
            return hasClaimableReadyNativeForSlot(slotPos);
        } catch (Exception ignored) {
        }
        return false;
    }

    /** True if an exact-position creative exists (no pool transfer peek). */
    private boolean hasExactLoadedNativeForSlot(@Nullable ModelClass.Datum slot) {
        if (slot == null) {
            return false;
        }
        Integer slotPos = slot.getAd_req_position();
        if (slotPos == null) {
            return false;
        }
        try {
            if (nativeGoogleAdList != null) {
                for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed != null
                            && packed.getReqPos() == slotPos
                            && (packed.getAd() != null
                                    || packed.getInterstitialAd() != null)) {
                        return true;
                    }
                }
            }
            if (nativeFBAdList != null) {
                for (int i = 0; i < nativeFBAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed != null && packed.getFbAd() != null
                            && packed.getReqPos() == slotPos) {
                        return true;
                    }
                }
            }
        } catch (Exception ignored) {
        }
        return false;
    }

    /**
     * Peek: unclaimed creative that FlipperAdapter may transfer (orphan or ahead
     * of {@code slotPos}). Does not mutate.
     */
    private boolean hasClaimableReadyNativeForSlot(int slotPos) {
        try {
            java.util.HashSet<Integer> liveAdPositions = new java.util.HashSet<>();
            if (list != null) {
                for (int i = 0; i < list.size(); i++) {
                    ModelClass.Datum d = list.get(i);
                    if (d == null || d.getPostType() == null
                            || !d.getPostType().equalsIgnoreCase("ad")) {
                        continue;
                    }
                    Integer p = d.getAd_req_position();
                    if (p != null) {
                        liveAdPositions.add(p);
                    }
                }
            }
            if (nativeGoogleAdList != null) {
                for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed == null || packed.getAd() == null || packed.isClaimed()) {
                        continue;
                    }
                    int packedPos = packed.getReqPos();
                    if (!liveAdPositions.contains(packedPos) || packedPos > slotPos) {
                        return true;
                    }
                }
            }
            if (nativeFBAdList != null) {
                for (int i = 0; i < nativeFBAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed == null || packed.getFbAd() == null || packed.isClaimed()) {
                        continue;
                    }
                    if (packed.getReqPos() > slotPos) {
                        return true;
                    }
                }
            }
        } catch (Exception ignored) {
        }
        return false;
    }

    private int countReadyUnclaimedNatives() {
        int n = 0;
        try {
            if (nativeGoogleAdList != null) {
                for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed != null && packed.getAd() != null
                            && !packed.isClaimed() && !packed.isImpressed()) {
                        n++;
                    }
                }
            }
            if (nativeFBAdList != null) {
                for (int i = 0; i < nativeFBAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed != null && packed.getFbAd() != null
                            && !packed.isClaimed() && !packed.isImpressed()) {
                        n++;
                    }
                }
            }
        } catch (Exception ignored) {
        }
        return n;
    }

    /**
     * Donor seat lost its creative to a nearer empty seat — kick a refill load
     * for the donor and keep the pool topped up.
     */
    public void onNativeAdPoolReassigned(int fromReqPos, int toReqPos) {
        showLog("native pool reassign " + fromReqPos + " → " + toReqPos);
        try {
            refillNativeAdPoolAfterConsume();
        } catch (Exception ignored) {
        }
    }

    /**
     * After a creative is claimed/impressed/destroyed, immediately top the shared
     * warm pool and seat prefetch within lookahead. No stretch-beyond-lookahead
     * walks — those doubled AdLoader work and janked flip.
     */
    public void refillNativeAdPoolAfterConsume() {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        try {
            // Replenish shared warm only when empty (after claim/show).
            if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                AdPreloader.get().prefetch(getApplicationContext());
            }
        } catch (Exception ignored) {
        }
        if (list == null || list.isEmpty()) {
            return;
        }
        try {
            if (shouldDeferAdWork()) {
                try {
                    warmNextAdSeatDuringFlip();
                } catch (Exception ignored) {
                }
                return;
            }
            int ready = countReadyUnclaimedNatives();
            int inFlight = countInFlightNativeAdLoads();
            int preloaderReady = AdPreloader.get().readyCount();
            int target = getMaxNativeAdLoadsInFlight();
            showLog("refillNativeAdPool ready=" + ready + " inFlight=" + inFlight
                    + " preloader=" + preloaderReady + " target=" + target);
            // Count warm inventory toward coverage — do not abort seat refill merely
            // because AdPreloader has 1 creative (primary_only Share-after-first bug).
            if (ready + inFlight + preloaderReady >= target) {
                return;
            }
            int from = Math.max(0, positionx);
            try {
                if (mFlipView != null) {
                    int cur = mFlipView.getCurrentPage();
                    if (cur >= 0) from = cur;
                }
            } catch (Exception ignored) {
            }
            prefetchUpcomingNativeAds(from, getAdPrefetchLookahead());
        } catch (Exception e) {
            showLog("refillNativeAdPoolAfterConsume: " + e.getMessage());
        }
    }

    /**
     * Hard wipe of Google/FB seat pools + AdPreloader. Use only on Activity destroy /
     * offline reload teardown — not on ordinary News↔Local↔Flash↔Special switches
     * (those must keep the shared warm unimpressed pool via
     * {@link #pruneImpressedNativeAdsKeepWarm()}).
     */
    private void clearNativeAdPools() {
        try {
            // Genuine destruction boundary. Queued starts for the previous list are obsolete;
            // ordinary flips deliberately do not reach here.
            adLoaderGeneration++;
            pendingNativeLoadStarts.clear();
            NativeAdCacheCoordinator.get().clearAll();
            try {
                AdPreloader.get().clear();
            } catch (Exception ignored) {
            }
            adShellPoolGraceUsed.clear();
            if (nativeGoogleAdList != null) {
                for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed == null) continue;
                    try {
                        packed.setClaimed(false);
                        packed.setImpressed(false);
                        if (packed.getAd() != null) {
                            packed.getAd().destroy();
                            packed.setAd(null);
                        }
                    } catch (Exception ignored) {
                    }
                    try {
                        if (packed.getFbAd() != null) {
                            packed.getFbAd().destroy();
                            packed.setFbAd(null);
                        }
                    } catch (Exception ignored) {
                    }
                }
                nativeGoogleAdList.clear();
            }
            if (nativeFBAdList != null) {
                for (int i = 0; i < nativeFBAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed == null) continue;
                    try {
                        packed.setClaimed(false);
                        packed.setImpressed(false);
                        if (packed.getFbAd() != null) {
                            packed.getFbAd().destroy();
                            packed.setFbAd(null);
                        }
                    } catch (Exception ignored) {
                    }
                }
                nativeFBAdList.clear();
            }
            if (nativeGoogleAdArray != null) {
                nativeGoogleAdArray.clear();
            }
            feedInterstitialShownPos.clear();
            if (nativeFBAdArray != null) {
                nativeFBAdArray.clear();
            }
            if (adapter != null) {
                adapter.resetAdBindState();
            }
        } catch (Exception e) {
            showLog("clearNativeAdPools: " + e.getMessage());
            try {
                if (nativeGoogleAdList != null) nativeGoogleAdList.clear();
                if (nativeFBAdList != null) nativeFBAdList.clear();
                if (nativeGoogleAdArray != null) nativeGoogleAdArray.clear();
                if (nativeFBAdArray != null) nativeFBAdArray.clear();
            } catch (Exception ignored) {
            }
        }
    }

    /**
     * Feed-mode switch (News / Local / Flash / Special / search): destroy only
     * claimed or impressed creatives, keep warm unimpressed seat-pool + AdPreloader
     * inventory so the next feed can claim immediately. Cancels in-flight start
     * markers for the previous list without wiping the shared warm preloader.
     */
    private void pruneImpressedNativeAdsKeepWarm() {
        try {
            adLoaderGeneration++;
            pendingNativeLoadStarts.clear();
            NativeAdCacheCoordinator.get().clearAll();
            // Intentionally do NOT AdPreloader.clear() — shared warm pool survives mode switch.
            adShellPoolGraceUsed.clear();
            feedInterstitialShownPos.clear();
            pruneGoogleListKeepUnimpressed();
            pruneFbListKeepUnimpressed();
            if (nativeGoogleAdArray != null) {
                nativeGoogleAdArray.clear();
            }
            if (nativeFBAdArray != null) {
                nativeFBAdArray.clear();
            }
            // Re-register remaining unclaimed Google reqPos so ensure/dedupe stays coherent.
            if (nativeGoogleAdList != null && nativeGoogleAdArray != null) {
                for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed == null || packed.getAd() == null || packed.isClaimed()
                            || packed.isImpressed()) {
                        continue;
                    }
                    int pos = packed.getReqPos();
                    if (!nativeGoogleAdArray.contains(pos)) {
                        nativeGoogleAdArray.add(pos);
                    }
                }
            }
            if (nativeFBAdList != null && nativeFBAdArray != null) {
                for (int i = 0; i < nativeFBAdList.size(); i++) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed == null || packed.getFbAd() == null || packed.isClaimed()
                            || packed.isImpressed()) {
                        continue;
                    }
                    int pos = packed.getReqPos();
                    if (!nativeFBAdArray.contains(pos)) {
                        nativeFBAdArray.add(pos);
                    }
                }
            }
            if (adapter != null) {
                adapter.resetAdBindState();
            }
            try {
                if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                    AdPreloader.get().prefetch(getApplicationContext());
                }
            } catch (Exception ignored) {
            }
            showLog("pruneImpressedNativeAdsKeepWarm googleWarm="
                    + (nativeGoogleAdList != null ? nativeGoogleAdList.size() : 0)
                    + " preloader=" + AdPreloader.get().readyCount());
        } catch (Exception e) {
            showLog("pruneImpressedNativeAdsKeepWarm: " + e.getMessage());
        }
    }

    private void pruneGoogleListKeepUnimpressed() {
        if (nativeGoogleAdList == null || nativeGoogleAdList.isEmpty()) {
            return;
        }
        for (int i = nativeGoogleAdList.size() - 1; i >= 0; i--) {
            FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
            if (packed == null) {
                nativeGoogleAdList.remove(i);
                continue;
            }
            boolean used = packed.isClaimed() || packed.isImpressed();
            boolean empty = packed.getAd() == null && packed.getInterstitialAd() == null
                    && packed.getFbAd() == null;
            if (!used && !empty) {
                continue;
            }
            // Always destroy claimed/impressed on mode switch (money-safe). Keeping
            // them under admin destroy-OFF allowed flip/tab return to early-keep the
            // same already-paid NativeAd object with no new AdMob impression.
            try {
                if (packed.getAd() != null) {
                    packed.getAd().destroy();
                    packed.setAd(null);
                }
            } catch (Exception ignored) {
            }
            try {
                if (packed.getFbAd() != null) {
                    packed.getFbAd().destroy();
                    packed.setFbAd(null);
                }
            } catch (Exception ignored) {
            }
            packed.setInterstitialAd(null);
            packed.setClaimed(false);
            packed.setImpressed(false);
            nativeGoogleAdList.remove(i);
        }
    }

    private void pruneFbListKeepUnimpressed() {
        if (nativeFBAdList == null || nativeFBAdList.isEmpty()) {
            return;
        }
        for (int i = nativeFBAdList.size() - 1; i >= 0; i--) {
            FlipGoogleNativeAds packed = nativeFBAdList.get(i);
            if (packed == null) {
                nativeFBAdList.remove(i);
                continue;
            }
            boolean used = packed.isClaimed() || packed.isImpressed();
            boolean empty = packed.getFbAd() == null;
            if (!used && !empty) {
                continue;
            }
            try {
                if (packed.getFbAd() != null) {
                    packed.getFbAd().destroy();
                    packed.setFbAd(null);
                }
            } catch (Exception ignored) {
            }
            packed.setClaimed(false);
            packed.setImpressed(false);
            nativeFBAdList.remove(i);
        }
    }

    /**
     * Mark the packed Google native for {@code reqPos} as impressed (one paid show).
     * Flip-away destroys it so flip-back requests a fresh fill — no seat-sticky
     * same creative. Kick a replacement into the shared warm pool for upcoming
     * empty seats.
     */
    public void markGoogleNativeImpressed(@Nullable Integer reqPos) {
        if (reqPos == null || nativeGoogleAdList == null) {
            return;
        }
        try {
            for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                if (packed != null && packed.getReqPos() == reqPos && packed.getAd() != null) {
                    packed.setImpressed(true);
                    packed.setClaimed(true);
                    showLog("native impressed reqPos=" + reqPos);
                    try {
                        refillNativeAdPoolAfterConsume();
                    } catch (Exception ignored) {
                    }
                    return;
                }
            }
        } catch (Exception ignored) {
        }
    }

    /** Mark the packed FB native for {@code reqPos} as impressed. */
    public void markFbNativeImpressed(@Nullable Integer reqPos) {
        if (reqPos == null || nativeFBAdList == null) {
            return;
        }
        try {
            for (int i = 0; i < nativeFBAdList.size(); i++) {
                FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                if (packed != null && packed.getReqPos() == reqPos && packed.getFbAd() != null) {
                    packed.setImpressed(true);
                    packed.setClaimed(true);
                    showLog("fb native impressed reqPos=" + reqPos);
                    try {
                        refillNativeAdPoolAfterConsume();
                    } catch (Exception ignored) {
                    }
                    return;
                }
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * After settle: destroy claimed/impressed natives whose seat is not the
     * current Flip page (fresh fill on return). Gated by admin
     * {@code destroy_native_ads_after_impression} (default OFF for Play-smooth
     * seat-sticky). When OFF this is a no-op — unpaid cross-seat reuse stays
     * blocked via reqPos + claim-once in FlipperAdapter. Unimpressed warm pool
     * + AdPreloader stay intact. Never call mid-flip.
     */
    public void destroyOffscreenImpressedNatives(int currentPage) {
        if (isFinishing() || isDestroyed()) {
            return;
        }
        if (!FeedAdConfig.isDestroyAfterImpression(this)) {
            return;
        }
        Integer currentSeatReqPos = null;
        try {
            if (list != null && currentPage >= 0 && currentPage < list.size()) {
                ModelClass.Datum cur = list.get(currentPage);
                if (cur != null && cur.getPostType() != null
                        && cur.getPostType().equalsIgnoreCase("ad")) {
                    currentSeatReqPos = cur.getAd_req_position();
                }
            }
        } catch (Exception ignored) {
        }
        boolean destroyedAny = false;
        try {
            if (nativeGoogleAdList != null) {
                for (int i = nativeGoogleAdList.size() - 1; i >= 0; i--) {
                    FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                    if (packed == null || packed.getAd() == null) {
                        continue;
                    }
                    if (!packed.isClaimed() && !packed.isImpressed()) {
                        continue;
                    }
                    int oldPos = packed.getReqPos();
                    // Still on this seat — keep until the user flips away.
                    if (currentSeatReqPos != null
                            && currentSeatReqPos.intValue() == oldPos) {
                        continue;
                    }
                    try {
                        packed.getAd().destroy();
                    } catch (Exception ignored) {
                    }
                    String destroyedCode = packed.getAdCode();
                    packed.setAd(null);
                    packed.setClaimed(false);
                    packed.setImpressed(false);
                    nativeGoogleAdList.remove(i);
                    try {
                        if (nativeGoogleAdArray != null) {
                            nativeGoogleAdArray.remove(Integer.valueOf(oldPos));
                        }
                    } catch (Exception ignored) {
                    }
                    try {
                        String coordCode = !TextUtils.isEmpty(destroyedCode)
                                ? destroyedCode.trim()
                                : FeedAdConfig.getUnitId(this);
                        NativeAdCacheCoordinator.get().onConsumed(
                                "google", coordCode, oldPos);
                        NativeAdCacheCoordinator.get().allowSettleRetry(
                                "google", coordCode, oldPos);
                    } catch (Exception ignored) {
                    }
                    destroyedAny = true;
                    showLog("destroy flip-away impressed google reqPos=" + oldPos);
                }
            }
            if (nativeFBAdList != null) {
                for (int i = nativeFBAdList.size() - 1; i >= 0; i--) {
                    FlipGoogleNativeAds packed = nativeFBAdList.get(i);
                    if (packed == null || packed.getFbAd() == null) {
                        continue;
                    }
                    if (!packed.isClaimed() && !packed.isImpressed()) {
                        continue;
                    }
                    int oldPos = packed.getReqPos();
                    if (currentSeatReqPos != null
                            && currentSeatReqPos.intValue() == oldPos) {
                        continue;
                    }
                    try {
                        packed.getFbAd().destroy();
                    } catch (Exception ignored) {
                    }
                    packed.setFbAd(null);
                    packed.setClaimed(false);
                    packed.setImpressed(false);
                    nativeFBAdList.remove(i);
                    try {
                        if (nativeFBAdArray != null) {
                            nativeFBAdArray.remove(Integer.valueOf(oldPos));
                        }
                    } catch (Exception ignored) {
                    }
                    destroyedAny = true;
                    showLog("destroy flip-away impressed fb reqPos=" + oldPos);
                }
            }
        } catch (Exception e) {
            showLog("destroyOffscreenImpressedNatives: " + e.getMessage());
        }
        if (destroyedAny) {
            try {
                refillNativeAdPoolAfterConsume();
            } catch (Exception ignored) {
            }
        }
    }

    /**
     * Keep unfilled seat as {@code ad} with house placeholder — no share_app demotion,
     * no flipTo / dataset thrash. Optionally nudge one more AdMob load if under cap.
     */
    private void keepUnfilledAdShellAsHousePlaceholder(int listPosition) {
        if (list == null || list.isEmpty()) {
            return;
        }
        if (listPosition < 0 || listPosition >= list.size()) {
            return;
        }
        ModelClass.Datum d = list.get(listPosition);
        if (d == null || !ReadArticleStore.isAdFeedSlot(d)) {
            return;
        }
        if (hasLoadedNativeForSlot(d)) {
            showLog("keep house — creative ready pos=" + listPosition
                    + " exact=" + hasExactLoadedNativeForSlot(d));
            try {
                scheduleFlipSafeAdRebind();
            } catch (Exception ignored) {
            }
            return;
        }
        showLog("keep unfilled ad seat as house placeholder pos=" + listPosition
                + " reqPos=" + d.getAd_req_position()
                + " ready=" + countReadyUnclaimedNatives()
                + " inFlight=" + countInFlightNativeAdLoads());
        // Always nudge another load — schedule if at cap so share UI is never permanent.
        try {
            String code = d.getAd_code();
            if (code == null || code.trim().isEmpty()) {
                code = d.getNext_req_ad_code();
            }
            Integer reqPos = d.getAd_req_position();
            String type = d.getAd_type();
            if (reqPos != null) {
                String typeSafe = type == null ? "google" : type;
                if ("google".equalsIgnoreCase(typeSafe)
                        || "admanager".equalsIgnoreCase(typeSafe)) {
                    String resolved = resolveGoogleNativeAdUnit(code);
                    NativeAdCacheCoordinator.get().allowSettleRetry(typeSafe, resolved, reqPos);
                }
            }
            if (countInFlightNativeAdLoads() < getMaxNativeAdLoadsInFlight()) {
                ensureFeedNativeAdLoaded(code, reqPos, type);
            } else if (reqPos != null) {
                scheduleBoundedNativeRetry(
                        code != null ? code : resolveGoogleNativeAdUnit(null),
                        reqPos,
                        type,
                        800L);
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * @deprecated Prefer {@link #keepUnfilledAdShellAsHousePlaceholder}. Kept so any
     * leftover call sites still avoid permanent WhatsApp {@code share_app} demotion.
     */
    private void convertUnfilledAdShellToShareApp(int listPosition) {
        keepUnfilledAdShellAsHousePlaceholder(listPosition);
    }

    /** No-op: permanent share_app demotion disabled (100% ad-seat intent). */
    private void mutateAdShellToShareApp(@Nullable ModelClass.Datum slot) {
        // Intentionally empty — do not replace ad seats with WhatsApp share promo.
    }

    /**
     * Drop an unfilled ad at {@code listPosition} and flip to the same index
     * (now the next card) or the first remaining content card.
     * Prefer {@link #convertUnfilledAdShellToShareApp} for user-visible timeout paths.
     */
    private void skipUnfilledAdShellAt(int listPosition) {
        if (list == null || list.isEmpty()) {
            resolveSoftEmptyNewsFeed("ad_skip_empty_list");
            return;
        }
        if (listPosition < 0 || listPosition >= list.size()) {
            return;
        }
        ModelClass.Datum d = list.get(listPosition);
        if (d == null || !ReadArticleStore.isAdFeedSlot(d)) {
            return;
        }
        if (hasLoadedNativeForSlot(d)) {
            // Race: fill arrived after timeout posted — rebind spinner page.
            try {
                scheduleFlipSafeAdRebind();
            } catch (Exception ignored) {
            }
            return;
        }
        showLog("skip unfilled ad shell at pos=" + listPosition
                + " reqPos=" + d.getAd_req_position()
                + " code=" + d.getAd_code());
        try {
            list.remove(listPosition);
        } catch (Exception e) {
            return;
        }
        // Chain-remove adjacent unfilled ads so we don't hop spinner→spinner.
        while (listPosition < list.size()) {
            ModelClass.Datum next = list.get(listPosition);
            if (next == null || !ReadArticleStore.isAdFeedSlot(next)) {
                break;
            }
            if (hasLoadedNativeForSlot(next)) {
                break;
            }
            showLog("chain-skip adjacent unfilled ad at pos=" + listPosition);
            list.remove(listPosition);
        }
        int paintables = ReadArticleStore.countPaintableArticles(list);
        if (list.isEmpty() || paintables == 0) {
            // Only shells/spinners left — keep paging or show empty; never hang.
            try {
                ensureHomeFlipAdapterBoundAndData(list);
            } catch (Exception ignored) {
            }
            resolveSoftEmptyNewsFeed("ad_skip_no_paintables");
            return;
        }
        int target = Math.min(listPosition, list.size() - 1);
        // Prefer landing on a non-ad if current was stripped mid-open.
        if (target >= 0 && target < list.size()
                && ReadArticleStore.isAdFeedSlot(list.get(target))
                && !hasLoadedNativeForSlot(list.get(target))) {
            int better = indexOfFirstPaintableOrFilledCard(list);
            if (better >= 0) {
                target = better;
            }
        }
        positionx = Math.max(0, target);
        try {
            ensureHomeFlipAdapterBoundAndData(list);
            if (mFlipView != null && !list.isEmpty()) {
                mFlipView.setVisibility(View.VISIBLE);
                if (layout_with_data != null) {
                    layout_with_data.setVisibility(View.VISIBLE);
                }
                if (txtNoData != null) {
                    txtNoData.setVisibility(View.GONE);
                }
                hideHomeFeedLoadingReveal(true);
                final int flipTo = positionx;
                if (adapter != null) {
                    adapter.setCurrentFlipPage(flipTo);
                }
                mFlipView.flipTo(flipTo);
            }
        } catch (Exception e) {
            showLog("skipUnfilledAdShellAt bind: " + e.getMessage());
        }
        try {
            maybePrefetchOnlineNewsIfNearEnd();
        } catch (Exception ignored) {
        }
    }

    /** First real/sticky card, or first ad that already has a creative. */
    private int indexOfFirstPaintableOrFilledCard(
            @Nullable java.util.List<ModelClass.Datum> items) {
        if (items == null || items.isEmpty()) {
            return -1;
        }
        for (int i = 0; i < items.size(); i++) {
            ModelClass.Datum d = items.get(i);
            if (d == null) {
                continue;
            }
            if (ReadArticleStore.isAdFeedSlot(d)) {
                if (hasLoadedNativeForSlot(d)) {
                    return i;
                }
                continue;
            }
            if (ReadArticleStore.isShareFeedSlot(d)) {
                return i;
            }
            if (d.getPostId() != null && d.getPostId() > 0) {
                return i;
            }
        }
        return items.isEmpty() ? -1 : 0;
    }

    /**
     * Mid skip-ahead / strip left no real cards: keep fetching next pages, or
     * surface offline/empty — never leave News/Special/Video on loading or an
     * unfilled ad spinner forever.
     */
    private void resolveSoftEmptyNewsFeed(String reason) {
        showLog("resolveSoftEmptyNewsFeed: " + reason
                + " streak=" + onlineNewsAllReadSkipStreak
                + " list=" + (list != null ? list.size() : -1)
                + " video=" + isVideoFeedMode()
                + " special=" + isSpecialFeedMode());
        // Keyword / single search must never soft-page into List_All_Articles loops.
        if (searchFeedActive
                && (activeSearchSingleOnly
                        || activeSearchPostId > 0L
                        || (activeSearchQuery != null
                                && !activeSearchQuery.trim().isEmpty()))) {
            showLog("ANYNEWS_SEARCH soft-empty diverted → finalize/abort (" + reason + ")");
            if (list == null) {
                list = new ArrayList<>();
            }
            if (ReadArticleStore.countPaintableArticles(list) > 0) {
                finalizeSearchFeedSeating(true);
            } else {
                abortKeywordSearchNoHits();
            }
            return;
        }
        try {
            if (canPageActiveOnlineFlipFeed()
                    && !bookmarksModeSelected
                    && onlineNewsAllReadSkipStreak < ONLINE_NEWS_ALL_READ_SKIP_CAP
                    && isDeviceOnline()) {
                if (txtNoData != null) {
                    txtNoData.setVisibility(View.GONE);
                }
                showHomeFeedLoadingReveal();
                // Clear hung in-flight flag so skip-ahead / timeout can re-request.
                isApiRequested = false;
                onlineNewsAllReadSkipStreak++;
                isApiRequested = true;
                final boolean videoPage = isVideoFeedMode();
                final boolean specialPage = isSpecialFeedMode();
                new Handler(Looper.getMainLooper()).post(new Runnable() {
                    @Override
                    public void run() {
                        if (isFinishing() || isDestroyed()) {
                            isApiRequested = false;
                            return;
                        }
                        // Mode may have changed while the post was pending.
                        if (!canPageActiveOnlineFlipFeed()
                                || bookmarksModeSelected
                                || videoPage != isVideoFeedMode()
                                || specialPage != isSpecialFeedMode()) {
                            isApiRequested = false;
                            finishEmptyNewsFeedUi();
                            return;
                        }
                        // Page-0 style replace when list is empty soft-empty; append when
                        // we already have shells / partial list (Video filtered empty etc.).
                        int req = (list == null || list.isEmpty()
                                || ReadArticleStore.countPaintableArticles(list) == 0)
                                ? 1 : 3;
                        ShowNews_Data_Values(category_id, req);
                    }
                });
                return;
            }
        } catch (Exception ignored) {
        }
        finishEmptyNewsFeedUi();
    }

    private void finishEmptyNewsFeedUi() {
        try {
            hideHomeFeedLoadingReveal(true);
            // Keep unfilled ad seats as house placeholders (no share_app demotion).
            if (list != null && !list.isEmpty()) {
                ensureHomeFlipAdapterBoundAndData(list);
                if (mFlipView != null) {
                    mFlipView.setVisibility(View.VISIBLE);
                }
                if (layout_with_data != null) {
                    layout_with_data.setVisibility(View.VISIBLE);
                }
                if (txtNoData != null) {
                    txtNoData.setVisibility(View.GONE);
                }
                try {
                    seatAwayFromUnfilledAdIfNeeded();
                } catch (Exception ignored) {
                }
                return;
            }
            if (mFlipView != null) {
                mFlipView.setVisibility(View.GONE);
            }
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null) {
                txtNoData.setVisibility(View.VISIBLE);
            }
            initialCall = true;
        } catch (Exception ignored) {
        }
    }

    /**
     * Soft timeout may have demoted an ad seat to {@code share_app} while AdMob was
     * still loading (esp. cold push). Metadata (ad_code / ad_req_position) is kept —
     * restore seat to {@code ad} when a matching creative arrives so income is not lost.
     * Also restores the nearest demoted seat when any unclaimed ready-pool creative exists.
     */
    private void maybeRestoreDemotedAdSeatsForFill(@Nullable Integer ad_req_position) {
        if (list == null || list.isEmpty()) {
            return;
        }
        try {
            boolean restored = false;
            boolean poolHasReady = countReadyUnclaimedNatives() > 0;
            for (int i = 0; i < list.size(); i++) {
                ModelClass.Datum d = list.get(i);
                if (d == null || !ReadArticleStore.isShareFeedSlot(d)) {
                    continue;
                }
                Integer slotPos = d.getAd_req_position();
                String code = d.getAd_code();
                if (code == null || code.trim().isEmpty()) {
                    code = d.getNext_req_ad_code();
                }
                // Only seats that were ad shells (still carry unit metadata).
                if (code == null || code.trim().isEmpty() || slotPos == null) {
                    continue;
                }
                boolean exactFill = ad_req_position != null && ad_req_position.equals(slotPos);
                // Pool path: any ready creative can serve the nearest demoted seat.
                if (!exactFill && !poolHasReady) {
                    continue;
                }
                if (!exactFill) {
                    // Prefer restoring seats near the current flip first.
                    int cur = positionx;
                    try {
                        if (mFlipView != null) {
                            cur = mFlipView.getCurrentPage();
                        }
                    } catch (Exception ignored) {
                    }
                    if (Math.abs(i - cur) > 2) {
                        continue;
                    }
                }
                try {
                    d.setPostType("ad");
                    restored = true;
                    showLog("restore demoted share_app → ad at pos=" + i
                            + " reqPos=" + slotPos
                            + (exactFill ? " (exact)" : " (pool)"));
                    if (!exactFill) {
                        // One pool restore per fill callback — avoid claiming all seats.
                        break;
                    }
                } catch (Exception ignored) {
                }
            }
            if (restored && adapter != null) {
                pendingFullAdRebind = true;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        scheduleFlipSafeAdRebind();
                    }
                });
            }
            if (poolHasReady || ad_req_position != null) {
                try {
                    refillNativeAdPoolAfterConsume();
                } catch (Exception ignored) {
                }
            }
        } catch (Exception e) {
            showLog("maybeRestoreDemotedAdSeatsForFill: " + e.getMessage());
        }
    }

    /**
     * Rebind when a creative arrives for the on-screen ad seat or a nearby FlipView
     * buffer seat (prev/next within 2). Critical so the buffered next page paints the
     * ad before the user flips — not a default placeholder → ad after settle.
     */
    private void maybeRebindCurrentAdAfterLoad(Integer ad_req_position) {
        try {
            if (adapter == null || mFlipView == null || list == null || list.isEmpty()) {
                return;
            }
            int cur = positionx;
            try {
                cur = mFlipView.getCurrentPage();
            } catch (Exception ignored) {
            }
            if (cur < 0 || cur >= list.size()) return;
            int from = Math.max(0, cur - 1);
            int to = Math.min(list.size() - 1, cur + 2);
            boolean shouldRebind = false;
            for (int i = from; i <= to; i++) {
                ModelClass.Datum d = list.get(i);
                if (d == null || d.getPostType() == null
                        || !d.getPostType().equalsIgnoreCase("ad")) {
                    continue;
                }
                Integer slotPos = d.getAd_req_position();
                if (ad_req_position != null && slotPos != null
                        && ad_req_position.equals(slotPos)) {
                    shouldRebind = true;
                    break;
                }
            }
            if (!shouldRebind) {
                return;
            }
            runOnUiThread(new Runnable() {
                @Override
                public void run() {
                    // Prefer in-place paint; only schedule a FlipView recycle when the
                    // seated ad still needs share/empty → creative layout swap.
                    try {
                        if (adapter != null && adapter.tryPaintReadyGoogleNativesInPlace()) {
                            return;
                        }
                    } catch (Exception ignored) {
                    }
                    scheduleFlipSafeAdRebind();
                }
            });
        } catch (Exception ignored) {
        }
    }
    private void scheduleSkipCurrentAdIfStillUnfilled(
            @Nullable Integer adReqPosition, long delayMs) {
        if (adReqPosition == null) {
            return;
        }
        // Load failed / still empty: keep house placeholder on the ad seat.
        // Do NOT demote to share_app (layout thrash + permanent WhatsApp promo).
        final long wait = Math.max(0L, delayMs);
        Runnable keepHouseIfStillUnfilled = new Runnable() {
            @Override
            public void run() {
                try {
                    if (isFinishing() || isDestroyed() || list == null || list.isEmpty()) {
                        return;
                    }
                    int cur = positionx;
                    try {
                        if (mFlipView != null) {
                            cur = mFlipView.getCurrentPage();
                        }
                    } catch (Exception ignored) {
                    }
                    if (cur < 0 || cur >= list.size()) {
                        return;
                    }
                    ModelClass.Datum d = list.get(cur);
                    if (d == null || !ReadArticleStore.isAdFeedSlot(d)) {
                        return;
                    }
                    Integer slotPos = d.getAd_req_position();
                    if (slotPos != null && !adReqPosition.equals(slotPos)) {
                        return;
                    }
                    if (hasLoadedNativeForSlot(d)) {
                        return;
                    }
                    showLog("ad load fail — keep house placeholder at flip="
                            + cur + " reqPos=" + adReqPosition);
                    keepUnfilledAdShellAsHousePlaceholder(cur);
                } catch (Exception ignored) {
                }
            }
        };
        if (wait <= 0L) {
            new Handler(Looper.getMainLooper()).post(keepHouseIfStillUnfilled);
        } else {
            new Handler(Looper.getMainLooper()).postDelayed(keepHouseIfStillUnfilled, wait);
        }
    }

    /**
     * Prefer admin/splash unit ({@link FeedAdConfig}); fall back to production native
     * string. Ignore Google test publisher units and empty/GAM-mismatched values when
     * the admin unit is unset — keep paid AdMob requests working.
     * <p>Interstitial mode must use an AdMob {@code ca-app-pub-…/…} unit — never a
     * GAM native path ({@code /network,unit/name}).
     */
    @NonNull
    private String resolveGoogleNativeAdUnit(@Nullable String configuredCode) {
        final boolean interstitial = FeedAdConfig.isInterstitial(this);
        String adminUnit = FeedAdConfig.getUnitId(this);
        if (!TextUtils.isEmpty(adminUnit)
                && !adminUnit.contains("3940256099942544")
                && !(interstitial && adminUnit.startsWith("/"))
                && !adminUnit.contains("~")) {
            Log.d(ADS_TAG, "resolved ad_code=" + adminUnit + " source=FeedAdConfig"
                    + " format=" + (interstitial ? "interstitial" : "native")
                    + " ignored_slot_ad_code=" + (configuredCode == null ? "" : configuredCode));
            return adminUnit;
        }
        String code = configuredCode == null ? "" : configuredCode.trim();
        if (!code.isEmpty()
                && !code.contains("3940256099942544")
                && !code.contains("~")
                && !(interstitial && code.startsWith("/"))) {
            Log.d(ADS_TAG, "resolved ad_code=" + code + " source=slot"
                    + " format=" + (interstitial ? "interstitial" : "native"));
            return code;
        }
        String fallback = getString(R.string.admob_native_ad_unit_fallback).trim();
        if (TextUtils.isEmpty(fallback)) {
            fallback = FeedAdConfig.DEFAULT_UNIT_ID;
        }
        Log.d(ADS_TAG, "resolved ad_code=" + fallback + " source=strings-fallback"
                + " format=" + (interstitial ? "interstitial" : "native")
                + " ignored_server_ad_code=" + code);
        return fallback;
    }

    /**
     * When admin format (or slot ad_screen_type) is interstitial, show a full-screen
     * ad at most once per seat. Frequency is still feed_ad_every_n (ad seats only).
     */
    private void maybeShowFeedInterstitialForSlot(@Nullable ModelClass.Datum slot) {
        if (slot == null || isFinishing() || isDestroyed()) return;
        boolean interstitial =
                FeedAdConfig.isInterstitial(this)
                        || "interstitial".equalsIgnoreCase(
                                slot.getAd_screen_type() == null
                                        ? ""
                                        : slot.getAd_screen_type().trim());
        if (!interstitial) return;
        Integer reqPos = slot.getAd_req_position();
        if (reqPos == null) return;
        if (feedInterstitialShownPos.contains(reqPos)) return;
        if (nativeGoogleAdList == null || nativeGoogleAdList.isEmpty()) return;
        InterstitialAd ready = null;
        int readyIndex = -1;
        for (int i = 0; i < nativeGoogleAdList.size(); i++) {
            FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
            if (packed == null || packed.getInterstitialAd() == null) continue;
            if (packed.getReqPos() == reqPos) {
                ready = packed.getInterstitialAd();
                readyIndex = i;
                break;
            }
            if (ready == null) {
                ready = packed.getInterstitialAd();
                readyIndex = i;
            }
        }
        if (ready == null) return;
        try {
            feedInterstitialShownPos.add(reqPos);
            if (readyIndex >= 0 && readyIndex < nativeGoogleAdList.size()) {
                FlipGoogleNativeAds packed = nativeGoogleAdList.get(readyIndex);
                if (packed != null) packed.setInterstitialAd(null);
            }
            Log.d(ADS_TAG, "show feed interstitial reqPos=" + reqPos);
            try {
                ready.setFullScreenContentCallback(
                        new com.google.android.gms.ads.FullScreenContentCallback() {
                            @Override
                            public void onAdImpression() {
                                adImpress = true;
                                Log.d(ADS_TAG, "interstitial onAdImpression reqPos=" + reqPos
                                        + " (AdMob Impressions / estimated earnings)");
                            }

                            @Override
                            public void onAdDismissedFullScreenContent() {
                                Log.d(ADS_TAG, "interstitial dismissed reqPos=" + reqPos);
                                try {
                                    // Restore in-feed chrome after overlay closes.
                                    if (!FeedAdConfig.isInterstitial(HomePage.this)) {
                                        ensureOnlineBottomNavVisible();
                                    }
                                } catch (Exception ignored) {
                                }
                            }
                        });
            } catch (Exception ignored) {
            }
            ready.show(this);
        } catch (Exception e) {
            feedInterstitialShownPos.remove(reqPos);
            Log.w(ADS_TAG, "feed interstitial show failed: " + e.getMessage());
        }
    }

    private void loadGoogleAds(String adCode, Integer ad_req_position,int reqType) {
        if (ad_req_position == null) {
            Log.w(ADS_TAG, "request skip missing position");
            return;
        }
        adCode = resolveGoogleNativeAdUnit(adCode);
        Log.d(ADS_TAG, "request start type=google format="
                + (reqType == 1 ? "interstitial" : "native")
                + " ad_code=" + adCode + " reqPos=" + ad_req_position);

        // Do NOT mark in-flight here — startNativeAdLoader may defer across flips.
        // Marking early left orphan positions that never retried after cancel.

        if(reqType==0){
            loadAdLoader(adCode,ad_req_position);

        }else if(reqType==1){
            // Interstitial path still needs a reservation marker.
            if (ad_req_position != null && nativeGoogleAdArray != null
                    && !nativeGoogleAdArray.contains(ad_req_position)) {
                nativeGoogleAdArray.add(ad_req_position);
            }
            loadInterstitialAd(adCode,ad_req_position);
        }

        showLog("Ad2 loading");
    }

    private void loadAdLoader(String adCode, Integer ad_req_position) {
        Log.e(TAG, "loadAdLoader: "+adCode );
        // AdLoader.Builder + loadAd are main-thread SDK entry points but must not run
        // synchronously on the flip gesture path — post so the current frame finishes.
        if (ad_req_position != null) {
            if (pendingNativeLoadStarts.contains(ad_req_position)
                    || (nativeGoogleAdArray != null
                    && nativeGoogleAdArray.contains(ad_req_position))) {
                return;
            }
            pendingNativeLoadStarts.add(ad_req_position);
        }
        final String code = adCode;
        final Integer reqPos = ad_req_position;
        final int gen = adLoaderGeneration;
        adPrefetchHandler.post(() -> {
            if (gen != adLoaderGeneration) {
                if (reqPos != null) {
                    pendingNativeLoadStarts.remove(reqPos);
                }
                return;
            }
            startNativeAdLoader(code, reqPos);
        });
    }

    private void startNativeAdLoader(String adCode, Integer ad_req_position) {
        if (isFinishing() || isDestroyed()) {
            if (ad_req_position != null) {
                pendingNativeLoadStarts.remove(ad_req_position);
            }
            return;
        }
        // Mid-flip warm may call ensure; AdLoader itself is fine. Cap skips / backoff must
        // still schedule a retry so on-settle never gets stuck on the share placeholder.
        if (ad_req_position == null || adCode == null || adCode.trim().isEmpty()) {
            if (ad_req_position != null) pendingNativeLoadStarts.remove(ad_req_position);
            return;
        }
        // Local dedupe/cap before coordinator reservation so a skipped start cannot leave
        // an orphaned in-flight cache entry.
        if (nativeGoogleAdArray != null && nativeGoogleAdArray.contains(ad_req_position)) {
            pendingNativeLoadStarts.remove(ad_req_position);
            return;
        }
        if (countInFlightNativeAdLoads() >= getMaxNativeAdLoadsInFlight()) {
            showLog("startNativeAdLoader cap skip pos=" + ad_req_position);
            pendingNativeLoadStarts.remove(ad_req_position);
            // Best-effort warm hit the cap — retry soon so settle/land still fills.
            scheduleBoundedNativeRetry(adCode, ad_req_position, "google", 450L);
            return;
        }
        NativeAdCacheCoordinator.StartDecision cacheDecision =
                NativeAdCacheCoordinator.get().requestStart(
                        "google", adCode, ad_req_position, getMaxNativeAdLoadsInFlight());
        if (cacheDecision != NativeAdCacheCoordinator.StartDecision.START) {
            pendingNativeLoadStarts.remove(ad_req_position);
            if (cacheDecision == NativeAdCacheCoordinator.StartDecision.IN_FLIGHT) {
                return;
            }
            if (cacheDecision == NativeAdCacheCoordinator.StartDecision.ALREADY_READY) {
                // Stale ready marker (creative destroyed / claimed without clear) must not
                // block the seat for the rest of the session. AdPreloader inventory alone
                // is NOT "this seat has a creative" — that skipped July on-seat loads.
                boolean hasCreative = false;
                try {
                    if (nativeGoogleAdList != null) {
                        for (int i = 0; i < nativeGoogleAdList.size(); i++) {
                            FlipGoogleNativeAds packed = nativeGoogleAdList.get(i);
                            if (packed != null && packed.getAd() != null
                                    && packed.getReqPos() == ad_req_position) {
                                hasCreative = true;
                                break;
                            }
                        }
                    }
                } catch (Exception ignored) {
                }
                if (hasCreative) {
                    return;
                }
                NativeAdCacheCoordinator.get().resetSlotFailure(
                        "google", adCode, ad_req_position);
                NativeAdCacheCoordinator.get().allowSettleRetry(
                        "google", adCode, ad_req_position);
                scheduleBoundedNativeRetry(adCode, ad_req_position, "google", 200L);
                return;
            }
            long wait = NativeAdCacheCoordinator.get().millisUntilRetryAllowed(
                    "google", adCode, ad_req_position);
            if (wait <= 0L) {
                wait = cacheDecision == NativeAdCacheCoordinator.StartDecision.BACKOFF
                        ? 1_200L : 450L;
            }
            showLog("startNativeAdLoader defer " + cacheDecision + " pos=" + ad_req_position
                    + " wait=" + wait);
            scheduleBoundedNativeRetry(adCode, ad_req_position, "google", wait);
            return;
        }
        if (nativeGoogleAdArray != null && !nativeGoogleAdArray.contains(ad_req_position)) {
            nativeGoogleAdArray.add(ad_req_position);
        }
        pendingNativeLoadStarts.remove(ad_req_position);
        VideoOptions videoOptions = new VideoOptions.Builder()
                .setStartMuted(true)
                .build();

        NativeAdOptions adOptions = new NativeAdOptions.Builder()
                .setVideoOptions(videoOptions)
                .build();

        AdLoader adLoader = new AdLoader.Builder(context, adCode)
                .withNativeAdOptions(adOptions)
                .withAdListener(new AdListener() {
                    @Override
                    public void onAdClicked() {
                        super.onAdClicked();
                        showLog(TAG+ "onAdClicked: ");
                    }

                    @Override
                    public void onAdClosed() {
                        super.onAdClosed();
                        showLog(TAG+  "onAdClosed: ");
                    }

                    @Override
                    public void onAdFailedToLoad(@NonNull LoadAdError error) {
                        super.onAdFailedToLoad(error);
                        try{
                            // Allow a later ensureFeedNativeAdLoaded / settle to retry.
                            if (nativeGoogleAdArray != null && ad_req_position != null) {
                                nativeGoogleAdArray.remove(ad_req_position);
                            }

                            String errorDomain = error.getDomain();
                            int errorCode = error.getCode();
                            String errorMessage = error.getMessage();
                            com.google.android.gms.ads.AdError cause = error.getCause();
                            // All of this information is available via the error's toString() method.
                            Log.d("Ads", error.toString());
                            JSONObject object=new JSONObject();
                            object.put("errorDomain",errorDomain);
                            object.put("errorCode",errorCode);
                            object.put("errorMessage",errorMessage);
                            object.put("adCode",adCode);
                            object.put("adPos",ad_req_position);
                            adError=object.toString();
                            boolean noFill = errorCode == AdRequest.ERROR_CODE_NO_FILL;
                            Log.w(ADS_TAG, "load failure ad_code=" + adCode
                                    + " reqPos=" + ad_req_position
                                    + " code=" + errorCode
                                    + " domain=" + errorDomain
                                    + " noFill=" + noFill
                                    + " message=" + errorMessage);
                            // Always schedule — coordinator never session-kills (delay >= 0).
                            long retryDelayMs = NativeAdCacheCoordinator.get().onFailed(
                                    "google", adCode, ad_req_position, noFill, errorMessage);
                            // Waterfall: primary no-fill → second native unit (admin toggle).
                            if (noFill) {
                                String secondary = FeedAdConfig.resolveFallbackUnitAfterNoFill(
                                        HomePage.this, adCode);
                                if (!TextUtils.isEmpty(secondary)) {
                                    Log.d(ADS_TAG, "waterfall no-fill → secondary unit="
                                            + secondary + " reqPos=" + ad_req_position);
                                    NativeAdCacheCoordinator.get().allowSettleRetry(
                                            "google", secondary, ad_req_position);
                                    loadAdLoader(secondary, ad_req_position);
                                    if (adapter != null) {
                                        runOnUiThread(new Runnable() {
                                            @Override
                                            public void run() {
                                                try {
                                                    maybeRebindCurrentAdAfterLoad(ad_req_position);
                                                } catch (Exception ignored) {
                                                }
                                                try {
                                                    scheduleFlipSafeAdRebind();
                                                } catch (Exception ignored) {
                                                }
                                            }
                                        });
                                    }
                                    return;
                                }
                            }
                            scheduleBoundedNativeRetry(
                                    adCode, ad_req_position, "google",
                                    Math.max(0L, retryDelayMs));
                            // Do not AdPreloader.prefetch on every seat fail — that
                            // doubled no-fill spam. Recover path owns warm refill.

                            // Fail = no creative for this request. Flipper mounts Share UI
                            // immediately (never a spinner). Keep seat as "ad" so a later
                            // ensureFeedNativeAdLoaded can still retry; soft fill-timeout
                            // demotes to share_app only if fill never arrives. Prefer
                            // ready-pool transfer over share when another seat already filled.
                            if (adapter != null) {
                                runOnUiThread(new Runnable() {
                                    @Override
                                    public void run() {
                                        try {
                                            maybeRebindCurrentAdAfterLoad(ad_req_position);
                                        } catch (Exception ignored) {
                                        }
                                        try {
                                            // Nearby seats may already hold unclaimed inventory.
                                            scheduleFlipSafeAdRebind();
                                        } catch (Exception ignored) {
                                        }
                                    }
                                });
                            }

                        }catch (Exception e){
                            e.printStackTrace();
                        }
                    }

                    @Override
                    public void onAdImpression() {
                        super.onAdImpression();
                        adImpress=true;
                        Log.d(ADS_TAG, "AdMob onAdImpression ad_code=" + adCode
                                + " reqPos=" + ad_req_position
                                + " (counts in AdMob Impressions; money = paid if matched)");
                        NativeAdCacheCoordinator.get().onPaidShown(
                                "google", adCode, ad_req_position);
                        // One impression = one creative — exclude from shared pool forever.
                        markGoogleNativeImpressed(ad_req_position);
                    }

                    @Override
                    public void onAdLoaded() {
                        super.onAdLoaded();
                        Log.d(ADS_TAG, "load success callback ad_code=" + adCode
                                + " reqPos=" + ad_req_position);
                        showLog(TAG+  "onAdLoaded: ");
                    }

                    @Override
                    public void onAdOpened() {
                        super.onAdOpened();
                        showLog(TAG+  "onAdOpened: ");
                    }
                })
                .forNativeAd(new NativeAd.OnNativeAdLoadedListener() {
                    @Override
                    public void onNativeAdLoaded(@NonNull NativeAd nativeAd) {
                        showLog(TAG+  "onNativeAdLoaded: ");
                        try {
                            MediaContent mediaContent = nativeAd.getMediaContent();
                            if (mediaContent != null) {
                                VideoController videoController = mediaContent.getVideoController();
                                boolean canShowCustomControls = videoController.isCustomControlsEnabled();
                                showLog("canShowCustomControls::"+canShowCustomControls);
                            }
                            if (list != null && list.size() > 0) {
                                FlipGoogleNativeAds flipGoogleNativeAds = new FlipGoogleNativeAds();
                                flipGoogleNativeAds.setAd(nativeAd);
                                flipGoogleNativeAds.setAdCode(adCode);
                                flipGoogleNativeAds.setClaimed(false);
                                flipGoogleNativeAds.setImpressed(false);
                                // Null-safe: unboxing NPE used to drop the creative entirely.
                                if (ad_req_position != null) {
                                    flipGoogleNativeAds.setReqPos(ad_req_position);
                                    if (nativeGoogleAdArray != null
                                            && !nativeGoogleAdArray.contains(ad_req_position)) {
                                        nativeGoogleAdArray.add(ad_req_position);
                                    }
                                }
                                nativeGoogleAdList.add(flipGoogleNativeAds);
                                try {
                                    // Lightweight earnings debug — AdMob console remains
                                    // source of truth. Safe no-op if SDK omits value.
                                    nativeAd.setOnPaidEventListener(adValue -> {
                                        if (adValue == null) return;
                                        Log.d(ADS_TAG, "onPaidEvent micros="
                                                + adValue.getValueMicros()
                                                + " currency=" + adValue.getCurrencyCode()
                                                + " precision=" + adValue.getPrecisionType()
                                                + " ad_code=" + adCode
                                                + " reqPos=" + ad_req_position);
                                    });
                                } catch (Exception ignored) {
                                }
                                String adapterName = null;
                                try {
                                    if (nativeAd.getResponseInfo() != null
                                            && nativeAd.getResponseInfo()
                                            .getLoadedAdapterResponseInfo() != null) {
                                        adapterName = nativeAd.getResponseInfo()
                                                .getLoadedAdapterResponseInfo().getAdapterClassName();
                                    }
                                } catch (Exception ignored) {
                                }
                                NativeAdCacheCoordinator.get().onLoaded(
                                        "google", adCode, ad_req_position, adapterName);
                                NativeAdCacheCoordinator.get().logMediationAdapter(adapterName);
                                Log.d(ADS_TAG, "native ready ad_code=" + adCode
                                        + " reqPos=" + ad_req_position
                                        + " mediationAdapter=" + adapterName);
                                maybeRestoreDemotedAdSeatsForFill(ad_req_position);
                                maybeRebindCurrentAdAfterLoad(ad_req_position);
                                try {
                                    if(nativeAd.getResponseInfo()!=null && nativeAd.getResponseInfo().getLoadedAdapterResponseInfo()!=null &&
                                            nativeAd.getResponseInfo().getLoadedAdapterResponseInfo().getAdapterClassName()!=null){
                                        showLog("Data:"+nativeAd.getResponseInfo().getLoadedAdapterResponseInfo().getAdapterClassName());
                                    }
                                }catch (Exception e){
                                    e.printStackTrace();
                                }
                            }
                        }catch (Exception e){
                            e.printStackTrace();
                        }

                    }

                })
                .build();
        try {
            adLoader.loadAd(new AdRequest.Builder().build());
        } catch (Exception e) {
            if (nativeGoogleAdArray != null && ad_req_position != null) {
                nativeGoogleAdArray.remove(ad_req_position);
            }
            Log.e(ADS_TAG, "load start exception ad_code=" + adCode
                    + " reqPos=" + ad_req_position + " error=" + e.getMessage());
            long retryDelayMs = NativeAdCacheCoordinator.get().onFailed(
                    "google", adCode, ad_req_position, false, String.valueOf(e.getMessage()));
            scheduleBoundedNativeRetry(
                    adCode, ad_req_position, "google", Math.max(1_200L, retryDelayMs));
        }

    }

    private void loadInterstitialAd(String adCode, Integer ad_req_position) {
        if (adCode == null || adCode.isEmpty()) {
            if (nativeGoogleAdArray != null && ad_req_position != null) {
                nativeGoogleAdArray.remove(ad_req_position);
            }
            return;
        }
        // InterstitialAd.load requires an AdMob unit (ca-app-pub-…/…), not a GAM
        // native path. resolveGoogleNativeAdUnit already prefers FeedAdConfig.
        if (adCode.startsWith("/")) {
            Log.w(ADS_TAG, "interstitial skip GAM-style unit ad_code=" + adCode
                    + " reqPos=" + ad_req_position
                    + " — set AdMob interstitial unit + matching format");
            if (nativeGoogleAdArray != null && ad_req_position != null) {
                nativeGoogleAdArray.remove(ad_req_position);
            }
            return;
        }
        AdRequest adRequest = new AdRequest.Builder().build();
        InterstitialAd.load(this, adCode, adRequest, new InterstitialAdLoadCallback() {
            @Override
            public void onAdFailedToLoad(@NonNull LoadAdError loadAdError) {
                super.onAdFailedToLoad(loadAdError);
                if (nativeGoogleAdArray != null && ad_req_position != null) {
                    nativeGoogleAdArray.remove(ad_req_position);
                }
                Log.w(ADS_TAG, "interstitial load failure ad_code=" + adCode
                        + " reqPos=" + ad_req_position
                        + " error=" + (loadAdError != null ? loadAdError.getMessage() : ""));
            }

            @Override
            public void onAdLoaded(@NonNull InterstitialAd interstitialAd) {
                super.onAdLoaded(interstitialAd);
                try {
                    FlipGoogleNativeAds flipGoogleNativeAds = new FlipGoogleNativeAds();
                    flipGoogleNativeAds.setInterstitialAd(interstitialAd);
                    flipGoogleNativeAds.setAdCode(adCode);
                    flipGoogleNativeAds.setReqPos(ad_req_position);
                    if (nativeGoogleAdArray != null
                            && ad_req_position != null
                            && !nativeGoogleAdArray.contains(ad_req_position)) {
                        nativeGoogleAdArray.add(ad_req_position);
                    }
                    nativeGoogleAdList.add(flipGoogleNativeAds);
                    Log.d(ADS_TAG, "interstitial ready ad_code=" + adCode
                            + " reqPos=" + ad_req_position);
                    // If user already settled on this seat, show immediately.
                    try {
                        if (list != null
                                && positionx >= 0
                                && positionx < list.size()
                                && list.get(positionx) != null
                                && "ad".equalsIgnoreCase(list.get(positionx).getPostType())) {
                            maybeShowFeedInterstitialForSlot(list.get(positionx));
                        }
                    } catch (Exception ignored) {
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        });
    }

    /**
     * Retry only an unchanged feed seat after coordinator backoff / cap. This runs on
     * the ad handler, never on pagination/render work, and is discarded when the owning
     * feed was replaced. Match by {@code ad_req_position} only — resolved AdMob unit ids
     * often differ from server slot codes and must not drop valid retries.
     */
    private void scheduleBoundedNativeRetry(
            @Nullable String adCode,
            @Nullable Integer adReqPosition,
            @Nullable String adType,
            long delayMs) {
        if (adReqPosition == null) return;
        final String codeHint = adCode;
        final Integer pos = adReqPosition;
        final String type = adType == null ? "google" : adType;
        final int generation = adLoaderGeneration;
        adPrefetchHandler.postDelayed(() -> {
            if (isFinishing() || isDestroyed() || generation != adLoaderGeneration || list == null) {
                return;
            }
            for (ModelClass.Datum datum : list) {
                if (datum == null || !ReadArticleStore.isAdFeedSlot(datum)) continue;
                Integer slotPos = datum.getAd_req_position();
                if (!pos.equals(slotPos)) {
                    continue;
                }
                String slotCode = datum.getAd_code();
                if (slotCode == null || slotCode.trim().isEmpty()) {
                    slotCode = datum.getNext_req_ad_code();
                }
                if (slotCode == null || slotCode.trim().isEmpty()) {
                    slotCode = codeHint;
                }
                String slotType = datum.getAd_type();
                if (slotType == null || slotType.trim().isEmpty()) {
                    slotType = type;
                }
                showLog("AD RETRY valid seat pos=" + pos);
                ensureFeedNativeAdLoaded(slotCode, pos, slotType);
                return;
            }
            showLog("AD RETRY obsolete seat dropped pos=" + pos);
        }, Math.max(0L, delayMs));
    }

    private void loadFBAds(String adCode, Integer ad_req_position) {
        showLog("loadAds3");
        if (adCode == null || adCode.trim().isEmpty() || ad_req_position == null) {
            return;
        }
        if (nativeFBAdArray != null && nativeFBAdArray.contains(ad_req_position)) {
            return;
        }
        if (countInFlightNativeAdLoads() >= getMaxNativeAdLoadsInFlight()) {
            showLog("loadFBAds cap skip pos=" + ad_req_position);
            scheduleBoundedNativeRetry(adCode, ad_req_position, "facebook", 450L);
            return;
        }
        NativeAdCacheCoordinator.StartDecision cacheDecision =
                NativeAdCacheCoordinator.get().requestStart(
                        "facebook", adCode, ad_req_position, getMaxNativeAdLoadsInFlight());
        if (cacheDecision != NativeAdCacheCoordinator.StartDecision.START) {
            if (cacheDecision == NativeAdCacheCoordinator.StartDecision.IN_FLIGHT
                    || cacheDecision == NativeAdCacheCoordinator.StartDecision.ALREADY_READY) {
                return;
            }
            long wait = NativeAdCacheCoordinator.get().millisUntilRetryAllowed(
                    "facebook", adCode, ad_req_position);
            if (wait <= 0L) {
                wait = cacheDecision == NativeAdCacheCoordinator.StartDecision.BACKOFF
                        ? 1_200L : 450L;
            }
            scheduleBoundedNativeRetry(adCode, ad_req_position, "facebook", wait);
            return;
        }
        if (nativeFBAdArray != null && !nativeFBAdArray.contains(ad_req_position)) {
            nativeFBAdArray.add(ad_req_position);
        }
      //  AdSettings.addTestDevice("b14f44bb-6e6c-4e38-910a-17b1b14ccc78");
        //AdSettings.addTestDevice(" 7f8b87ee-f0f2-4e3f-8a78-e3e60e226f41");
        //AdSettings.addTestDevice("811a589f-fb7f-496b-be57-863f812ab0db");
//        AdSettings.addTestDevice("e281cb34-438f-441d-a6f4-f44f12a2cbc8");
//        AdSettings.addTestDevice("2769be7c-e83c-42f5-b10c-79c0d6ea8d8e");
        //AdSettings.addTestDevice("3a138881-78e4-4aa0-9d51-45a91f7c9539");
        // AdSettings.addTestDevice("ba679175-04d5-4eb0-a5d3-b34a272ddc58");
       // String placementID="1908969226136425_1909067626126585";
//         String adCodeN="VID_HD_16_9_46S_LINK#"+adCode;
        com.facebook.ads.NativeAd nativeAd = new com.facebook.ads.NativeAd(HomePage.this, adCode);
        NativeAdListener nativeAdListener = new NativeAdListener() {
            @Override
            public void onMediaDownloaded(Ad ad) {
                // Native ad finished downloading all assets
                showLog(TAG+  "Native ad finished downloading all assets.");
            }

            @Override
            public void onError(Ad ad, AdError adError) {
                // Native ad failed to load
                showLog(TAG+  "Native ad failed to load: " + adError.getErrorMessage());
                try {
                    if (nativeFBAdArray != null && ad_req_position != null) {
                        nativeFBAdArray.remove(ad_req_position);
                    }
                } catch (Exception ignored) {
                }
                boolean noFill = adError != null && adError.getErrorCode() == 1001;
                long retryDelayMs = NativeAdCacheCoordinator.get().onFailed(
                        "facebook", adCode, ad_req_position, noFill,
                        adError != null ? adError.getErrorMessage() : "unknown");
                scheduleBoundedNativeRetry(
                        adCode, ad_req_position, "facebook", Math.max(0L, retryDelayMs));
            }

            @Override
            public void onAdLoaded(Ad ad) {
                if (nativeAd == null || nativeAd != ad) {
                    return;
                }
                // Native ad is loaded and ready to be displayed
                showLog(TAG+  "Native ad is loaded and ready to be displayed!");
                FlipGoogleNativeAds flipGoogleNativeAds=new FlipGoogleNativeAds();
                flipGoogleNativeAds.setFbAd(nativeAd);
                flipGoogleNativeAds.setAdCode(adCode != null ? adCode : "");
                flipGoogleNativeAds.setClaimed(false);
                flipGoogleNativeAds.setImpressed(false);
                // Use the requested slot position (not current flip index) so prefetch
                // for upcoming ad seats matches correctly.
                Integer reqPos = ad_req_position;
                if (reqPos == null && list != null && positionx >= 0 && positionx < list.size()) {
                    reqPos = list.get(positionx).getAd_req_position();
                }
                if (reqPos != null) {
                    flipGoogleNativeAds.setReqPos(reqPos);
                    if (nativeFBAdArray != null && !nativeFBAdArray.contains(reqPos)) {
                        nativeFBAdArray.add(reqPos);
                    }
                }
                nativeFBAdList.add(flipGoogleNativeAds);
                NativeAdCacheCoordinator.get().onLoaded(
                        "facebook", adCode, reqPos, "direct-facebook");
                NativeAdCacheCoordinator.get().logMediationAdapter("direct-facebook");
                maybeRestoreDemotedAdSeatsForFill(reqPos);
                maybeRebindCurrentAdAfterLoad(reqPos);
            }

            @Override
            public void onAdClicked(Ad ad) {
            }

            @Override
            public void onLoggingImpression(Ad ad) {
                // Native ad impression
                adImpress=true;
                if (ad_req_position != null) {
                    NativeAdCacheCoordinator.get().onPaidShown(
                            "facebook", adCode, ad_req_position);
                    markFbNativeImpressed(ad_req_position);
                }
            }
        };
        nativeAd.loadAd(
                nativeAd.buildLoadAdConfig()
                        .withMediaCacheFlag(NativeAdBase.MediaCacheFlag.ALL)
                        .withAdListener(nativeAdListener)
                        .build());
    }

