    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        if(requestCode==289){
            return;
        }
        if (requestCode == REQ_POST_NOTIFICATIONS) {
            boolean granted = grantResults.length > 0
                    && grantResults[0] == PackageManager.PERMISSION_GRANTED;
            handlePostNotificationsPermissionResult(granted);
            return;
        }
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if(requestCode==234){
            if(grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED){
                showLog(""+TAG+"Permission: "+permissions[0]+ "was "+grantResults[0]);
                downloadRequests(1);
              //  adapter.downloadPDFWithProgressBar(list.get(positionx).getVideoUrl(),"anyNews_+"+list.get(positionx).getPostId()+"."+getMimeType(list.get(positionx).getVideoUrl()),positionx,1);
                //resume tasks needing this permission
            }
        }else if(requestCode==223){
            if(grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED){
                showLog(""+TAG+"Permission: "+permissions[0]+ "was "+grantResults[0]);
                downloadRequests(0);
//                adapter.downloadPDFWithProgressBar(list.get(positionx).getDownloadUrl(),"anyNews_+"+list.get(positionx).getPostId()+".pdf",positionx,0);
                //resume tasks needing this permission
            }
        }

    }
    public static String getMimeType(String url) {
        String type = null;
        String[] array=url.split("/");
        String data=url.substring(url.lastIndexOf("/") + 1);
        data=data.substring(data.lastIndexOf(".") + 1);
        String extension = MimeTypeMap.getFileExtensionFromUrl(url);
        if (extension != null) {
            type = MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension);
        }
        showLog("type:::::::"+type);
        showLog("data:::::::"+data);
        return data;
    }
    boolean loadingOnOverFlip =true;
    @Override
    public void onOverFlip(FlipView v, OverFlipMode mode, boolean overFlippingPrevious, float overFlipDistance, float flipDistancePerPage) {
        Logone.i("onoverflip", "overFlipDistance = " + overFlipDistance);
        showLog("onOverFlip::overFlipDistance:"+ overFlipDistance);
        showLog("onOverFlip::flipDistancePerPage:"+ flipDistancePerPage);
        showLog("onOverFlip::getPageCount:"+ v.getPageCount());
        showLog("onOverFlip::size:"+ list.size());
        showLog("onOverFlip::positionx:"+ positionx);
        showLog("onOverFlip::positionx:"+((list.size()-1)==positionx));

        // Forward pull past the last loaded card. A fast fling often leaves
        // positionx behind the finger, so do not require it to equal the last index.
        final boolean forwardPastEnd = overFlipDistance > 0
                && !overFlippingPrevious
                && list != null
                && !list.isEmpty()
                && v.getPageCount() == list.size();
        // A page the server already returned must be appended even inside the
        // overflip cooldown. Waiting out that cooldown left the last card stuck
        // while Redis still had rows.
        if (forwardPastEnd && dummyResponse != null && !isDataParsed) {
            showLog("onOverFlip apply held page positionx=" + positionx
                    + " size=" + list.size());
            convertListOfArticles(dummyResponse, -1);
        }

        if(forwardPastEnd && loadingOnOverFlip){
            loadingOnOverFlip = false;
            // Keyword search: last page is Continue-reading hub — never invent a
            // second "no more news" sentinel on overflip.
            if (searchFeedActive
                    && ((activeSearchQuery != null && !activeSearchQuery.trim().isEmpty())
                            || activeSearchPostId > 0L
                            || activeSearchSingleOnly)) {
                // Finite search deck — rubber-band only; never page more News/hits.
                showLog("ANYNEWS_SEARCH overflip blocked — finite search deck");
                try {
                    if (list != null
                            && ReadArticleStore.countPaintableArticles(list) > 0
                            && (!searchContentLanded
                                    || !FeedEndHelper.hasAtEnd(list))) {
                        finalizeSearchFeedSeating(!searchContentLanded);
                    }
                } catch (Exception ignored) {
                }
            } else {
            boolean paginationInFlight = isApiRequested && dummyResponse == null;
            if (!isDataParsed) {
                if (dummyResponse != null) {
                    convertListOfArticles(dummyResponse, -1);
                }
            } else if (paginationInFlight) {
                // Next page API is in flight; avoid misleading toast.
            } else if (!isDeviceOnline()
                    || isOnlineReadFlipMode()
                    || isOnlinePageableFeedTrulyExhausted()) {
                // Finite deck or known exhausted — end card, never blank white.
                ensureFeedEndCardVisible(true);
            } else if (isFeedExhaustedMessage()
                    && canPageActiveOnlineFlipFeed()
                    && !bookmarksModeSelected) {
                // Stale EOF marker (e.g. Chadivindi toggle) — clear and page older days.
                clearSpuriousFeedExhaustedState();
                try {
                    refreshDetails();
                } catch (Exception ignored) {
                }
            } else {
                // Online News/Special/Video: nudge pagination instead of inventing end.
                try {
                    refreshDetails();
                } catch (Exception ignored) {
                }
            }
            }
        }
        new Handler(Looper.getMainLooper()).postDelayed(new Runnable() {
            @Override
            public void run() {
                loadingOnOverFlip =true;
            }
        },1500);



    }

