    private View getFlipChildForShare() {
        if (mFlipView == null || ppi < 0 || ppi >= mFlipView.getChildCount()) {
            return null;
        }
        return mFlipView.getChildAt(ppi);
    }

    private static final String MAGAZINE_GLOW_TAG = "MagazineGlow";

    /**
     * Prefer FlipView's current page index (source of truth) over stale positionx.
     */
    private int getVisiblePostIndex() {
        try {
            if (mFlipView != null && list != null) {
                int cur = mFlipView.getCurrentPage();
                if (cur >= 0 && cur < list.size()) {
                    return cur;
                }
            }
        } catch (Exception ignored) {
        }
        return positionx;
    }

    /** Visible flip index for FlipperAdapter on-post magazine Share restore. */
    public int getVisiblePostIndexForShare() {
        return getVisiblePostIndex();
    }

    /**
     * Middle column between Special and Daily Updates.
     * Magazines / special galleries: blinking Share.
     * Every other card, including ads: a steady WhatsApp icon. It does not pulse
     * and it does not hide when an ad scrolls in. Hiding that slot rebuilt the
     * Material bar and moved the Special pulse onto the wrong tab.
     * The reporter "+" is not a footer control on this build.
     */
    private void updateCenterFab() {
        if (footerCenterSlotFrozenForReload) {
            // Empty list during Reload is not "hide WhatsApp". Leaving the slot
            // up avoids a menu rebuild under a still-down finger (opens Profile).
            boolean keepFrozen = isDeviceOnline() && (list == null || list.isEmpty());
            if (keepFrozen) {
                return;
            }
            footerCenterSlotFrozenForReload = false;
        }
        if (newsFooterWhatsappHeld) {
            if (list == null || list.isEmpty()) {
                newsFooterSawEmptyDuringHold = true;
            } else if (newsFooterSawEmptyDuringHold && !isDailyUpdatesMode()) {
                newsFooterWhatsappHeld = false;
                newsFooterSawEmptyDuringHold = false;
            }
        }
        if (visibleFlipIsInviteOrAdShell()) {
            repairVisibleShareTargetIfInviteShell();
        }
        boolean showShare = shouldShowMagazineFooterShare();
        int idx = getVisiblePostIndex();
        String type = "";
        try {
            if (list != null && idx >= 0 && idx < list.size() && list.get(idx) != null
                    && list.get(idx).getPostType() != null) {
                type = list.get(idx).getPostType();
            }
        } catch (Exception ignored) {
        }
        Log.i(MAGAZINE_GLOW_TAG, "updateCenterFab idx=" + idx
                + " postType=[" + type + "]"
                + " showShare=" + showShare);
        hideCenterPlusOverlays();
        if (showShare) {
            applyMagazineCenterShare();
            Log.i(MAGAZINE_GLOW_TAG, "MODE=SHARE_FOOTER postType=[" + type + "]");
            showLog("updateCenterFab magazine share footer");
            return;
        }
        hideMagazineShareFooter();
        if (shouldShowFooterWhatsapp()) {
            applyFooterWhatsapp();
            if (isVisibleFooterQuietCard()) {
                hideSpecialBlinkForQuietCard();
            }
            Log.i(MAGAZINE_GLOW_TAG, "MODE=WHATSAPP_FOOTER postType=[" + type + "]");
            showLog("updateCenterFab footer WhatsApp");
            return;
        }
        hideFooterWhatsapp();
        ensureMagazineShareFooterSlot();
        if (isVisibleFooterQuietCard()) {
            hideSpecialBlinkForQuietCard();
        }
        showLog("updateCenterFab middle slot hidden");
    }

    /**
     * The drawn flip child is the "Share AnyNews with your friends" invite
     * (unfilled ad placeholder or {@code share_app}), not a magazine pager.
     * List index can still say magazine after a pin that did not rebind.
     */
    private boolean visibleFlipIsInviteOrAdShell() {
        try {
            if (mFlipView == null) {
                return false;
            }
            View page = mFlipView.getCurrentPageView();
            if (page == null) {
                return false;
            }
            if (page.findViewById(R.id.ad_default_placeholder_root) != null) {
                return true;
            }
            if (page.findViewById(R.id.fl_adplaceholder) != null
                    && page.findViewById(R.id.magzine_viewPager_data) == null
                    && page.findViewById(R.id.viewpager) == null) {
                return true;
            }
            return page.findViewById(R.id.imageViewWhatsapp) != null
                    && page.findViewById(R.id.magzine_viewPager_data) == null
                    && page.findViewById(R.id.viewpager) == null
                    && page.findViewById(R.id.gallery_horizontal_flip) == null;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Ads, invite, and ratings cards must not pulse Special or Daily Updates.
     * The footer WhatsApp icon stays in the middle slot on these cards.
     * The orange blink stays on center Share, and only while a magazine is visible.
     */
    private boolean isVisibleFooterQuietCard() {
        if (visibleFlipIsInviteOrAdShell()) {
            return true;
        }
        try {
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size()) {
                return false;
            }
            ModelClass.Datum item = list.get(idx);
            if (item == null) {
                return false;
            }
            if (ReadArticleStore.isAdFeedSlot(item)
                    || ReadArticleStore.isShareFeedSlot(item)
                    || ReadArticleStore.isRatingsFeedSlot(item)) {
                return true;
            }
            String type = item.getPostType();
            return type != null && (type.trim().equalsIgnoreCase("web")
                    || type.trim().equalsIgnoreCase("web_ads"));
        } catch (Exception e) {
            return false;
        }
    }

    /** One-shot: invite shell is showing but a share/push target is in the list. */
    private void repairVisibleShareTargetIfInviteShell() {
        if (shareInviteRepairAttempts >= 2) {
            return;
        }
        if (resolvePendingDeepLinkPostId() <= 0 || list == null || mFlipView == null) {
            return;
        }
        if (indexOfRealDeepLinkTarget(list, resolvePendingDeepLinkPostId()) < 0) {
            return;
        }
        shareInviteRepairAttempts++;
        final int attempt = shareInviteRepairAttempts;
        mFlipView.post(new Runnable() {
            @Override
            public void run() {
                try {
                    if (resolvePendingDeepLinkPostId() <= 0) {
                        return;
                    }
                    showLog("share invite-shell repair attempt=" + attempt);
                    pinDeepLinkTargetToFront(list);
                    if (mFlipView != null) {
                        mFlipView.beginForcedPage0Seat();
                    }
                    if (adapter != null) {
                        adapter.notifyWhenFlipSettled();
                    }
                    flipToDeepLinkPage(0, true);
                } catch (Exception ignored) {
                }
            }
        });
    }

    private boolean shouldShowMagazineFooterShare() {
        try {
            if (visibleFlipIsInviteOrAdShell()) {
                return false;
            }
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size()) {
                return false;
            }
            ModelClass.Datum item = list.get(idx);
            if (item != null && (ReadArticleStore.isSyntheticFeedSlot(item)
                    || ReadArticleStore.isShareFeedSlot(item))) {
                return false;
            }
            if (usesMagazineGlowShare(item, idx)) {
                return true;
            }
            if (!isSpecialFeedMode() || item == null) {
                return false;
            }
            String type = item.getPostType();
            if (type == null) {
                return false;
            }
            type = type.trim();
            return type.equalsIgnoreCase("image_gallery")
                    || type.equalsIgnoreCase("magazine")
                    || type.equalsIgnoreCase("magazines");
        } catch (Exception e) {
            Log.e(MAGAZINE_GLOW_TAG, "shouldShowMagazineFooterShare: " + e.getMessage());
            return false;
        }
    }

    /**
     * True when the currently visible post should use the glow Share FAB instead of "+".
     * Live "రామాయణం స్పెషల్" is post_type {@code image_gallery} in Magazines (category 15) —
     * not {@code magazine}. Only true magazines + Magazines-category galleries get glow.
     * Normal image_gallery posts keep "+" / WhatsApp; on-image corner share stays hidden.
     */
    private boolean isCurrentPostMagazine() {
        try {
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size()) {
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=false reason=bad_index idx=" + idx
                        + " listSize=" + (list == null ? -1 : list.size()));
                return false;
            }
            return usesMagazineGlowShare(list.get(idx), idx);
        } catch (Exception e) {
            Log.e(MAGAZINE_GLOW_TAG, "isMagazine exception: " + e.getMessage());
            return false;
        }
    }

    /**
     * Footer glow Share applies only to card magazines and Magazines-category specials
     * (e.g. Ramayana). Ordinary {@code image_gallery} news posts must NOT match — they keep
     * the reporter "+" / WhatsApp FAB. On-image {@code image_gallary_share} stays hidden.
     */
    public static boolean usesMagazineGlowShare(ModelClass.Datum item) {
        return usesMagazineGlowShare(item, -1);
    }

    private static boolean usesMagazineGlowShare(ModelClass.Datum item, int idx) {
        try {
            if (item == null) {
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=false reason=null_item idx=" + idx);
                return false;
            }
            String type = item.getPostType();
            if (type == null) {
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=false reason=null_postType idx=" + idx);
                return false;
            }
            type = type.trim();
            boolean glow = type.equalsIgnoreCase("magazine")
                    || type.equalsIgnoreCase("magazines");
            // Magazines-category image_gallery specials only (NOT all galleries).
            Integer catId = item.getCategoryId();
            if (!glow && type.equalsIgnoreCase("image_gallery")
                    && catId != null && catId.intValue() == 15) {
                glow = true;
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=true via Magazines image_gallery cat=15"
                        + " idx=" + idx);
            }
            // Magazines card posts: media_type "2" with strip JSON (non-gallery).
            if (!glow && !"image_gallery".equalsIgnoreCase(type)
                    && "2".equals(String.valueOf(item.getMediaType()))) {
                String strip = item.getStrip_content();
                if (strip != null && strip.trim().length() > 2
                        && (strip.trim().startsWith("[") || strip.contains("http"))) {
                    glow = true;
                    Log.i(MAGAZINE_GLOW_TAG, "isMagazine=true via media_type=2+strip"
                            + " postType=[" + type + "] idx=" + idx);
                }
            }
            // Magazines category_id 15 + media_type 2 — safety net if post_type mistyped.
            if (!glow && catId != null && catId.intValue() == 15
                    && "2".equals(String.valueOf(item.getMediaType()))
                    && !"image_gallery".equalsIgnoreCase(type)) {
                glow = true;
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=true via Magazines category_id=15"
                        + " postType=[" + type + "] idx=" + idx);
            }
            if (!glow) {
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=false postType=[" + type + "] mediaType="
                        + item.getMediaType() + " cat=" + item.getCategoryId() + " idx=" + idx);
            } else {
                Log.i(MAGAZINE_GLOW_TAG, "isMagazine=true postType=[" + type + "] mediaType="
                        + item.getMediaType() + " cat=" + item.getCategoryId() + " idx=" + idx);
            }
            return glow;
        } catch (Exception e) {
            Log.e(MAGAZINE_GLOW_TAG, "usesMagazineGlowShare exception: " + e.getMessage());
            return false;
        }
    }

    /**
     * Magazines / image_gallery: replace the center "+" FAB with a footer-style Share
     * control (admin-sized icon + translated label) that blinks like the Special bulb.
     */
    private void applyMagazineCenterShare() {
        hideFooterWhatsapp();
        if (imageVIewShareWhatsapp != null) {
            imageVIewShareWhatsapp.clearAnimation();
            imageVIewShareWhatsapp.setOnClickListener(null);
            imageVIewShareWhatsapp.setClickable(false);
            imageVIewShareWhatsapp.setVisibility(View.GONE);
        }
        // Hide the + FAB plate so Share reads like a normal footer tab.
        if (floatingActionButtonHome != null) {
            floatingActionButtonHome.clearAnimation();
            floatingActionButtonHome.setOnClickListener(null);
            floatingActionButtonHome.setClickable(false);
            floatingActionButtonHome.setFocusable(false);
            floatingActionButtonHome.setVisibility(View.INVISIBLE);
            try {
                floatingActionButtonHome.hide();
            } catch (Exception ignored) {
            }
        }
        if (layoutMagazineShareFooter == null) {
            Log.e(MAGAZINE_GLOW_TAG, "applyMagazineCenterShare FAILED: layoutMagazineShareFooter null");
            return;
        }
        applyMagazineShareFooterLabel();
        layoutMagazineShareFooter.setVisibility(View.VISIBLE);
        layoutMagazineShareFooter.setEnabled(true);
        layoutMagazineShareFooter.setClickable(true);
        layoutMagazineShareFooter.setOnClickListener(v -> {
            try {
                int visibleIdx = getVisiblePostIndex();
                if (visibleIdx >= 0) {
                    positionx = visibleIdx;
                }
                CallShareListener magListener = new CallShareListener();
                magListener.setShareInterfaceListener(adapter);
                magListener.triggerEvent();
                shareCurrentPostViaWhatsAppFooter();
            } catch (Exception magEx) {
                magEx.printStackTrace();
            }
        });
        layoutMagazineShareFooter.bringToFront();
        if (home_page_navigation != null) {
            home_page_navigation.bringChildToFront(layoutMagazineShareFooter);
        }
        startMagazineShareBlink();
        // Pulse the center Share control only. Special and Daily Updates stay still.
        stopSpecialTabBlinkAnimation();
        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.setVisibility(View.GONE);
        }
        // Middle column (not the Special tab). Footer reflows to News | Special | Share | …
        ensureMagazineShareFooterSlot();
        Log.i(MAGAZINE_GLOW_TAG, "applyMagazineCenterShare OK mode=FOOTER_SHARE"
                + " vis=" + layoutMagazineShareFooter.getVisibility());
    }

    /** Localized "Share" from language pack (same source as reload/profile footer labels). */
    private void applyMagazineShareFooterLabel() {
        if (tvMagazineShareFooter == null) {
            return;
        }
        String label = null;
        try {
            if (languageModelResponse != null
                    && languageModelResponse.getData() != null
                    && languageModelResponse.getData().getShare() != null) {
                label = languageModelResponse.getData().getShare().trim();
            }
        } catch (Exception ignored) {
        }
        if (label == null || label.isEmpty()) {
            label = getString(R.string.share);
        }
        tvMagazineShareFooter.setText(label);
        if (layoutMagazineShareFooter != null) {
            layoutMagazineShareFooter.setContentDescription(label);
        }
        if (ivMagazineShareFooter != null) {
            ivMagazineShareFooter.setContentDescription(label);
        }
    }

    private void hideMagazineShareFooter() {
        stopMagazineShareBlink();
        if (layoutMagazineShareFooter != null) {
            layoutMagazineShareFooter.setOnClickListener(null);
            layoutMagazineShareFooter.setClickable(false);
            layoutMagazineShareFooter.setVisibility(View.GONE);
            ViewGroup.LayoutParams lp = layoutMagazineShareFooter.getLayoutParams();
            if (lp != null && lp.width != ViewGroup.LayoutParams.WRAP_CONTENT) {
                lp.width = ViewGroup.LayoutParams.WRAP_CONTENT;
                layoutMagazineShareFooter.setLayoutParams(lp);
            }
            layoutMagazineShareFooter.setTranslationX(0f);
        }
        // Keep the middle column when WhatsApp still needs it.
        ensureMagazineShareFooterSlot();
    }

    private boolean isMagazineShareFooterShowing() {
        return layoutMagazineShareFooter != null
                && layoutMagazineShareFooter.getVisibility() == View.VISIBLE;
    }

    /**
     * Steady WhatsApp between Special and Daily Updates on every card that is
     * not a magazine. Ads keep this icon so scrolling does not rebuild the bar.
     * No blink and no count. Offline stays News-only. The likes-row admin
     * toggle does not hide this icon. Only the Daily Updates hub hides it.
     * Local news and flash news opened from that hub are news and keep it,
     * including the empty moment before page 0 returns.
     */
    private boolean shouldShowFooterWhatsapp() {
        try {
            if (!isDeviceOnline() || shouldShowMagazineFooterShare()) {
                return false;
            }
            if (isDailyUpdatesMode() || isCalendarMode()) {
                return false;
            }
            if (newsFooterWhatsappHeld) {
                return true;
            }
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size() || list.get(idx) == null) {
                return false;
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private boolean isFooterWhatsappShowing() {
        return imageVIewShareWhatsapp != null
                && imageVIewShareWhatsapp.getVisibility() == View.VISIBLE;
    }

    private boolean isReporterPlusShowing() {
        return floatingActionButtonHome != null
                && floatingActionButtonHome.getVisibility() == View.VISIBLE;
    }

    /**
     * Middle column should be open for magazine Share or the footer WhatsApp.
     * The reporter-login flag does not open a plus here. The Daily Updates hub
     * does not keep an empty column — that was the gap between Special and
     * Daily Updates. Flash and local news from that hub open this slot for real
     * and draw the WhatsApp glyph on it.
     */
    private boolean wantsCenterFooterActionSlot() {
        if (!isDeviceOnline() || isFooterCalendarTabWanted() || isDailyUpdatesMode()) {
            return false;
        }
        if (shouldShowMagazineFooterShare()) {
            return true;
        }
        return shouldShowFooterWhatsapp();
    }

    /** Middle column is open for Share, +, or WhatsApp, and Panchangam is not using it. */
    private boolean isCenterFooterActionSlotOpen() {
        return !isFooterCalendarTabWanted()
                && (isMagazineShareFooterShowing() || isFooterWhatsappShowing()
                || isReporterPlusShowing());
    }

    /**
     * July 28 footer WhatsApp: ic_whatsapp_home, no tint, no count,
     * admin size (default 48dp). Steady icon — never the magazine Share pulse.
     * Already-visible calls do not hide and reshow the view (that fade is the
     * per-article blink from {@code animateLayoutChanges}).
     */
    private void applyFooterWhatsapp() {
        if (imageVIewShareWhatsapp == null) {
            return;
        }
        imageVIewShareWhatsapp.clearAnimation();
        imageVIewShareWhatsapp.animate().cancel();
        imageVIewShareWhatsapp.setScaleX(1f);
        imageVIewShareWhatsapp.setScaleY(1f);
        imageVIewShareWhatsapp.setAlpha(1f);
        boolean alreadyShowing = imageVIewShareWhatsapp.getVisibility() == View.VISIBLE
                && imageVIewShareWhatsapp.getDrawable() != null;
        if (!alreadyShowing) {
            imageVIewShareWhatsapp.setImageResource(R.drawable.ic_whatsapp_home);
            imageVIewShareWhatsapp.clearColorFilter();
            runWithoutFooterLayoutTransition(() ->
                    imageVIewShareWhatsapp.setVisibility(View.VISIBLE));
        }
        FooterStyleHelper.applyFooterWhatsappIcon(this, imageVIewShareWhatsapp);
        imageVIewShareWhatsapp.setEnabled(true);
        imageVIewShareWhatsapp.setClickable(true);
        imageVIewShareWhatsapp.setOnClickListener(v -> onFooterCenterWhatsappClicked());
        if (home_page_navigation != null) {
            int last = home_page_navigation.getChildCount() - 1;
            if (last < 0 || home_page_navigation.getChildAt(last) != imageVIewShareWhatsapp) {
                imageVIewShareWhatsapp.bringToFront();
                home_page_navigation.bringChildToFront(imageVIewShareWhatsapp);
            }
        }
        ensureMagazineShareFooterSlot();
    }

    private void hideFooterWhatsapp() {
        if (imageVIewShareWhatsapp == null) {
            return;
        }
        imageVIewShareWhatsapp.setOnClickListener(null);
        imageVIewShareWhatsapp.setClickable(false);
        imageVIewShareWhatsapp.clearAnimation();
        imageVIewShareWhatsapp.setAlpha(1f);
        imageVIewShareWhatsapp.setScaleX(1f);
        imageVIewShareWhatsapp.setScaleY(1f);
        runWithoutFooterLayoutTransition(() ->
                imageVIewShareWhatsapp.setVisibility(View.GONE));
        imageVIewShareWhatsapp.setTranslationX(0f);
    }

    /**
     * The new footer does not show the reporter plus. Posting stays on the
     * profile entry for a user whose role is reporter. {@code show_reporter_login}
     * is still read from the server for older builds.
     */
    private void applyReporterPlusFab() {
        hideCenterPlusOverlays();
    }

    /** Logged-in reporters open the create menu; everyone else opens login. */
    private void onReporterPlusFooterClicked() {
        try {
            if (isCenterPlusMenuOpen()) {
                closeCenterPlusMenu(true);
                return;
            }
            boolean isLogin = SharedPrefsData.getBool(
                    this, Constants.is_login, Constants.PREF_NAME);
            if (isLogin) {
                openCenterPlusMenu();
            } else {
                Intent intent = new Intent(HomePage.this, LoginActivityDetails.class);
                if (getApplicationContext() != null
                        && getApplicationContext().getPackageName().equals(BuildConfig.APPLICATION_ID)) {
                    startActivity(intent);
                }
            }
        } catch (Exception e) {
            showLog("onReporterPlusFooterClicked: " + e.getMessage());
        }
    }

    /**
     * One WhatsApp share of the visible article. The half-row chip and the middle
     * footer icon both call this. The count is written only after WhatsApp
     * returns RESULT_OK (the user sent). Opening WhatsApp does not write it.
     */
    public void onArticleWhatsappClicked(int position) {
        try {
            if (position >= 0) {
                positionx = position;
            }
            CallShareListener listener = new CallShareListener();
            listener.setShareInterfaceListener(adapter);
            listener.triggerEvent();
            shareCurrentPostViaWhatsAppFooter();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Footer WhatsApp. An ad uses the default ad screen's "share app with your
     * friends" WhatsApp send. A news post keeps the article share, which counts
     * only after WhatsApp returns RESULT_OK.
     */
    private void onFooterCenterWhatsappClicked() {
        if (footerWhatsappSharesTheApp()) {
            if (adapter != null) {
                adapter.shareAppWithFriendsOnWhatsApp();
            }
            return;
        }
        onArticleWhatsappClicked(getVisiblePostIndex());
    }

    /**
     * The drawn card is an ad or the share-the-app invite, so the footer
     * WhatsApp must not take the article-share path.
     */
    private boolean footerWhatsappSharesTheApp() {
        if (visibleFlipIsInviteOrAdShell()) {
            return true;
        }
        try {
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size()) {
                return false;
            }
            ModelClass.Datum item = list.get(idx);
            if (item == null) {
                return false;
            }
            if (ReadArticleStore.isAdFeedSlot(item)
                    || ReadArticleStore.isShareFeedSlot(item)
                    || ReadArticleStore.isRatingsFeedSlot(item)) {
                return true;
            }
            String type = item.getPostType();
            return type != null && type.trim().equalsIgnoreCase("web");
        } catch (Exception e) {
            return false;
        }
    }

