    public void onWhatsappShareCountUpdated(long postId, int count) {
    }

    /** Panchangam footer tab is product-off; the same menu id is the share column. */
    private boolean isFooterCalendarTabWanted() {
        try {
            return isDeviceOnline() && ProfileHubConfigHelper.isFooterShowCalendar(this);
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Empty middle menu column for blinking Share. Special keeps its own glyph.
     * Caller must already know the calendar tab is not wanted.
     */
    private void prepareMagazineShareCenterSlot(@Nullable MenuItem slot) {
        if (slot == null) {
            return;
        }
        // setIcon / setTitle / setVisible always notify the menu. setVisible(true)
        // when the slot was hidden rebuilds every item view. Skip when the spacer
        // is already in place so Reload does not rebuild the bar.
        CharSequence title = slot.getTitle();
        boolean titleEmpty = title == null || title.length() == 0;
        if (centerFooterSpacerPrepared && titleEmpty && slot.isVisible() && slot.isEnabled()) {
            return;
        }
        // setVisible(true) is a structure change: Material rebuilds every item
        // view from a LIFO pool. Suspend that, then paint the existing views.
        runWithFooterMenuUpdatesSuspended(() -> {
            if (!centerFooterSpacerPrepared) {
                slot.setIcon(new ColorDrawable(Color.TRANSPARENT));
            }
            if (!titleEmpty) {
                slot.setTitle("");
            }
            if (!slot.isVisible()) {
                slot.setVisible(true);
            }
            if (!slot.isEnabled()) {
                slot.setEnabled(true);
            }
        });
        refreshFooterItemViewsWithoutRebuild();
        centerFooterSpacerPrepared = slot.isVisible() && slot.isEnabled();
    }

    /**
     * Show or hide the middle footer column to match magazine / special-gallery Share.
     * Does not attach the blink to the Special tab.
     */
    private void ensureMagazineShareFooterSlot() {
        if (bottomNavigationView == null || bottomNavigationView.getMenu() == null) {
            return;
        }
        boolean calendar = isFooterCalendarTabWanted();
        boolean wantSpacer = wantsCenterFooterActionSlot();
        MenuItem slot = bottomNavigationView.getMenu().findItem(R.id.navigation_stricker);
        boolean spacerOpen = slot != null && slot.isVisible() && !calendar;
        if (wantSpacer == spacerOpen) {
            if (wantSpacer) {
                prepareMagazineShareCenterSlot(slot);
                hideShareCenterSlotChrome();
            }
            repositionCenterFabForVisibleTabs();
            return;
        }
        if (footerRebalanceDepth > 0) {
            return;
        }
        // News, Special, ads, and magazines keep this column open, so they never
        // reach here. Daily Updates is the toggle. Profile hides that same item
        // by painting the view that is already in the bar. A full rebalance
        // calls FooterStyleHelper on every label and that is the blink.
        if (footerTabsBesidesCenterAlreadyMatch()) {
            runWithoutFooterLayoutTransition(() -> {
                setCenterFooterSlotVisibleWithoutRebuild(slot, wantSpacer);
                if (wantSpacer) {
                    hideShareCenterSlotChrome();
                }
            });
            repositionCenterFabForVisibleTabs();
            return;
        }
        rebalanceFooterTabs();
    }

    /**
     * True when News, Special, Daily Updates, and Profile already match the
     * admin flags. The middle column can then open or close on its own.
     */
    private boolean footerTabsBesidesCenterAlreadyMatch() {
        if (bottomNavigationView == null || bottomNavigationView.getMenu() == null) {
            return false;
        }
        try {
            android.view.Menu menu = bottomNavigationView.getMenu();
            boolean online = isDeviceOnline();
            return footerMenuItemMatches(menu.findItem(R.id.navigation_home),
                    ProfileHubConfigHelper.isFooterShowReload(this))
                    && footerMenuItemMatches(menu.findItem(R.id.navigation_catagiries),
                    online && ProfileHubConfigHelper.isFooterShowSpecial(this))
                    && footerMenuItemMatches(menu.findItem(R.id.navigation_status),
                    online && ProfileHubConfigHelper.isFooterShowVideos(this))
                    && footerMenuItemMatches(menu.findItem(R.id.navigation_profile),
                    online && ProfileHubConfigHelper.isFooterShowProfile(this));
        } catch (Exception e) {
            return false;
        }
    }

    private static boolean footerMenuItemMatches(@Nullable MenuItem item, boolean wantVisible) {
        return item != null && item.isVisible() == wantVisible && item.isEnabled() == wantVisible;
    }

    /** Hide the spacer item's own icon and label; the Share overlay is the control. */
    private void hideShareCenterSlotChrome() {
        if (!wantsCenterFooterActionSlot() && !isCenterFooterActionSlotOpen()) {
            return;
        }
        View item = findFooterMenuItemView(R.id.navigation_stricker);
        if (item == null) {
            return;
        }
        View icon = item.findViewById(
                com.google.android.material.R.id.navigation_bar_item_icon_view);
        if (icon != null) {
            icon.setVisibility(View.INVISIBLE);
        }
        int smallId = getResources().getIdentifier(
                "navigation_bar_item_small_label_view", "id", getPackageName());
        int largeId = getResources().getIdentifier(
                "navigation_bar_item_large_label_view", "id", getPackageName());
        View small = smallId != 0 ? item.findViewById(smallId) : null;
        View large = largeId != 0 ? item.findViewById(largeId) : null;
        if (small != null) {
            small.setVisibility(View.INVISIBLE);
        }
        if (large != null) {
            large.setVisibility(View.INVISIBLE);
        }
    }

    private void startMagazineShareBlink() {
        if (ivMagazineShareFooter == null) {
            return;
        }
        stopMagazineShareBlink();
        ivMagazineShareFooter.setAlpha(1f);
        // Match R.anim.blink_share: ~1200ms one-way → ~2400ms full gentle pulse.
        ObjectAnimator animator = ObjectAnimator.ofFloat(ivMagazineShareFooter, View.ALPHA, 1f, 0.35f);
        animator.setDuration(1200);
        animator.setRepeatCount(ValueAnimator.INFINITE);
        animator.setRepeatMode(ValueAnimator.REVERSE);
        animator.setInterpolator(new AccelerateDecelerateInterpolator());
        magazineShareBlinkAnimator = animator;
        animator.start();
    }

    private void stopMagazineShareBlink() {
        if (magazineShareBlinkAnimator != null) {
            magazineShareBlinkAnimator.cancel();
            magazineShareBlinkAnimator = null;
        }
        if (ivMagazineShareFooter != null) {
            ivMagazineShareFooter.clearAnimation();
            ivMagazineShareFooter.setAlpha(1f);
        }
        if (layoutMagazineShareFooter != null) {
            layoutMagazineShareFooter.clearAnimation();
            layoutMagazineShareFooter.setAlpha(1f);
        }
    }

