    /**
     * Offline Video News: filter main offline pack to half/full video posts only.
     * @return true when at least one video item was painted
     */
    private boolean paintOfflineVideoFeed() {
        try {
            java.util.List<ModelClass.Datum> offline = OfflineFeedStore.loadForOfflinePaint(this);
            ArrayList<ModelClass.Datum> videos = new ArrayList<>();
            if (offline != null) {
                for (ModelClass.Datum d : offline) {
                    if (d != null && isVideoNewsPostType(d.getPostType())) {
                        videos.add(d);
                    }
                }
            }
            if (videos.isEmpty()) {
                EncreptionRequest cached = OpenPathCache.loadFeed(this, 0);
                if (cached == null) {
                    cached = OpenPathCache.loadFeedForOffline(this, 0);
                }
                if (cached != null) {
                    convertListOfArticles(cached, 0, true);
                    filterListToVideoPostsOnly(list);
                    if (list != null && !list.isEmpty()) {
                        rebindFlipperAdapterWithCurrentList();
                        if (txtNoData != null) txtNoData.setVisibility(View.GONE);
                        if (mFlipView != null) mFlipView.setVisibility(View.VISIBLE);
                        if (layout_with_data != null) layout_with_data.setVisibility(View.VISIBLE);
                        return true;
                    }
                }
                return false;
            }
            list = videos;
            requestSize = list.size();
            positionx = 0;
            lastSettledFlipIndex = -1;
            rebindFlipperAdapterWithCurrentList();
            if (txtNoData != null) txtNoData.setVisibility(View.GONE);
            if (mFlipView != null) mFlipView.setVisibility(View.VISIBLE);
            if (layout_with_data != null) layout_with_data.setVisibility(View.VISIBLE);
            return true;
        } catch (Exception e) {
            Logone.w(e, "paintOfflineVideoFeed");
            return false;
        }
    }

    /** Ensure FlipperAdapter exists and setData(list) after offline video paint. */
    private void rebindFlipperAdapterWithCurrentList() {
        try {
            if (type == null || type.isEmpty() || "null".equalsIgnoreCase(String.valueOf(type).trim())) {
                type = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
            }
            if (adapter == null && mFlipView != null) {
                adapter = new FlipperAdapter(Activity, HomePage.this, type, category_id, getLifecycle());
                adapter.setCallback(this);
                adapter.setCurrentFlipPage(positionx);
                mFlipView.setAdapter(adapter);
                mFlipView.setOnFlipListener(this);
                mFlipView.setOnFlipCompleteListener(this);
                mFlipView.setOverFlipMode(OverFlipMode.GLOW);
                mFlipView.peakNext(false);
                mFlipView.setOnOverFlipListener(this);
                mFlipView.setOnFlipAppear(this);
            }
            if (adapter != null && list != null) {
                adapter.setData(list);
            }
        } catch (Exception e) {
            showLog("rebindFlipperAdapterWithCurrentList: " + e.getMessage());
        }
    }

    /**
     * Paint main offline pack from disk when offline (unread-first when open log exists).
     * Special offline paint is intentionally blocked — use
     * {@link #showSpecialOfflineEmptyState()} instead.
     * <p>
     * FlipperAdapter keeps its own list; after any full replace we must call
     * {@link FlipperAdapter#setData} (notify alone is not enough when HomePage
     * reassigned {@link #list} or a brand-new adapter was created empty).
     * Same path for splash cold-open offline and mid-session network drop.
     */
    private boolean paintOfflineFeed(boolean special, boolean showToast) {
        try {
            if (special) {
                // Spec: Special never surfaces offline cache / bookmarks / half articles.
                showLog("paintOfflineFeed blocked for special (online-only tab)");
                return false;
            }
            // Local tab: never paint Offline News / main OpenPath — Main cards with
            // Anakapalli pin labels looked like Local when district was already set.
            if (category_id == -1 || localFeedFromDailyUpdates) {
                showLog("paintOfflineFeed blocked for Local");
                return false;
            }
            // Load fully before mutating UI so a failed load never blanks a good list.
            // Unread / not-opened first when ArticleOpenLog has ids; else pack order (newest).
            java.util.List<ModelClass.Datum> offline = OfflineFeedStore.loadForOfflinePaint(this);
            if (offline == null || offline.isEmpty()) {
                // Fall back to OpenPathCache page-0 (warm TTL first, then stale offline).
                EncreptionRequest cached = OpenPathCache.loadFeed(this, 0);
                if (cached == null) {
                    cached = OpenPathCache.loadFeedForOffline(this, 0);
                }
                if (cached != null) {
                    convertListOfArticles(cached, 0, true);
                    // Same media gate as OfflineFeedStore — never paint logo placeholders.
                    filterListToOfflineMediaReady(list);
                    if (list != null && !list.isEmpty()) {
                        try {
                            FeedEndHelper.ensureAtEnd(list, this);
                            no_article_message = FeedEndHelper.resolveMessage(this);
                            if (adapter != null) {
                                adapter.setData(list);
                            } else {
                                ensureHomeFlipAdapterBoundAndData(list);
                            }
                        } catch (Exception ignored) {
                        }
                    }
                    boolean ok = list != null && !list.isEmpty();
                    if (ok) {
                        applyOfflineMainFeedChrome(showToast);
                    }
                    return ok;
                }
                return false;
            }
            // Atomic full replace into a new list, then one setData — avoid empty intermediate.
            ArrayList<ModelClass.Datum> next = new ArrayList<>(offline);
            list = next;
            requestSize = list.size();
            positionx = 0;
            lastSettledFlipIndex = -1;
            // Prefer language-matched offline/prefs district (theme recreate / cold offline).
            String offlineDistrict = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
            if (type == null || type.isEmpty() || "null".equalsIgnoreCase(String.valueOf(type).trim())
                    || !DistrictLabelHelper.labelCompatibleWithLanguage(
                            type, SharedPrefsData.getInt(HomePage.this, Constants.LanguageID, Constants.PREF_NAME))) {
                if (!TextUtils.isEmpty(offlineDistrict)) {
                    type = offlineDistrict;
                } else {
                    type = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
                }
            }
            if (!TextUtils.isEmpty(offlineDistrict)
                    || DistrictLabelHelper.isUsable(type)) {
                try {
                    // Always use language-safe resolver for header; never paint a
                    // foreign-script offline string.
                    String resolved = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
                    if (DistrictLabelHelper.isUsable(resolved)) {
                        type = resolved;
                        if (local_distic_name != null) {
                            local_distic_name.setText(resolved);
                        }
                        if (selelcted_local_distic_name != null) {
                            selelcted_local_distic_name.setText(resolved);
                        }
                    } else {
                        DistrictLabelHelper.applyTo(
                                HomePage.this, local_distic_name, selelcted_local_distic_name);
                    }
                } catch (Exception ignored) {
                }
            }
            ensureHomeFlipAdapterBoundAndData(list);
            // Offline pack is finite — append end card so the next flip is never blank white.
            try {
                if (list != null && !list.isEmpty()) {
                    FeedEndHelper.ensureAtEnd(list, this);
                    no_article_message = FeedEndHelper.resolveMessage(this);
                    if (adapter != null) {
                        adapter.setData(list);
                    }
                }
            } catch (Exception ignored) {
            }
            applyOfflineMainFeedChrome(showToast);
            showLog("paintOfflineFeed special=false n=" + list.size());
            return true;
        } catch (Exception e) {
            Logone.w(e, "paintOfflineFeed");
            return false;
        }
    }

    /** Neutral in-flight marker — must never be confused with true end-of-feed. */
    private static final String FEED_LOADING_MESSAGE = "Please wait while loading ...";

    private boolean isFeedExhaustedMessage() {
        return FeedEndHelper.messageLooksLikeEnd(no_article_message)
                || "No articles to read further".equals(no_article_message);
    }

    /**
     * Drop stale EOF marker + accidental end sentinel so News/Special/Video can
     * keep loading older days (e.g. after Chadivindi ↔ News toggle).
     */
    private void clearSpuriousFeedExhaustedState() {
        no_article_message = FEED_LOADING_MESSAGE;
        // Keyword search Continue-reading hub is intentional — never strip it as a
        // Chadivindi / stale EOF leftover (that removed the hub on flip-settle).
        if (searchFeedActive
                && activeSearchQuery != null
                && !activeSearchQuery.trim().isEmpty()) {
            return;
        }
        stripFeedEndSentinelQuietly();
    }

    /**
     * Online News/Special/Video: only treat as truly exhausted when the end
     * sentinel is present, the exhausted message is set, <b>and</b> empty-page
     * auto-continue hit the cap. A leftover message/card from Read (Chadivindi)
     * or a single empty race is not EOF.
     */
    private boolean isOnlinePageableFeedTrulyExhausted() {
        return canPageActiveOnlineFlipFeed()
                && !bookmarksModeSelected
                && isFeedExhaustedMessage()
                && FeedEndHelper.hasAtEnd(list)
                && onlineNewsAllReadSkipStreak >= ONLINE_NEWS_ALL_READ_SKIP_CAP;
    }

    /**
     * Empty or fully-filtered List_All_Articles page while the deck already has
     * cards: advance cursors and keep paging older days. Do <b>not</b> insert
     * the end card (that was a race / filter / short-page false EOF).
     *
     * @return true if this empty page was handled (caller should return)
     */
    private boolean continuePagingAfterEmptyOrFilteredPage(
            @Nullable ModelClass validateUserOtp, @NonNull String reason) {
        if (validateUserOtp == null) {
            return false;
        }
        if (!canPageActiveOnlineFlipFeed() || bookmarksModeSelected || !isDeviceOnline()) {
            return false;
        }
        final boolean hasPaintables = list != null
                && ReadArticleStore.countPaintableArticles(list) > 0;
        // Soft-empty (no cards yet): allow auto-page; with cards: always prefer continue
        // over premature end card until consecutive-empty cap.
        if (onlineNewsAllReadSkipStreak >= ONLINE_NEWS_ALL_READ_SKIP_CAP) {
            showLog("empty page cap reached (" + reason + ") — true EOF");
            return false;
        }
        if (validateUserOtp.getLastPostId() != null) {
            last_post_id = validateUserOtp.getLastPostId();
        }
        if (validateUserOtp.getSkip() != null) {
            skip = validateUserOtp.getSkip();
        }
        if (validateUserOtp.getActualSkip() != null) {
            actual_skip = validateUserOtp.getActualSkip();
        }
        requestSize = list != null ? list.size() : 0;
        if (requestSize > 0) {
            requestPostition = Math.max(0, Math.min(requestSize - 1, Math.max(1, requestSize - 3)));
        } else {
            requestPostition = 1;
        }
        onlineNewsAllReadSkipStreak++;
        no_article_message = FEED_LOADING_MESSAGE;
        stripFeedEndSentinelQuietly();
        showLog("empty/filtered page continue (" + reason + ") streak="
                + onlineNewsAllReadSkipStreak
                + " list=" + requestSize
                + " skip=" + skip
                + " last_post_id=" + last_post_id);
        try {
            if (txtNoData != null) {
                txtNoData.setVisibility(View.GONE);
            }
            if (!hasPaintables) {
                showHomeFeedLoadingReveal();
            }
        } catch (Exception ignored) {
        }
        isApiRequested = false;
        final boolean videoFlag = isVideoFeedMode();
        final boolean specialFlag = isSpecialFeedMode();
        final boolean listHadPaintables = hasPaintables;
        new Handler(Looper.getMainLooper()).post(new Runnable() {
            @Override
            public void run() {
                if (isFinishing() || isDestroyed()) {
                    isApiRequested = false;
                    return;
                }
                if (!canPageActiveOnlineFlipFeed()
                        || bookmarksModeSelected
                        || videoFlag != isVideoFeedMode()
                        || specialFlag != isSpecialFeedMode()) {
                    isApiRequested = false;
                    return;
                }
                if (dummyResponse != null || isApiRequested) {
                    return;
                }
                isApiRequested = true;
                ShowNews_Data_Values(category_id, listHadPaintables ? 3 : 1);
            }
        });
        initialCall = true;
        return true;
    }

    /**
     * Append (or re-seat) the FlipView end card and optionally flip onto it.
     * Search: end card is the Continue-reading hub (never "no more news").
     * Used when pagination is exhausted, offline/read finite decks, or overflip
     * past the last real article — never leave a blank white FlipView page.
     */
    private void ensureFeedEndCardVisible(boolean flipToEnd) {
        try {
            if (list == null) {
                list = new ArrayList<>();
            }
            // Search: never leave native ad shells between hits and the hub.
            if (searchFeedActive) {
                try {
                    ReadArticleStore.stripAdFeedSlots(list);
                } catch (Exception ignored) {
                }
            }
            int paintablesBefore = ReadArticleStore.countPaintableArticles(list);
            // Search: never jump onto Continue-reading while hits exist.
            if (searchFeedActive && paintablesBefore > 0 && flipToEnd) {
                showLog("ANYNEWS_SEARCH ASSERT block flipToEnd hub — paintables="
                        + paintablesBefore);
                flipToEnd = false;
            }
            // Empty list + end card alone still beats a white FlipView.
            boolean mutated = FeedEndHelper.ensureAtEnd(list, this);
            no_article_message = FeedEndHelper.resolveMessage(this);
            requestSize = list.size();
            // Keep pagination trigger off the sentinel index.
            if (list.size() >= 2) {
                requestPostition = Math.max(0, list.size() - 2);
            }
            if (mutated || adapter == null) {
                ensureHomeFlipAdapterBoundAndData(list);
            } else if (adapter != null) {
                adapter.setData(list);
            }
            if (mFlipView != null) {
                mFlipView.setVisibility(View.VISIBLE);
            }
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null && list.size() > 0) {
                txtNoData.setVisibility(View.GONE);
            }
            if (flipToEnd && mFlipView != null && !list.isEmpty()) {
                final int endIdx = list.size() - 1;
                // Final guard: do not seat on hub when a prior hit is at index 0.
                if (searchFeedActive
                        && ReadArticleStore.countPaintableArticles(list) > 0
                        && FeedEndHelper.isFeedEnd(list.get(endIdx))) {
                    showLog("ANYNEWS_SEARCH ASSERT skip flipTo hub endIdx=" + endIdx);
                    forceSearchHitsOnPage0();
                    return;
                }
                positionx = endIdx;
                try {
                    mFlipView.flipTo(endIdx);
                } catch (Exception e) {
                    try {
                        mFlipView.smoothFlipTo(endIdx);
                    } catch (Exception ignored) {
                    }
                }
            } else if (searchFeedActive
                    && ReadArticleStore.countPaintableArticles(list) > 0) {
                forceSearchHitsOnPage0();
            }
            showLog("ensureFeedEndCardVisible flipToEnd=" + flipToEnd
                    + " size=" + list.size());
        } catch (Exception e) {
            Logone.w(e, "ensureFeedEndCardVisible");
        }
    }

    /** Drop end sentinel before merge / capture / page-0 replace. */
    private void stripFeedEndSentinelQuietly() {
        try {
            if (list != null) {
                FeedEndHelper.stripAll(list);
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * Ensure FlipperAdapter exists on {@link #mFlipView} and is bound to {@code data}.
     * Always uses setData so adapter count matches HomePage list after offline/reload.
     * After a successful non-empty list, also forces flip + content container visible
     * so cold open / News|Read toggle never ends on a blank white FlipView.
     */
    private void ensureHomeFlipAdapterBoundAndData(@Nullable ArrayList<ModelClass.Datum> data) {
        if (mFlipView == null) {
            return;
        }
        if (type == null || type.isEmpty() || "null".equalsIgnoreCase(String.valueOf(type).trim())
                || !DistrictLabelHelper.labelCompatibleWithLanguage(
                        type, SharedPrefsData.getInt(HomePage.this, Constants.LanguageID, Constants.PREF_NAME))) {
            String fromPrefs = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
            if (!TextUtils.isEmpty(fromPrefs)) {
                type = fromPrefs;
            } else {
                type = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
            }
        }
        boolean needNew = adapter == null || isFromLocalArticles;
        isFromLocalArticles = false;
        if (needNew) {
            adapter = new FlipperAdapter(Activity, HomePage.this, type, category_id, getLifecycle());
            adapter.setCallback(this);
            mFlipView.setAdapter(adapter);
            mFlipView.setOnFlipListener(this);
            mFlipView.setOnFlipCompleteListener(this);
            mFlipView.setOverFlipMode(OverFlipMode.GLOW);
            mFlipView.peakNext(false);
            mFlipView.setOnOverFlipListener(this);
            mFlipView.setOnFlipAppear(this);
        }
        if (adapter == null) {
            return;
        }
        int flipTo = 0;
        if (data != null && !data.isEmpty()) {
            // Search: never clamp a stale News positionx onto the last page (hub).
            if (searchFeedActive) {
                flipTo = 0;
            } else {
                flipTo = Math.max(0, Math.min(positionx, data.size() - 1));
            }
        }
        adapter.setCurrentFlipPage(flipTo);
        if (data != null) {
            if (searchFeedActive) {
                try {
                    if (mFlipView != null) {
                        mFlipView.beginForcedPage0Seat();
                    }
                } catch (Exception ignored) {
                }
                adapter.setDataImmediate(data);
            } else {
                adapter.setData(data);
            }
        }
        // First-paint guarantee: successful list must show the flip surface.
        if (data != null && !data.isEmpty()) {
            try {
                mFlipView.setVisibility(View.VISIBLE);
                if (layout_with_data != null) {
                    layout_with_data.setVisibility(View.VISIBLE);
                }
                if (txtNoData != null) {
                    txtNoData.setVisibility(View.GONE);
                }
                hideHomeFeedLoadingReveal(true);
                // Prefer not to open on a bare ad spinner if content exists.
                seatAwayFromUnfilledAdIfNeeded();
            } catch (Exception ignored) {
            }
        }
    }

    /**
     * Remember admin stickies from a main feed list so Read can re-apply sticky_position
     * for pins that have been session-viewed / committed into the local read store.
     */
    private void rememberFeedStickiesFrom(
            @androidx.annotation.Nullable java.util.List<ModelClass.Datum> items) {
        if (items == null || items.isEmpty()) return;
        if (isSpecialFeedMode() || isVideoFeedMode()) return;
        try {
            ArrayList<ModelClass.Datum> pins = ReadArticleStore.extractStickyArticles(items);
            if (pins.isEmpty()) return;
            java.util.LinkedHashMap<Long, ModelClass.Datum> byId = new java.util.LinkedHashMap<>();
            for (ModelClass.Datum d : rememberedFeedStickies) {
                if (d != null && d.getPostId() != null && d.getPostId() > 0) {
                    byId.put(d.getPostId(), d);
                }
            }
            for (ModelClass.Datum d : pins) {
                if (d != null && d.getPostId() != null && d.getPostId() > 0) {
                    byId.put(d.getPostId(), d);
                }
            }
            rememberedFeedStickies.clear();
            rememberedFeedStickies.addAll(byId.values());
        } catch (Exception ignored) {
        }
    }

    /** Shared chrome after main offline feed is painted (or OpenPath convert succeeded). */
    private void applyOfflineMainFeedChrome(boolean showToast) {
        hideHomeFeedLoadingReveal(true);
        hideBlockingNoInternetOverlay();
        try {
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null) {
                txtNoData.setVisibility(View.GONE);
            }
            if (mFlipView != null) {
                mFlipView.setVisibility(View.VISIBLE);
            }
            if (comment_page != null) {
                comment_page.setVisibility(View.GONE);
            }
        } catch (Exception ignored) {
        }
        if (showToast) {
            // Saved-news copy is a system Toast (app icon + text on Android 12+).
            // It draws over WhatsApp, the browser, and the home screen if posted
            // while this activity is stopped. Announce only from the foreground,
            // only when the device has no network path, and only once per offline
            // session. Server errors, timeouts, and captive-portal flaps while a
            // network path exists must not post it.
            maybeAnnounceOfflineSavedNews();
        }
        try {
            refreshHomeModeToggleUi();
            refreshHomeModeCounts();
            rebalanceFooterTabs();
        } catch (Exception ignored) {
        }
    }

    /**
     * Schedule the saved-news toast only while Home is in the foreground and the
     * device has no network path. The post is delayed so a handoff blip never
     * shows it, and a second call in the same offline session is ignored.
     */
    private void maybeAnnounceOfflineSavedNews() {
        if (offlineSavedNewsAnnounced || offlineSavedNewsToastPending) return;
        if (!canShowOfflineSavedNewsToast()) return;
        if (isNetworkConnected()) return;
        offlineSavedNewsToastPending = true;
        networkRestoreHandler.postDelayed(
                offlineSavedNewsToastRunnable, OFFLINE_SAVED_NEWS_CONFIRM_MS);
    }

    private void showOfflineSavedNewsToastIfStillOffline() {
        offlineSavedNewsToastPending = false;
        if (offlineSavedNewsAnnounced) return;
        if (!canShowOfflineSavedNewsToast()) return;
        // Came back during the confirm window, or the link never really dropped.
        if (isNetworkConnected()) return;
        offlineSavedNewsAnnounced = true;
        try {
            if (offlineSavedNewsToast != null) {
                offlineSavedNewsToast.cancel();
                offlineSavedNewsToast = null;
            }
            offlineSavedNewsToast = Toast.makeText(
                    this, R.string.offline_showing_saved_news, Toast.LENGTH_SHORT);
            offlineSavedNewsToast.show();
        } catch (Exception ignored) {
        }
    }

    /** Home is the resumed screen. A system toast posted otherwise floats on other apps. */
    private boolean canShowOfflineSavedNewsToast() {
        return homeActivityResumed && !isFinishing() && !isDestroyed();
    }

    private void cancelPendingOfflineSavedNewsToast() {
        offlineSavedNewsToastPending = false;
        try {
            networkRestoreHandler.removeCallbacks(offlineSavedNewsToastRunnable);
        } catch (Exception ignored) {
        }
    }

    /** Remove a visible or queued saved-news toast. Does not arm the next announcement. */
    private void dismissOfflineSavedNewsToast() {
        cancelPendingOfflineSavedNewsToast();
        if (offlineSavedNewsToast != null) {
            try {
                offlineSavedNewsToast.cancel();
            } catch (Exception ignored) {
            }
            offlineSavedNewsToast = null;
        }
    }

    /** After a debounced return online, the next real offline may announce once. */
    private void resetOfflineSavedNewsAnnouncement() {
        offlineSavedNewsAnnounced = false;
        dismissOfflineSavedNewsToast();
    }

    /**
     * Page-0 cursor/sticky reset without wiping the in-memory list or FlipperAdapter.
     * Used for offline Reload so a good feed stays up until paintOfflineFeed rebinds.
     */
    private void prepareOfflineMainReloadCursors() {
        clearPendingFlipRestore();
        clearStickyPushPostId();
        SHARE_ID = 0;
        SHARE_REDIRECT_ID = "0";
        DATAFROM2G = "0";
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        positionx = 0;
        lastSettledFlipIndex = -1;
        requestSize = 0;
        requestPostition = 1;
        isApiRequested = false;
        isDataParsed = true;
        isFromLocalArticles = true; // force Flipper rebuild on next paint
        dummyResponse = null;
        clearNativeAdPools();
        OpenPathCache.clearForceFeedNetwork();
        category_id = 0;
    }

    /**
     * Main Reload offline with no OfflineFeedStore / OpenPathCache — empty Offline News
     * feed chrome, not the full-screen “No internet!” layout (footer + pill stay).
     */
    private void showMainOfflineEmptyState() {
        try {
            hideHomeFeedLoadingReveal(true);
            hideBlockingNoInternetOverlay();
            if (list == null) {
                list = new ArrayList<>();
            } else {
                list.clear();
            }
            requestSize = 0;
            if (adapter != null) {
                try {
                    adapter.setData(list);
                } catch (Exception ignored) {
                }
            }
            if (mFlipView != null) {
                mFlipView.setVisibility(View.GONE);
            }
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null) {
                txtNoData.setVisibility(View.VISIBLE);
            }
            // Keep Offline News | Bookmarks + News footer (yes_internet stays visible).
            try {
                refreshHomeModeToggleUi();
                refreshHomeModeCounts();
                rebalanceFooterTabs();
            } catch (Exception ignored) {
            }
        } catch (Exception e) {
            Logone.w(e, "showMainOfflineEmptyState");
        }
    }

    private JsonObject getCommentRequestData(long post_id, long sub_post_id, String comment, Long parentId) {
        ListOfCommentsRequest requestModel = new ListOfCommentsRequest();
        requestModel.setDraftId(SharedPrefsData.getInt(getApplicationContext(), Constants.DraftID, Constants.PREF_NAME));
        requestModel.setPostId(post_id);
        requestModel.setSubPostId(sub_post_id);
        requestModel.setUserid(allsharedpreference.getEmailId());
        requestModel.setComment(comment != null ? comment : "");
        requestModel.setLanguageId(SharedPrefsData.getInt(getApplicationContext(), Constants.LanguageID, Constants.PREF_NAME));
        if (parentId != null && parentId > 0) {
            requestModel.setParentCommentId(parentId);
        }

        String jsonString = new com.google.gson.Gson().toJson(requestModel);
        showLog("API COMMENT REQUEST :" + jsonString);
        String encrpt_data = encrypt(jsonString);
        EncritonRequestData Encriton_Request = new EncritonRequestData();
        Encriton_Request.setData(encrpt_data);
        return new Gson().toJsonTree(Encriton_Request).getAsJsonObject();
    }

    private void setCommentSendChromeBusy(boolean busy) {
        commentSubmitInFlight = busy;
        if (comment_progress != null) {
            comment_progress.setVisibility(busy ? View.VISIBLE : View.GONE);
        }
        if (send_btn_layout != null) {
            send_btn_layout.setEnabled(!busy);
            if (!busy) {
                CharSequence text = leave_comment_white != null ? leave_comment_white.getText() : null;
                send_btn_layout.setVisibility(
                        text != null && text.toString().trim().length() > 0 ? View.VISIBLE : View.GONE);
            } else {
                send_btn_layout.setVisibility(View.GONE);
            }
        }
    }

    /** Re-apply remembered comment count after closing the comments sheet. */
    private void refreshVisibleCommentCountChrome() {
        try {
            if (adapter == null || list == null) return;
            int idx = getVisiblePostIndex();
            if (idx < 0 || idx >= list.size() || list.get(idx) == null) return;
            ModelClass.Datum item = list.get(idx);
            if (item.getPostId() == null) return;
            Integer comments = item.getComments();
            if (comments == null) comments = 0;
            adapter.syncCommentCountFromServer(
                    item.getPostId(), item.getSubPostId(), comments, true);
        } catch (Exception e) {
            Logone.w(e, "refreshVisibleCommentCountChrome");
        }
    }

    /**
     * Apply list-of-comments API payload to the sheet + engagement badge.
     * One light retry when the feed badge was &gt;0 but the sheet came back empty
     * (transient / sync lag) — no polling loop.
     */
    private void applyCommentsListResponse(long post_id, long sub_post_id,
                                           ListOfCommentsResponse validateUserOtp,
                                           boolean isRetry) {
        if (validateUserOtp == null || !Boolean.TRUE.equals(validateUserOtp.getSuccess())) {
            return;
        }
        List<ListOfCommentsResponse.Datum> rows = validateUserOtp.getData();
        int serverCount = validateUserOtp.getCount() != null
                ? validateUserOtp.getCount()
                : (rows != null ? rows.size() : 0);
        int priorBadge = 0;
        try {
            if (list != null) {
                for (int i = 0; i < list.size(); i++) {
                    ModelClass.Datum item = list.get(i);
                    if (item != null && item.getPostId() != null
                            && item.getPostId() == post_id
                            && item.getComments() != null) {
                        priorBadge = item.getComments();
                        break;
                    }
                }
            }
        } catch (Exception ignored) {
        }

        comment_chooseLanguage_models = new ArrayList<>();
        if (rows != null && !rows.isEmpty()) {
            final boolean parentalOn = SharedPrefsData.getBool(
                    HomePage.this, Constants.PARENTAL_CONTROL, Constants.PREF_NAME, false);
            for (int i = 0; i < rows.size(); i++) {
                ListOfCommentsResponse.Datum src = rows.get(i);
                if (parentalOn && looksAbusiveComment(src != null ? src.getComment() : null)) {
                    continue;
                }
                comment_chooseLanguage_models.add(mapCommentDatum(src));
            }
        }

        boolean sheetEmpty = comment_chooseLanguage_models.isEmpty();
        if (sheetEmpty && priorBadge > 0 && serverCount <= 0 && !isRetry) {
            if (adapter != null) {
                adapter.syncCommentCountFromServer(post_id, sub_post_id, priorBadge, true);
            }
            linear_no_comment_page.setVisibility(View.VISIBLE);
            if (comment_recycler_view != null) {
                comment_recycler_view.setVisibility(View.INVISIBLE);
            }
            if (comment_page != null) {
                comment_page.postDelayed(() -> {
                    if (comment_page != null && comment_page.isShown()) {
                        OpenComments(post_id, sub_post_id, true);
                    }
                }, 700);
            }
            return;
        }

        if (adapter != null) {
            boolean allowZero = sheetEmpty && (isRetry || priorBadge <= 0);
            int paintCount;
            if (!sheetEmpty) {
                paintCount = Math.max(serverCount, comment_chooseLanguage_models.size());
                allowZero = true;
            } else if (allowZero) {
                paintCount = Math.max(0, serverCount);
            } else {
                paintCount = priorBadge;
            }
            adapter.syncCommentCountFromServer(post_id, sub_post_id, paintCount, allowZero);
        }

        if (sheetEmpty) {
            comment_recycler_view.setVisibility(View.INVISIBLE);
            linear_no_comment_page.setVisibility(View.VISIBLE);
        } else {
            bindCommentsAdapter();
        }
    }

    private void WriteComments() {
        if (commentSubmitInFlight) {
            return;
        }
        linear_no_comment_page.setVisibility(View.GONE);

        long resolvedPostId = commentsSheetPostId;
        long resolvedSubPostId = commentsSheetSubPostId;
        if (resolvedPostId <= 0) {
            int idx = getVisiblePostIndex();
            if (list == null || idx < 0 || idx >= list.size() || list.get(idx) == null) {
                idx = positionx;
            }
            if (list != null && idx >= 0 && idx < list.size() && list.get(idx) != null) {
                if (list.get(idx).getPostId() != null) {
                    resolvedPostId = list.get(idx).getPostId();
                }
                if (list.get(idx).getSubPostId() != null) {
                    resolvedSubPostId = list.get(idx).getSubPostId();
                }
            }
        }
        if (resolvedPostId <= 0) {
            Toast.makeText(this, "Unable to send comment", Toast.LENGTH_SHORT).show();
            return;
        }
        final long post_id = resolvedPostId;
        final long sub_post_id = resolvedSubPostId;
        final Long parentIdSnapshot = replyParentCommentId;
        final String textBody = leave_comment_white.getText() != null
                ? leave_comment_white.getText().toString()
                : "";
        if (textBody.trim().isEmpty()) {
            Toast.makeText(this, "Comment is empty", Toast.LENGTH_LONG).show();
            return;
        }
        final long sentAtMs = System.currentTimeMillis();

        if (!isDeviceOnline()) {
            try {
                OfflineActionQueue.enqueueComment(
                        getApplicationContext(),
                        post_id,
                        sub_post_id,
                        textBody,
                        parentIdSnapshot,
                        allsharedpreference.getEmailId());
                leave_comment_white.setText("");
                clearReplyContext();
                if (adapter != null) {
                    adapter.incrementCommentCountForPost(post_id, sub_post_id);
                }
                Toast.makeText(this, R.string.offline_action_queued, Toast.LENGTH_SHORT).show();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return;
        }

        JsonObject otp;
        try {
            otp = getCommentRequestData(post_id, sub_post_id, textBody, parentIdSnapshot);
        } catch (Exception e) {
            toastCommentSendFailure(null);
            return;
        }
        setCommentSendChromeBusy(true);

        APIService apiService = RestApiClient.getClient().create(APIService.class);
        Call<EncreptionRequest> otp_generation = apiService.comment("v3", otp);
        try {
            otp_generation.enqueue(new Callback<EncreptionRequest>() {

                @Override
                public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                    CommentResponuse parsed = null;
                    boolean parsedOk = false;
                    try {
                        EncreptionRequest encreptionRequest = response != null ? response.body() : null;
                        if (encreptionRequest != null && encreptionRequest.getData() != null) {
                            String encrpt_data = decrypt(encreptionRequest.getData());
                            parsed = new Gson().fromJson(encrpt_data, CommentResponuse.class);
                            parsedOk = parsed != null;
                        }
                    } catch (Exception e) {
                        parsedOk = false;
                    }

                    if (parsedOk && parsed.wasSaved()) {
                        setCommentSendChromeBusy(false);
                        applySuccessfulCommentSend(post_id, sub_post_id, parentIdSnapshot, parsed.getComments());
                        return;
                    }
                    if (parsedOk && Boolean.FALSE.equals(parsed.getSuccess())
                            && !Boolean.TRUE.equals(parsed.getSaved())) {
                        setCommentSendChromeBusy(false);
                        toastCommentSendFailure(parsed.getMsg());
                        return;
                    }
                    // Timeout, empty body, or an error after the row was stored.
                    confirmSavedCommentOrToast(post_id, sub_post_id, textBody, parentIdSnapshot, sentAtMs);
                }

                @Override
                public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                    confirmSavedCommentOrToast(post_id, sub_post_id, textBody, parentIdSnapshot, sentAtMs);
                }
            });
        } catch (Exception e) {
            setCommentSendChromeBusy(false);
            toastCommentSendFailure(null);
        }
    }

    private void applySuccessfulCommentSend(long post_id, long sub_post_id, Long parentIdSnapshot, Integer serverCount) {
        if (parentIdSnapshot != null && parentIdSnapshot > 0) {
            pendingExpandParentId = parentIdSnapshot;
        }
        if (leave_comment_white != null) {
            leave_comment_white.setText("");
        }
        clearReplyContext();
        refreshCommentComposeHint();
        if (adapter != null) {
            adapter.incrementCommentCountForPost(post_id, sub_post_id);
        }
        if (serverCount != null && adapter != null) {
            adapter.syncCommentCountFromServer(post_id, sub_post_id, serverCount, true);
        }
        OpenComment(post_id, sub_post_id);
    }

    private void toastCommentSendFailure(String serverMsg) {
        String message = serverMsg == null ? "" : serverMsg.trim();
        String lower = message.toLowerCase(Locale.US);
        boolean showServer = !message.isEmpty()
                && message.length() <= 140
                && !lower.contains("e11000")
                && !lower.contains("mongo")
                && !lower.contains("exception")
                && !lower.contains("syntax");
        Toast.makeText(
                HomePage.this,
                showServer ? message : "Comment failed — try again",
                Toast.LENGTH_SHORT).show();
    }

    /**
     * Add_Comment can store the row and still drop the HTTP response (timeout,
     * proxy, or a throw after save). If this draft's text is already in the
     * thread, treat the send as success instead of a generic failure toast.
     */
    private void confirmSavedCommentOrToast(long postId, long subPostId, String textBody,
                                            Long parentId, long sentAtMs) {
        try {
            JsonObject otp = getAllCommentRequestData(postId, subPostId);
            APIService apiService = RestApiClient.getClient().create(APIService.class);
            apiService.List_All_Comment_For_Article("v3", otp)
                    .enqueue(new Callback<EncreptionRequest>() {
                        @Override
                        public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                            boolean found = false;
                            ListOfCommentsResponse parsed = null;
                            try {
                                EncreptionRequest body = response != null ? response.body() : null;
                                if (body != null && body.getData() != null) {
                                    parsed = new Gson().fromJson(
                                            decrypt(body.getData()), ListOfCommentsResponse.class);
                                    found = commentListContainsRecentSend(
                                            parsed, textBody, parentId, sentAtMs);
                                }
                            } catch (Exception ignored) {
                            }
                            setCommentSendChromeBusy(false);
                            if (found && parsed != null) {
                                if (parentId != null && parentId > 0) {
                                    pendingExpandParentId = parentId;
                                }
                                if (leave_comment_white != null) {
                                    leave_comment_white.setText("");
                                }
                                clearReplyContext();
                                refreshCommentComposeHint();
                                applyCommentsListResponse(postId, subPostId, parsed, false);
                                return;
                            }
                            toastCommentSendFailure(null);
                        }

                        @Override
                        public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                            setCommentSendChromeBusy(false);
                            toastCommentSendFailure(null);
                        }
                    });
        } catch (Exception e) {
            setCommentSendChromeBusy(false);
            toastCommentSendFailure(null);
        }
    }

    private boolean commentListContainsRecentSend(ListOfCommentsResponse parsed, String textBody,
                                                  Long parentId, long sentAtMs) {
        if (parsed == null || !Boolean.TRUE.equals(parsed.getSuccess()) || parsed.getData() == null) {
            return false;
        }
        String want = textBody == null ? "" : textBody.trim();
        if (want.isEmpty()) {
            return false;
        }
        long wantParent = parentId != null && parentId > 0 ? parentId : 0L;
        int myDraft = SharedPrefsData.getInt(this, Constants.DraftID, Constants.PREF_NAME);
        for (int i = 0; i < parsed.getData().size(); i++) {
            ListOfCommentsResponse.Datum row = parsed.getData().get(i);
            if (row == null || row.getComment() == null) {
                continue;
            }
            if (!want.equals(row.getComment().trim())) {
                continue;
            }
            long rowParent = row.getParentCommentId() != null ? row.getParentCommentId() : 0L;
            if (rowParent != wantParent) {
                continue;
            }
            if (myDraft > 0 && (row.getDraftId() == null || row.getDraftId() != myDraft)) {
                continue;
            }
            Long commentTime = row.getCommentTime();
            if (commentTime == null || commentTime < sentAtMs - 15000L) {
                continue;
            }
            return true;
        }
        return false;
    }

    private JsonObject getAllCommentRequestData(long post_id, long sub_post_id) {

        ListOfCommentsRequest requestModel = new ListOfCommentsRequest();
        requestModel.setDraftId(SharedPrefsData.getInt(getApplicationContext(), Constants.DraftID, Constants.PREF_NAME));
        requestModel.setPostId(post_id);
        requestModel.setSubPostId(sub_post_id);
        requestModel.setUserid(allsharedpreference.getEmailId());
        requestModel.setLanguageId(SharedPrefsData.getInt(getApplicationContext(), Constants.LanguageID, Constants.PREF_NAME));


        String jsonString = new com.google.gson.Gson().toJson(requestModel);
        String encrpt_data = null;
        showLog("API REQUEST E" + jsonString.toString());
        encrpt_data = encrypt(jsonString);
        EncritonRequestData Encriton_Request = new EncritonRequestData();
        Encriton_Request.setData(encrpt_data);
        return new Gson().toJsonTree(Encriton_Request).getAsJsonObject();
    }

    private void OpenComment(long post_id, long sub_post_id) {
        showProgress();
        setCommentArticleTitleFromCurrentPost();
        refreshCommentComposeHint();
        comment_chooseLanguage_models = new ArrayList<>();
        comment_chooseLanguage_models.clear();
        JsonObject otp = getAllCommentRequestData(post_id, sub_post_id);
        linear_no_comment_page.setVisibility(View.GONE);


        APIService apiService = RestApiClient.getClient().create(APIService.class);
        Call<EncreptionRequest> otp_generation = apiService.List_All_Comment_For_Article("v3", otp);
        try {
            otp_generation.enqueue(new Callback<EncreptionRequest>() {

                @Override
                public void onResponse(Call<EncreptionRequest> call, Response<EncreptionRequest> response) {
                    hideProgress();
                    EncreptionRequest encreptionRequest = response.body();
                    if (encreptionRequest == null || encreptionRequest.getData() == null) {
                        refreshVisibleCommentCountChrome();
                        return;
                    }
                    String encrpt_data = decrypt(encreptionRequest.getData());
                    showLog("comments response:"+encrpt_data);

                    Gson gsonObj = new Gson();
                    ListOfCommentsResponse validateUserOtp = gsonObj.fromJson(encrpt_data, ListOfCommentsResponse.class);
                    applyCommentsListResponse(post_id, sub_post_id, validateUserOtp, false);
                }

                @Override
                public void onFailure(Call<EncreptionRequest> call, Throwable t) {
                    hideProgress();
                    refreshVisibleCommentCountChrome();
                }
            });

        } catch (Exception e) {
            hideProgress();
            refreshVisibleCommentCountChrome();
        }


    }

    public void inlist(int category_id) {

        this.category_id = category_id;
        list = new ArrayList<>();
        dummyResponse=null;
        pruneImpressedNativeAdsKeepWarm();
        showLog("inlist called:"+category_id);
        initialCall=false;
        // Highlight Special / News before the request so a News-tab guard cannot
        // cancel an intentional Special open, and a stuck Special flag cannot
        // ride a News highlight.
        syncFooterSelectionToFeedMode();
        try {
            ShowNews_Data_Values(category_id,-1);
        } finally {
            explicitSpecialOpen = false;
        }

        try {

            allsharedpreference = new Allsharedpreference(HomePage.this);
            Gson gson = new Gson();
            String Translation = allsharedpreference.getShared_String(Allsharedpreference.Translator);
            if (Translation != null && !Translation.isEmpty()) {
                languageModelResponse = gson.fromJson(Translation, LanguageModelResponse.class);
            }

            if (languageModelResponse != null && languageModelResponse.getData() != null) {
                showLog("");
                showLog("Check Point #6 language response is not null");
                my_feed.setText("" + languageModelResponse.getData().getMyFeed());
                my_feed_text.setText("" + languageModelResponse.getData().getMyFeed());

                applyFooterTabLabelsFromTranslator();
                fab_fullpost.setText("" + languageModelResponse.getData().getFullPost());
                fab_video.setText("" + languageModelResponse.getData().getVideoPost());
                fab_article.setText("" + languageModelResponse.getData().getArticle());
                nodatascreen.setText("" + languageModelResponse.getData().getNoData());
                leave_comment_white.setHint("" + languageModelResponse.getData().getWriteComments());
                applyMagazineShareFooterLabel();

                // Local → Pradhana (→ Main); Main → district (→ Local);
                // category → category name.
                type = resolveLocationPillTypeForCategory(category_id);

                showLog("List size:"+list.size());

                // IMPORTANT: ShowNews_Data_Values may already paint page-0 from disk
                // (sync) into list + adapter. FlipperAdapter() starts with its own
                // empty list — re-bind list after setAdapter or cache paint is wiped
                // and warm reopen can skip network → permanent blank feed.
                bindHomeFlipAdapter(type, category_id, list != null && !list.isEmpty());

            } else {
                // Translator prefs not ready: still attach adapter so network/cache paint works.
                showLog("inlist: languageModelResponse null — binding adapter without chrome labels");
                if (type == null || type.isEmpty() || "null".equalsIgnoreCase(String.valueOf(type).trim())) {
                    type = resolveLocationPillTypeForCategory(category_id);
                    if (TextUtils.isEmpty(type)) {
                        type = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
                    }
                    if (TextUtils.isEmpty(type)) {
                        type = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
                    }
                }
                bindHomeFlipAdapter(type, category_id, list != null && !list.isEmpty());
            }

        } catch (Exception e) {
            e.printStackTrace();
            // Guarantee adapter exists even if translator parse fails.
            try {
                if (type == null || type.isEmpty() || "null".equalsIgnoreCase(String.valueOf(type).trim())) {
                    type = resolveLocationPillTypeForCategory(category_id);
                    if (TextUtils.isEmpty(type)) {
                        type = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
                    }
                    if (TextUtils.isEmpty(type)) {
                        type = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
                    }
                }
                bindHomeFlipAdapter(type, category_id, list != null && !list.isEmpty());
            } catch (Exception ignored) {
            }
        }

    }

    /**
     * Footer location-pill label passed into {@link FlipperAdapter}.
     * Pill shows the <em>redirection destination</em>, not the current feed:
     * <ul>
     *   <li>Local ({@code -1}) → {@code getMyFeed()} / ప్రధాన వార్తలు (click → Main)</li>
     *   <li>Main ({@code 0}) → selected district name (click → Local)</li>
     *   <li>Category ({@code > 0}) → that category's display name
     *       (intent extra / prefs / {@link CategoriesDiskCache})</li>
     * </ul>
     */
    @NonNull
    private String resolveLocationPillTypeForCategory(int catId) {
        // Local: redirection label = Main (Pradhana Varthalu).
        if (catId == -1) {
            String myFeed = resolveTranslatorMyFeedLabel();
            if (DistrictLabelHelper.isUsable(myFeed)) {
                return myFeed;
            }
            if (DistrictLabelHelper.isUsable(type) && isTranslatorMyFeedLabel(type)) {
                return type;
            }
            return type != null ? type : "";
        }
        if (catId > 0) {
            String categoryName = resolveCategoryFeedLabel(catId);
            if (DistrictLabelHelper.isUsable(categoryName)) {
                return categoryName;
            }
            // Prefer an already-bound category title over wrongly showing Main's getMyFeed.
            if (DistrictLabelHelper.isUsable(type)
                    && !isTranslatorMyFeedLabel(type)) {
                return type;
            }
            return type != null ? type : "";
        }
        // Main (0): always district (redirection = Local).
        String district = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
        if (DistrictLabelHelper.isUsable(district)) {
            return district;
        }
        String offline = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
        if (DistrictLabelHelper.isUsable(offline)) {
            return offline;
        }
        return type != null ? type : "";
    }

    /**
     * Persist / read the human category title for {@code catId > 0} feeds so the
     * location pill can show Politics / Sports / etc. instead of getMyFeed().
     */
    private void rememberCategoryFeedNameFromIntent(@Nullable Intent intent, int catId) {
        if (catId <= 0) return;
        String fromExtra = null;
        try {
            if (intent != null && intent.hasExtra(EXTRA_CATEGORY_NAME)) {
                fromExtra = intent.getStringExtra(EXTRA_CATEGORY_NAME);
                intent.removeExtra(EXTRA_CATEGORY_NAME);
            }
        } catch (Exception ignored) {
        }
        if (DistrictLabelHelper.isUsable(fromExtra)) {
            persistCategoryFeedName(catId, fromExtra.trim());
            return;
        }
        // Warm disk list from Profile/Search so pill is correct even without the extra.
        String fromCache = resolveCategoryNameFromDisk(catId);
        if (DistrictLabelHelper.isUsable(fromCache)) {
            persistCategoryFeedName(catId, fromCache.trim());
        }
    }

    private void persistCategoryFeedName(int catId, @NonNull String name) {
        try {
            SharedPrefsData.putInt(this, Constants.CategoryID, catId, Constants.PREF_NAME);
            SharedPrefsData.putString(this, Constants.CategoryName, name, Constants.PREF_NAME);
        } catch (Exception ignored) {
        }
    }

    @Nullable
    private String resolveCategoryFeedLabel(int catId) {
        if (catId <= 0) return null;
        try {
            Intent intent = getIntent();
            if (intent != null) {
                String fromExtra = intent.getStringExtra(EXTRA_CATEGORY_NAME);
                if (DistrictLabelHelper.isUsable(fromExtra)) {
                    return fromExtra.trim();
                }
            }
        } catch (Exception ignored) {
        }
        try {
            int storedId = SharedPrefsData.getInt(this, Constants.CategoryID, Constants.PREF_NAME);
            if (storedId == catId) {
                String stored = SharedPrefsData.getString(
                        this, Constants.CategoryName, Constants.PREF_NAME);
                if (DistrictLabelHelper.isUsable(stored)) {
                    return stored.trim();
                }
            }
        } catch (Exception ignored) {
        }
        return resolveCategoryNameFromDisk(catId);
    }

    @Nullable
    private String resolveCategoryNameFromDisk(int catId) {
        try {
            int langId = SharedPrefsData.getInt(
                    this, Constants.LanguageID, Constants.PREF_NAME);
            return CategoriesDiskCache.lookupName(this, langId, catId);
        } catch (Exception ignored) {
            return null;
        }
    }

    private boolean isTranslatorMyFeedLabel(@Nullable String label) {
        if (!DistrictLabelHelper.isUsable(label)) return false;
        String myFeed = resolveTranslatorMyFeedLabel();
        if (!DistrictLabelHelper.isUsable(myFeed)) return false;
        return label.trim().equalsIgnoreCase(myFeed.trim());
    }

    @Nullable
    private String resolveTranslatorMyFeedLabel() {
        try {
            if (languageModelResponse != null
                    && languageModelResponse.getData() != null
                    && languageModelResponse.getData().getMyFeed() != null) {
                return languageModelResponse.getData().getMyFeed().toString();
            }
            String translation = allsharedpreference.getShared_String(Allsharedpreference.Translator);
            if (translation != null && !translation.isEmpty()) {
                LanguageModelResponse parsed =
                        new Gson().fromJson(translation, LanguageModelResponse.class);
                if (parsed != null && parsed.getData() != null
                        && parsed.getData().getMyFeed() != null) {
                    return parsed.getData().getMyFeed().toString();
                }
            }
        } catch (Exception ignored) {
        }
        return null;
    }

    /**
     * Attach FlipperAdapter to mFlipView and re-bind any articles already in
     * {@link #list} (e.g. OpenPathCache disk paint before this method ran).
     */
    private void bindHomeFlipAdapter(String feedType, int catId, boolean rebindExistingList) {
        if (mFlipView == null) {
            return;
        }
        int langId = SharedPrefsData.getInt(HomePage.this, Constants.LanguageID, Constants.PREF_NAME);
        // Category titles / Local Pradhana come from translator or List_All_Categories —
        // do not apply district-script compatibility (that can wipe getMyFeed()).
        boolean feedTypeBad;
        if (catId > 0 || catId == -1) {
            feedTypeBad = feedType == null || feedType.isEmpty()
                    || "null".equalsIgnoreCase(feedType.trim());
        } else {
            feedTypeBad = feedType == null || feedType.isEmpty()
                    || "null".equalsIgnoreCase(feedType.trim())
                    || !DistrictLabelHelper.labelCompatibleWithLanguage(feedType, langId);
        }
        if (feedTypeBad) {
            if (catId > 0) {
                String catName = resolveCategoryFeedLabel(catId);
                if (DistrictLabelHelper.isUsable(catName)) {
                    feedType = catName;
                    feedTypeBad = false;
                }
            } else if (catId == -1) {
                // Local: Pradhana redirect label (never district).
                String myFeed = resolveTranslatorMyFeedLabel();
                if (DistrictLabelHelper.isUsable(myFeed)) {
                    feedType = myFeed;
                    feedTypeBad = false;
                }
            }
            // Main (and Local if translator missing): district prefs for Main only.
            if (feedTypeBad && catId != -1) {
                feedType = OfflineFeedStore.ensureDistrictPrefs(HomePage.this);
                if (TextUtils.isEmpty(feedType)) {
                    feedType = DistrictLabelHelper.resolveDisplayLabel(HomePage.this);
                }
            }
        }
        if (feedType != null && !feedType.isEmpty() && !"null".equalsIgnoreCase(feedType.trim())) {
            type = feedType;
        }
        adapter = new FlipperAdapter(Activity, HomePage.this, feedType, catId, getLifecycle());
        adapter.setCallback(this);
        adapter.setCurrentFlipPage(positionx);
        mFlipView.setAdapter(adapter);
        mFlipView.setOnFlipListener(this);
        mFlipView.setOnFlipCompleteListener(this);
        mFlipView.setOverFlipMode(OverFlipMode.GLOW);
        mFlipView.peakNext(false);
        mFlipView.setOnOverFlipListener(this);
        mFlipView.setOnFlipAppear(this);
        if (rebindExistingList && list != null && !list.isEmpty()) {
            showLog("bindHomeFlipAdapter rebind list size=" + list.size());
            adapter.setData(list);
            mFlipView.setVisibility(View.VISIBLE);
            hideHomeFeedLoadingReveal(true);
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.VISIBLE);
            }
            if (txtNoData != null) {
                txtNoData.setVisibility(View.GONE);
            }
        }
    }

    /**
     * One-shot push deep-link: never re-send a consumed/stale push_post_id on
     * list refreshes (Reload / tab switch / pagination). Call before any
     * intentional soft feed reload so Open is not inflated.
     */
    private void clearStickyPushPostId() {
        if (isPositivePostId(pushUpdatedID)) {
            lastConsumedPushPostId = pushUpdatedID.trim();
        }
        TITLE_VALUE = 0;
        pushUpdatedID = "0";
        // Wire-once flag stays true so Reload cannot re-fire Open without a new intent.
        try {
            Intent intent = getIntent();
            if (intent != null) {
                intent.removeExtra("TITLE");
                intent.removeExtra("TITILE");
            }
        } catch (Exception ignored) {
        }
        try {
            SharedPrefsData.putString(
                    getApplicationContext(), Constants.PENDING_PUSH_POST, "", Constants.PREF_NAME);
        } catch (Exception ignored) {
        }
    }

    /**
     * Synchronously clear the visible FlipperAdapter (including when HomePage.adapter
     * was already nulled but FlipView still holds the old News list). Prevents first
     * News→Special paint of half cards while special_posts loads.
     */
    private void hardClearFlipFeedImmediate() {
        FlipperAdapter attached = adapter;
        try {
            if (attached == null && mFlipView != null) {
                android.widget.ListAdapter la = mFlipView.getAdapter();
                if (la instanceof FlipperAdapter) {
                    attached = (FlipperAdapter) la;
                }
            }
        } catch (Exception ignored) {
        }
        if (attached != null) {
            try {
                attached.clearAllDataImmediate();
            } catch (Exception e) {
                try {
                    attached.setData(new ArrayList<>());
                } catch (Exception ignored) {
                }
            }
        }
        if (list == null) {
            list = new ArrayList<>();
        } else {
            list.clear();
        }
        try {
            if (mFlipView != null) {
                // Detach so any residual scrap/page bitmap cannot revive News half cards.
                mFlipView.setAdapter(null);
                mFlipView.setVisibility(View.GONE);
            }
        } catch (Exception ignored) {
        }
        adapter = null;
        requestSize = 0;
    }

    /**
     * True page-0 Local district feed ({@code category_id = -1}). Drops in-flight
     * main-feed responses, clears FlipView scrap, and forces network so warm
     * main (cat=0) disk never paints or poisons local cache.
     */
    private void prepareLocalFeedPage0(boolean fromDailyUpdates) {
        feedModeEpoch++;
        clearPendingFlipRestore();
        dummyResponse = null;
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        positionx = 0;
        lastSettledFlipIndex = -1;
        requestSize = 0;
        requestPostition = 1;
        isApiRequested = false;
        isDataParsed = true;
        isFromLocalArticles = true;
        softMergeOnNextPage0 = false;
        onlineNewsAllReadSkipStreak = 0;
        no_article_message = FEED_LOADING_MESSAGE;
        hardClearFlipFeedImmediate();
        pruneImpressedNativeAdsKeepWarm();
        // Warm next feed only if pool is empty (avoid double-request on tab switch).
        try {
            if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                AdPreloader.get().prefetch(getApplicationContext());
            }
        } catch (Exception ignored) {
        }
        OpenPathCache.forceNextFeedNetwork(this);
        category_id = -1;
        localFeedFromDailyUpdates = fromDailyUpdates;
        list = new ArrayList<>();
    }

    /**
     * Clear pagination cursor + held next page so the next {@link #inlist}
     * call is a true page-0 fetch (main My Feed or Special). Does not change
     * {@link Constants#isUnreadPostsSelected}.
     */
    private void prepareFreshPage0FeedCursors() {
        // Invalidate any in-flight list response from a previous feed mode.
        feedModeEpoch++;
        clearPendingFlipRestore();
        clearStickyPushPostId();
        SHARE_ID = 0;
        SHARE_REDIRECT_ID = "0";
        DATAFROM2G = "0";
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        positionx = 0;
        lastSettledFlipIndex = -1;
        requestSize = 0;
        requestPostition = 1;
        isApiRequested = false;
        isDataParsed = true;
        isFromLocalArticles = true; // force FlipperAdapter rebuild with fresh first page
        dummyResponse = null; // drop prefetched/held next page from prior feed
        // Fresh feed mode page-0: reset soft-empty skip streak (shared News/Special/Video cap).
        onlineNewsAllReadSkipStreak = 0;
        no_article_message = FEED_LOADING_MESSAGE;
        // Sync-clear FlipView adapter data BEFORE nulling HomePage.adapter (prior bug:
        // adapter=null skipped setData clear, so FlipView kept News half posts).
        hardClearFlipFeedImmediate();
        pruneImpressedNativeAdsKeepWarm();
        // Keep shared warm pool; top up only when empty while page-0 is in flight.
        try {
            if (AdPreloader.get().readyCount() == 0 && !AdPreloader.get().isLoading()) {
                AdPreloader.get().prefetch(getApplicationContext());
            }
        } catch (Exception ignored) {
        }
        OpenPathCache.forceNextFeedNetwork(this);
        category_id = 0;
        try {
            hasSavedOnlineNewsSession = false;
            savedOnlineNewsList.clear();
        } catch (Exception ignored) {
        }
    }

    /**
     * Enter Special as a fresh list: page 0, skip=0, special_posts=true,
     * flip from index 0. Call before inlist when opening Special (tab or intent).
     * <p>
     * Mode flag is set <b>before</b> clear/request so strip/getView never see News mode
     * on the first News→Special transition frame.
     */
    private void prepareSpecialFeedFromTop() {
        showLog("prepareSpecialFeedFromTop");
        // Mode first — any concurrent getView/setData strip uses Special immediately.
        // Flag stays set until inlist's ShowNews returns, so a still-highlighted
        // News tab cannot cancel this open.
        softMergeOnNextPage0 = false;
        explicitSpecialOpen = true;
        setFeedModeFlags(true, false);
        prepareFreshPage0FeedCursors();
        // prepareFresh also bumps epoch again after mode flag (stale News responses die).
        try {
            OfflinePackPrefetcher.get().resetSession();
        } catch (Exception ignored) {
        }
    }

    /**
     * Enter Video News as a fresh list: page 0, skip=0, video_posts=true,
     * flip from index 0. Call before inlist when opening Video News tab.
     */
    private void prepareVideoFeedFromTop() {
        showLog("prepareVideoFeedFromTop");
        // Mode first — same order as Special so concurrent bind/getView never sees News.
        softMergeOnNextPage0 = false;
        setFeedModeFlags(false, true);
        prepareFreshPage0FeedCursors();
        try {
            OfflinePackPrefetcher.get().resetSession();
        } catch (Exception ignored) {
        }
    }

    /**
     * Atomically set Special/Video in-memory + committed prefs (no apply() race).
     * Video wins over Special when both requested.
     */
    private void setFeedModeFlags(boolean special, boolean video) {
        if (video) {
            special = false;
        }
        feedModeFlagsApplied = true;
        specialFeedModeActive = special;
        videoFeedModeActive = video;
        SharedPrefsData.putBoolImmediate(
                HomePage.this, Constants.isUnreadPostsSelected, special, Constants.PREF_NAME);
        SharedPrefsData.putBoolImmediate(
                HomePage.this, Constants.isVideoPostsSelected, video, Constants.PREF_NAME);
        // Drop nested Special gallery swipe latch whenever feed mode changes.
        try {
            SpecialGalleryFlipHelper.clearNestedGalleryDriving();
            suppressFooterClickFromGallerySwipe = false;
        } catch (Exception ignored) {
        }
        // Online News|Read pill only on main News — hide for Special/Video.
        try {
            if (special || video) {
                if (bookmarksModeSelected) {
                    bookmarksModeSelected = false;
                    applyHomeModeContentVisibility();
                }
            }
            refreshHomeModeToggleUi();
            refreshHomeModeCounts();
        } catch (Exception ignored) {
        }
    }

    /** Public for FlipperAdapter half-strip / getView reject. */
    public boolean isSpecialFeedModeActive() {
        return isSpecialFeedMode();
    }

    /**
     * News footer is showing the main surface (not Local, search, calendar, or
     * Daily Updates). Special mode must not stay on while this tab is highlighted.
     */
    private boolean isNewsTabShowingMainSurface() {
        if (bottomNavigationView == null) return false;
        if (bottomNavigationView.getSelectedItemId() != R.id.navigation_home) return false;
        if (isCalendarMode() || isDailyUpdatesMode()) return false;
        if (category_id == -1 || localFeedFromDailyUpdates) return false;
        if (searchFeedActive) return false;
        return true;
    }

    /**
     * News tab highlighted while Special mode is still latched: clear the latch
     * and drop the Special pagination cursor so the next list call is main page 0.
     *
     * @return true when a live Special latch was cleared
     */
    private boolean clearStuckSpecialModeOnNewsTab() {
        if (explicitSpecialOpen || !isNewsTabShowingMainSurface()) {
            return false;
        }
        if (!specialFeedModeActive) {
            return false;
        }
        showLog("News tab stuck in special mode — reset to main feed");
        setFeedModeFlags(false, false);
        last_post_id = 0;
        skip = 0;
        actual_skip = 0;
        return true;
    }

    /**
     * Match the footer highlight to the feed about to load. Runs before the
     * network call so News vs Special cannot diverge for that request.
     */
    private void syncFooterSelectionToFeedMode() {
        if (bottomNavigationView == null) return;
        // Programmatic chrome only — avoid re-entering Special/Video/Reload open paths.
        final boolean prevSuppress = suppressBottomNavCallbacks;
        suppressBottomNavCallbacks = true;
        try {
            if (isSpecialFeedMode()) {
                showLog("setSelectedItemId(R.id.navigation_catagiries)");
                bottomNavigationView.setSelectedItemId(R.id.navigation_catagiries);
            } else if (!isCalendarMode() && !isDailyUpdatesMode()) {
                // Flash and local news from Daily Updates highlight News. Snap the
                // check — do not let Material slide it across the bar.
                showLog("setSelectedItemId(R.id.navigation_home)");
                selectFooterTabWithoutMotion(R.id.navigation_home);
            }
        } catch (Exception ignored) {
        } finally {
            suppressBottomNavCallbacks = prevSuppress;
        }
    }

    private boolean isSpecialFeedMode() {
        if (videoFeedModeActive) return false;
        // Cold Special deep-link: request is special even if the footer has not moved yet.
        if (explicitSpecialOpen) return true;
        // Highlighted News tab is the main mix, even if a Special latch is still set.
        if (isNewsTabShowingMainSurface()) return false;
        if (specialFeedModeActive) return true;
        // Before the first setFeedModeFlags, honor a committed Special pref (process restart
        // mid-Special). After that, memory wins — a queued apply(true) must not stick News.
        if (feedModeFlagsApplied) return false;
        return SharedPrefsData.getBool(
                HomePage.this, Constants.isUnreadPostsSelected, Constants.PREF_NAME)
                && !SharedPrefsData.getBool(
                HomePage.this, Constants.isVideoPostsSelected, Constants.PREF_NAME);
    }

    private boolean isVideoFeedMode() {
        if (videoFeedModeActive) return true;
        // After the first explicit mode write, memory wins. A leftover
        // isVideoPostsSelected pref must not light the Daily Updates tab
        // (same menu id) while the news flipper is still the surface.
        if (feedModeFlagsApplied) return false;
        return SharedPrefsData.getBool(
                HomePage.this, Constants.isVideoPostsSelected, Constants.PREF_NAME);
    }

    /** Half My-Feed types — never shown in Special. */
    private static boolean isHalfNewsPostType(@Nullable String postType) {
        if (postType == null) return false;
        return "normal_image".equalsIgnoreCase(postType)
                || "normal_video".equalsIgnoreCase(postType);
    }

    /**
     * Full-bleed and magazine cards. These are the Special deck.
     * {@code normal_image} / {@code normal_video} are the half-news layout
     * (player or image, body, reporter row) and are not this.
     */
    private static boolean isFullOrSpecialPostType(@Nullable String postType) {
        if (postType == null) return false;
        return "full_image".equalsIgnoreCase(postType)
                || "full_video".equalsIgnoreCase(postType)
                || "image_gallery".equalsIgnoreCase(postType)
                || "magazine".equalsIgnoreCase(postType)
                || "magazines".equalsIgnoreCase(postType);
    }

    /** Full / magazine / gallery cards only. Ads and ratings are seats, not a new Special post. */
    private static int countFullSpecialPosts(
            @Nullable java.util.List<ModelClass.Datum> items) {
        if (items == null || items.isEmpty()) return 0;
        int n = 0;
        for (int i = 0; i < items.size(); i++) {
            ModelClass.Datum d = items.get(i);
            if (d != null && isFullOrSpecialPostType(d.getPostType())
                    && d.getPostId() != null && d.getPostId() > 0) {
                n++;
            }
        }
        return n;
    }

    private boolean listContainsHalfNews(
            @Nullable java.util.List<ModelClass.Datum> items) {
        if (items == null) return false;
        for (int i = 0; i < items.size(); i++) {
            ModelClass.Datum d = items.get(i);
            if (d != null && isHalfNewsPostType(d.getPostType())) {
                return true;
            }
        }
        return false;
    }

    /**
     * Client safety filter for Special: strip {@code normal_image} / {@code normal_video}
     * even if the server errs or a main-list response races in. Mutates list in place.
     */
    private void filterListStripHalfPosts(@Nullable java.util.List<ModelClass.Datum> items) {
        // News tab keeps half news even if a Special latch was still set.
        if (isNewsTabShowingMainSurface() && !explicitSpecialOpen) return;
        if (items == null || items.isEmpty()) return;
        for (int i = items.size() - 1; i >= 0; i--) {
            ModelClass.Datum d = items.get(i);
            if (d == null || isHalfNewsPostType(d.getPostType())) {
                items.remove(i);
            }
        }
    }

    /**
     * Offline paint gate: drop items without a successfully cached hero image.
     * Keeps Offline News list free of ANYNEWS logo placeholders.
     */
    private void filterListToOfflineMediaReady(
            @Nullable java.util.List<ModelClass.Datum> items) {
        if (items == null || items.isEmpty()) return;
        for (int i = items.size() - 1; i >= 0; i--) {
            ModelClass.Datum d = items.get(i);
            if (d == null || !OfflineFeedStore.isServingReady(this, d)) {
                items.remove(i);
            }
        }
    }

    /** Half ({@code normal_video}) + full ({@code full_video}) only. */
    private static boolean isVideoNewsPostType(@Nullable String postType) {
        if (postType == null) return false;
        return "normal_video".equalsIgnoreCase(postType)
                || "full_video".equalsIgnoreCase(postType);
    }

    /**
     * Kept in Video News when mixed payloads arrive: video primary content plus the
     * same ad/ratings/vast slots News and Special streams show (do not strip ads).
     */
    private static boolean isVideoFeedAllowedPostType(@Nullable String postType) {
        if (isVideoNewsPostType(postType)) return true;
        if (postType == null) return false;
        return "ad".equalsIgnoreCase(postType)
                || "web_ads".equalsIgnoreCase(postType)
                || "ratings".equalsIgnoreCase(postType)
                || "google_vasttag".equalsIgnoreCase(postType)
                || "share_app".equalsIgnoreCase(postType);
    }

    /**
     * Client safety filter when server ignores {@code video_posts} or returns
     * greetings/mixed article types. Keeps half/full video and ad slots; strips
     * everything else. Mutates the list in place.
     */
    private void filterListToVideoPostsOnly(@Nullable java.util.List<ModelClass.Datum> items) {
        // Breaking / Flash News tab (former Video slot) shows pushed article types from
        // push history (main + district local) — do not strip to video-only.
        if (items == null || items.isEmpty()) return;
        if (isVideoFeedMode()) return;
        for (int i = items.size() - 1; i >= 0; i--) {
            ModelClass.Datum d = items.get(i);
            if (d == null || !isVideoFeedAllowedPostType(d.getPostType())) {
                items.remove(i);
            }
        }
    }

    /**
     * Build a rebalance-ready ad shell from feed-level {@code ads_data} when the
     * page response had no {@code post_type=ad} row (short video pages).
     */
    @Nullable
    private ModelClass.Datum adShellFromAdsData(@Nullable EncreptionRequest enc) {
        if (enc == null || !enc.isShow_ads()) return null;
        java.util.List<com.anyNews.anynews.Pojo.AdsPojo> positions = enc.getAd_positions();
        if (positions == null || positions.isEmpty()) return null;
        com.anyNews.anynews.Pojo.AdsPojo first = positions.get(0);
        if (first == null || first.getAd_code() == null || first.getAd_code().isEmpty()) {
            return null;
        }
        try {
            ModelClass.Datum shell = new ModelClass.Datum();
            shell.setPostType("ad");
            shell.setAd_type(first.getAd_type() != null ? first.getAd_type() : "google");
            shell.setAd_code(first.getAd_code());
            shell.setNext_req_ad_code(first.getAd_code());
            String code = first.getAd_code();
            shell.setAds_from(code != null && code.startsWith("/") ? "admanager" : "admob");
            shell.setAd_screen_type("native");
            shell.setAd_view_type("regular");
            shell.setAd_audio_mute(true);
            shell.setAd_check(true);
            if (first.getAd_req_position() != null) {
                shell.setAd_req_position(first.getAd_req_position());
            }
            // Stable synthetic id so Flipper/ad loaders treat it as an ad shell.
            shell.setPostId(901012L);
            shell.setSubPostId(1L);
            return shell;
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Video News: remember ad shell + re-place ads every
     * {@link ReadArticleStore#getAdEveryNReal()} real video cards (same as main News).
     * Uses feed ad rows and/or {@code ads_data} when the page had no ad slot yet.
     */
    private void rebalanceVideoFeedAdsIfNeeded(
            @Nullable java.util.List<ModelClass.Datum> items,
            @Nullable EncreptionRequest enc) {
        if (items == null || items.isEmpty()) return;
        if (!isVideoFeedMode() || !isDeviceOnline() || offlineChromeMode) return;
        // Search mode never seats Flash ads between keyword hits.
        if (isSearchFeedActive() || searchFeedActive) return;
        try {
            rememberFeedAdTemplate(items);
            if (onlineNewsAdTemplate == null && enc != null) {
                ModelClass.Datum fromData = adShellFromAdsData(enc);
                if (fromData != null) {
                    onlineNewsAdTemplate = fromData;
                }
            }
            if (onlineNewsAdTemplate == null) return;
            boolean changed =
                    ReadArticleStore.rebalanceFeedSlots(
                            HomePage.this, items, onlineNewsAdTemplate);
            boolean ratingsChanged =
                    ReadArticleStore.ensureRatingsSlot(HomePage.this, items);
            if (changed || ratingsChanged) {
                showLog("video feed: rebalanced ads/ratings listSize=" + items.size()
                        + " reals=" + ReadArticleStore.countRealArticles(items));
                preloadNativeAdsForFeedSlots(items);
            }
        } catch (Exception ignored) {
        }
    }

    /**
     * Quiet page-0 when IST greeting day-part changed while the process stayed
     * alive (tester: morning image still showing in the afternoon on one phone).
     * Keeps flip seat; does not switch tabs or show Reload chrome.
     */
    private void maybeRefreshFeedForGreetingSlotChange(String reason) {
        if (!homeActivityResumed || isFinishing()) {
            return;
        }
        if (!isDeviceOnline()) {
            return;
        }
        // Main News only — Special/Video/Local/search/bookmarks have their own lists.
        if (isSpecialFeedMode() || isVideoFeedMode() || isCalendarMode()
                || isDailyUpdatesMode() || bookmarksModeSelected || searchFeedActive) {
            return;
        }
        if (category_id == -1 || localFeedFromDailyUpdates) {
            return;
        }
        if (isOnlineReadFlipMode()) {
            return;
        }
        // A push/share seat is a one-shot page 0. A slot refresh would replace
        // it with the plain first article.
        if (isStickyFeedOpen()) {
            return;
        }
        final int slot = GreetingDayPartHelper.currentSlot();
        if (slot == GreetingDayPartHelper.SLOT_NONE) {
            return;
        }
        final String nowKey = GreetingDayPartHelper.currentSlotKey();
        if (appliedGreetingSlotKey == null) {
            // First observation this process — wait until a page-0 lands, then compare.
            appliedGreetingSlotKey = nowKey;
            return;
        }
        if (nowKey.equals(appliedGreetingSlotKey)) {
            return;
        }
        final long now = System.currentTimeMillis();
        if (now - lastGreetingSlotRefreshAtMs < GREETING_SLOT_REFRESH_MIN_INTERVAL_MS) {
            return;
        }
        if (isApiRequested) {
            return;
        }
        try {
            if (mFlipView != null && mFlipView.isUserDrivingFlip()) {
                return;
            }
        } catch (Exception ignored) {
        }
        lastGreetingSlotRefreshAtMs = now;
        showLog("greeting slot refresh reason=" + reason
                + " was=" + appliedGreetingSlotKey
                + " now=" + nowKey
                + " (" + GreetingDayPartHelper.slotLabel(slot) + ")");
        try {
            int flipIndex = resolveCurrentFlipIndexForSave();
            long postId = resolvePostIdForFlipIndex(flipIndex);
            pendingRestoreFlipIndex = flipIndex;
            pendingRestorePostId = postId;
            pendingFlipRestore = flipIndex > 0 || postId > 0;
        } catch (Exception ignored) {
        }
        try {
            OpenPathCache.forceNextFeedNetwork(this);
            last_post_id = 0;
            skip = 0;
            actual_skip = 0;
            isApiRequested = true;
            appliedGreetingSlotKey = nowKey;
            ShowNews_Data_Values(category_id, 0);
        } catch (Exception e) {
            isApiRequested = false;
            showLog("greeting slot refresh failed: " + e.getMessage());
        }
    }

    private void startGreetingSlotPoll() {
        try {
            greetingSlotHandler.removeCallbacks(greetingSlotPollRunnable);
            greetingSlotHandler.postDelayed(greetingSlotPollRunnable, GREETING_SLOT_POLL_MS);
        } catch (Exception ignored) {
        }
    }

    private void stopGreetingSlotPoll() {
        try {
            greetingSlotHandler.removeCallbacks(greetingSlotPollRunnable);
        } catch (Exception ignored) {
        }
    }

    /**
     * Soft feed restart matching cold-start intent: latest page 0, no push
     * sticky, no flip-restore jump to a previously-viewed article.
     * Leaves Special ({@code isUnreadPostsSelected=false}) and reloads My Feed.
     * Used by bottom-nav Reload (select + reselect).
     * <p>
     * Offline: re-paint OfflineFeedStore / OpenPathCache without blanking the
     * adapter first (same reliable path as cold offline open after rebind).
     */
    private void performFeedReload() {
        showLog("performFeedReload initialCall=" + initialCall);
        skipFeedNetworkForPositionKeep = false;
        try {
            FeedPositionKeepConfig.clear(this);
        } catch (Exception ignored) {
        }
        clearSearchFeedMode();
        // Drop mid-watch video position before the feed rebuilds. Same article often
        // comes back first; without this the shared Exo player reattaches and resumes.
        // Does not touch flip jump-to-first (prepareFreshPage0FeedCursors below).
        try {
            FlipperAdapter.resetPlaybackOnFeedReload();
        } catch (Exception ignored) {
        }
        try {
            if (adapter != null) {
                adapter.clearUserPausedVideoAutoplay();
            }
        } catch (Exception ignored) {
        }
        try {
            if (player != null) {
                player.setPlayWhenReady(false);
                player.pause();
                player.seekTo(0);
                player.stop();
            }
        } catch (Exception ignored) {
        }
        // Leaving any Mana Zilla local path when Reload / News main is requested.
        // Footer refresh = cold-start Main label (district redirection pill).
        localFeedFromDailyUpdates = false;
        hideLocalFeedChrome();
        hideHomeCalendarMode();
        hideHomeDailyUpdatesMode();
        writeButtonClick("User", type_firebase_button, current_time_firebase,
                draft_id_firebase, device_id_firebase, button_name_home);
        showLog("isUnreadPostsSelected set to false #5");
        setFeedModeFlags(false, false);
        try {
            OfflinePackPrefetcher.get().resetSession();
        } catch (Exception ignored) {
        }
        // Footer Reload always returns to News stream (not bookmarks list).
        try {
            selectHomeModeNews(true);
        } catch (Exception ignored) {
        }
        // My Feed chrome — same as tapping My Feed
        try {
            comment_page.setVisibility(View.GONE);
            un_selected_local.setVisibility(View.VISIBLE);
            un_selected_my_feed.setVisibility(View.GONE);
            selected_my_feed.setVisibility(View.VISIBLE);
            selected_local.setVisibility(View.GONE);
        } catch (Exception ignored) {
        }
        showLog("Check Point #3 : HomePage performFeedReload soft");
        if (!isDeviceOnline()) {
            // Offline Reload: keep prior list until disk paint rebinds adapter with setData.
            // Do NOT clear list/adapter first (that left a permanent white FlipView before).
            prepareOfflineMainReloadCursors();
            hideHomeFeedLoadingReveal(true);
            if (!paintOfflineFeed(false, true)) {
                // No cache — clear and show empty (not pure white FlipView).
                try {
                    list = new ArrayList<>();
                    adapter = null;
                    showMainOfflineEmptyState();
                } catch (Exception ignored) {
                }
            }
            return;
        }
        // Hold the middle column across the empty-list gap. Hiding it rebuilds
        // the footer and a fast second tap is delivered to Profile.
        footerCenterSlotFrozenForReload = true;
        // Online: full page-0 reset then network inlist (same as cold soft restart).
        prepareFreshPage0FeedCursors();
        try {
            showHomeFeedLoadingReveal();
            layout_with_data.setVisibility(View.GONE);
            comment_page.setVisibility(View.GONE);
        } catch (Exception ignored) {
        }
        inlist(0);
    }

    /**
     * Soft Special-tab open: always {@code special_posts=true} page 0 from the
     * top. Does not keep main-feed skip/cursor, held page, or flip-restore.
     * Does not recreate the activity (avoids inheriting mid-scroll pagination).
     * Offline: online-only empty message — never paints special/main offline cache.
     */
    private void performSpecialFeedOpen() {
        showLog("performSpecialFeedOpen");
        try {
            ArticleTtsHelper.stopAll();
        } catch (Exception ignored) {
        }
        clearSearchFeedMode();
        localFeedFromDailyUpdates = false;
        hideLocalFeedChrome();
        hideHomeCalendarMode();
        hideHomeDailyUpdatesMode();
        clearSpecialTabBlink();
        showLog("Check Point #5 : HomePage performSpecialFeedOpen soft");
        // Never soft-merge main Offline/reconnect list into Special.
        softMergeOnNextPage0 = false;
        // Mode flag FIRST (before any clear/paint/network): first News→Special transition.
        setFeedModeFlags(true, false);
        // Special is feed-mode (not bookmarks list) — hide panel only, do not paint main offline.
        try {
            bookmarksModeSelected = false;
            applyHomeModeContentVisibility();
            refreshHomeModeToggleUi();
        } catch (Exception ignored) {
        }
        if (!isDeviceOnline()) {
            // Online-only: Special flag already set; hard-clear FlipView + empty state.
            OpenPathCache.clearForceFeedNetwork();
            try {
                clearPendingFlipRestore();
                clearStickyPushPostId();
                SHARE_ID = 0;
                SHARE_REDIRECT_ID = "0";
                DATAFROM2G = "0";
                last_post_id = 0;
                skip = 0;
                actual_skip = 0;
                positionx = 0;
                lastSettledFlipIndex = -1;
                requestPostition = 1;
                isApiRequested = false;
                isDataParsed = true;
                isFromLocalArticles = true;
                dummyResponse = null;
                category_id = 0;
                hardClearFlipFeedImmediate();
            } catch (Exception ignored) {
            }
            hideHomeFeedLoadingReveal(true);
            showSpecialOfflineEmptyState();
            return;
        }
        prepareSpecialFeedFromTop();
        try {
            showHomeFeedLoadingReveal();
            if (layout_with_data != null) {
                layout_with_data.setVisibility(View.GONE);
            }
            if (comment_page != null) {
                comment_page.setVisibility(View.GONE);
            }
            // Belt-and-suspenders: ensure FlipView is empty/detached even if a path
            // reattached the main adapter between prepare and inlist.
            hardClearFlipFeedImmediate();
            if (txtNoData != null) {
                txtNoData.setVisibility(View.GONE);
            }
        } catch (Exception ignored) {
        }
        inlist(0);
    }

