    @Override
    public boolean dispatchTouchEvent(MotionEvent ev) {
        if (ev.getActionMasked() == MotionEvent.ACTION_DOWN) {
            footerGestureDownItemId = 0;
            if (bottomNavigationView != null
                    && isRawTouchInsideView(bottomNavigationView, ev.getRawX(), ev.getRawY())) {
                footerGestureDownItemId = footerItemIdAt(ev.getRawX(), ev.getRawY());
            }
        }
        // Special / nested magazine galleries: horizontal page-turn must not land on the
        // footer as a Profile / tab click, and must not race system-back edge.
        boolean guardGallerySwipe = (isSpecialFeedMode()
                || SpecialGalleryFlipHelper.isNestedGalleryDriving())
                && bottomNavigationView != null && mFlipView != null
                && mFlipView.getVisibility() == View.VISIBLE;
        if (guardGallerySwipe) {
            if (galleryNavTouchSlop < 0) {
                galleryNavTouchSlop = ViewConfiguration.get(this).getScaledTouchSlop();
            }
            final int action = ev.getActionMasked();
            switch (action) {
                case MotionEvent.ACTION_DOWN:
                    galleryNavGuardDownX = ev.getRawX();
                    galleryNavGuardDownY = ev.getRawY();
                    suppressFooterClickFromGallerySwipe = false;
                    break;
                case MotionEvent.ACTION_MOVE: {
                    float dx = Math.abs(ev.getRawX() - galleryNavGuardDownX);
                    float dy = Math.abs(ev.getRawY() - galleryNavGuardDownY);
                    if (!suppressFooterClickFromGallerySwipe
                            && dx > galleryNavTouchSlop
                            && dx > dy
                            && isRawTouchInsideView(mFlipView, galleryNavGuardDownX,
                            galleryNavGuardDownY)
                            && !isRawTouchInsideView(bottomNavigationView,
                            galleryNavGuardDownX, galleryNavGuardDownY)) {
                        suppressFooterClickFromGallerySwipe = true;
                    }
                    break;
                }
                case MotionEvent.ACTION_UP:
                case MotionEvent.ACTION_CANCEL:
                    if (suppressFooterClickFromGallerySwipe
                            || SpecialGalleryFlipHelper.isNestedGalleryDriving()) {
                        if (isRawTouchInsideView(bottomNavigationView, ev.getRawX(),
                                ev.getRawY())) {
                            suppressFooterClickFromGallerySwipe = false;
                            return true; // swallow footer click
                        }
                    }
                    suppressFooterClickFromGallerySwipe = false;
                    break;
                default:
                    break;
            }
        }
        try {
            return super.dispatchTouchEvent(ev);
        } catch (Exception e) {
            // Nested FlipView / ViewPager NPEs during magazine swipe must not kill process.
            android.util.Log.e("MagazineCrash", "dispatchTouchEvent: " + e.getMessage());
            SpecialGalleryFlipHelper.clearNestedGalleryDriving();
            return true;
        }
    }

    /** Menu id of the visible footer item that contains this screen point, or 0. */
    private int footerItemIdAt(float rawX, float rawY) {
        try {
            if (bottomNavigationView == null) {
                return 0;
            }
            View menuChild = bottomNavigationView.getChildAt(0);
            if (!(menuChild instanceof ViewGroup)) {
                return 0;
            }
            ViewGroup menu = (ViewGroup) menuChild;
            for (int i = 0; i < menu.getChildCount(); i++) {
                View child = menu.getChildAt(i);
                if (!(child instanceof BottomNavigationItemView)
                        || child.getVisibility() != View.VISIBLE
                        || !isRawTouchInsideView(child, rawX, rawY)) {
                    continue;
                }
                MenuItem data = ((BottomNavigationItemView) child).getItemData();
                return data != null ? data.getItemId() : 0;
            }
        } catch (Exception ignored) {
        }
        return 0;
    }

    /**
     * Material's item pool is last-in. A bar rebuild between ACTION_DOWN and
     * the click rebinds that view to another menu id. The listener then sees
     * Daily Updates for a finger that went down on Special (the same class of
     * miss that used to deliver Reload as Profile). Ignore the rebound id.
     * A reselect of the tab already under the finger must not navigate away.
     *
     * @return true when the delivered item must not run
     */
    private boolean ignoreReboundFooterNavigation(@NonNull MenuItem delivered) {
        int down = footerGestureDownItemId;
        if (down == 0 || delivered.getItemId() == down) {
            return false;
        }
        showLog("footer nav ignored — rebound down=" + down
                + " delivered=" + delivered.getItemId());
        if (bottomNavigationView != null
                && bottomNavigationView.getSelectedItemId() != down) {
            if (down == R.id.navigation_home
                    && ProfileHubConfigHelper.isFooterShowReload(this)) {
                performFeedReload();
            } else if (down == R.id.navigation_catagiries
                    && ProfileHubConfigHelper.isFooterShowSpecial(this)
                    && isDeviceOnline()) {
                performSpecialFeedOpen();
            }
        } else if (down == R.id.navigation_catagiries) {
            selectFooterTabWithoutMotion(R.id.navigation_catagiries);
        }
        return true;
    }

    /**
     * {@code buildMenuView} can check Daily Updates because that view was the
     * last Special view released into the pool. Put the check back. Does not
     * open Daily Updates and does not run while that hub is actually showing.
     */
    private void keepFooterCheckOffRecycledDailyUpdates() {
        if (bottomNavigationView == null || isDailyUpdatesMode() || isCalendarMode()) {
            return;
        }
        if (bottomNavigationView.getSelectedItemId() != R.id.navigation_status) {
            return;
        }
        int want = (footerGestureDownItemId == R.id.navigation_catagiries || isSpecialFeedMode())
                ? R.id.navigation_catagiries
                : R.id.navigation_home;
        selectFooterTabWithoutMotion(want);
    }

    private static boolean isRawTouchInsideView(@Nullable View v, float rawX, float rawY) {
        if (v == null || v.getVisibility() != View.VISIBLE) {
            return false;
        }
        int[] loc = new int[2];
        try {
            v.getLocationOnScreen(loc);
        } catch (Exception e) {
            return false;
        }
        return rawX >= loc[0] && rawX <= loc[0] + v.getWidth()
                && rawY >= loc[1] && rawY <= loc[1] + v.getHeight();
    }

