    /**
     * Soft-request LOCATION once on first Home so draft GPS works for guests/readers
     * who never open create-post. Does not re-prompt after deny / prior ask.
     */
    private void maybeSoftRequestDraftGpsPermission() {
        if (draftGpsPermissionLauncher == null) return;
        if (!DeviceLocationHelper.shouldSoftRequestOnce(this)) return;
        // Mark before launch so rotation / multi-resume does not stack dialogs.
        DeviceLocationHelper.markSoftAsked(this);
        // Slight delay so Home UI settles before the system dialog.
        getWindow().getDecorView().postDelayed(() -> {
            if (isFinishing() || isDestroyed()) return;
            if (DeviceLocationHelper.hasLocationPermission(this)) {
                try {
                    SessionAnalyticsTracker.get().forceRefreshDeviceLocation(this);
                } catch (Exception ignored) {
                }
                return;
            }
            try {
                draftGpsPermissionLauncher.launch(new String[]{
                        Manifest.permission.ACCESS_FINE_LOCATION,
                        Manifest.permission.ACCESS_COARSE_LOCATION
                });
            } catch (Exception e) {
                showLog("draft GPS soft request failed: " + e.getMessage());
            }
        }, 1600L);
    }

    @Override
    public void onPause() {
        homeActivityResumed = false;
        backgroundRefreshHandler.removeCallbacks(clearUnconfirmedShareSeat);
        // System toasts outlive the activity and sit on top of the next app.
        dismissOfflineSavedNewsToast();
        stopGreetingSlotPoll();
        stopReadBadgePoll();
        try {
            ViewsBatchTracker.get().setHomeFlushActive(false);
            MediaAccessReporter.get().setHomeFlushActive(false);
            com.anyNews.anynews.rewards.RewardsEngagementBatcher.get()
                    .setHomeFlushActive(false);
        } catch (Exception ignored) {
        }
        try {
            OfflinePackPrefetcher.get().onHostPaused();
        } catch (Exception ignored) {
        }
        try {
            PostDwellTracker.get().onPaused(this);
        } catch (Exception ignored) {
        }
        // Leave Home → one delivery if the views queue changed. Empty = no HTTP.
        // ProcessLifecycle ON_STOP still covers true background (also empty-gated).
        try {
            if (ViewsBatchTracker.get().hasPending()) {
                ViewsBatchTracker.get().flush(getApplicationContext(), false);
            }
            MediaAccessReporter.get().flush(getApplicationContext(), false);
        } catch (Exception ignored) {
        }
        // new flip — collapse reporter create-menu so pause never leaves a stuck X.
        try {
            closeCenterPlusMenu(false);
        } catch (Exception ignored) {
        }
        pauseVideo();
        try {
            // Leaving Home (incl. recents) — stop read-aloud so voice does not continue.
            ArticleTtsHelper.stopAll();
        } catch (Exception ignored) {
        }
        super.onPause();
        try {
            if (FlipperAdapter.exoPlayer != null) {
                FlipperAdapter.exoPlayer.setPlayWhenReady(false);
                FlipperAdapter.exoPlayer.pause();
                FlipperAdapter.exoPlayer.stop();
                FlipperAdapter.exoPlayer.release();
                FlipperAdapter.exoPlayer = null;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        try {
            if (adapter != null && adapter.nativeAd != null) {
                showLog("native Ad");
                NativeAd activeNativeAd = adapter.nativeAd;
                if (activeNativeAd.getMediaContent() != null
                        && activeNativeAd.getMediaContent().getVideoController() != null) {
                    showLog("native Ad getMediaContent pause");
                    activeNativeAd.getMediaContent().getVideoController().mute(true);
                    activeNativeAd.getMediaContent().getVideoController().pause();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        if (player != null) {
            try {
                player.setPlayWhenReady(false);
                if (positionx > 0) {
                   /* if (FlipperAdapter.youTubePlayerViewHalf != null) {
                        FlipperAdapter.youTubePlayerViewHalf.pause();
                        AudioManager audio = (AudioManager) getApplicationContext().getSystemService(Context.AUDIO_SERVICE);
                        int maxVolume = audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);
                        int seventyVolume = (int) (maxVolume * percent);
                        audio.setStreamVolume(AudioManager.STREAM_MUSIC, seventyVolume, 0);
                    }*/
                    if (youTubePlayerView1 != null) {
                        youTubePlayerView1.release();
                        AudioManager audio = (AudioManager) getApplicationContext().getSystemService(Context.AUDIO_SERVICE);
                        int maxVolume = audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);
                        int seventyVolume = (int) (maxVolume * percent);
                        audio.setStreamVolume(AudioManager.STREAM_MUSIC, seventyVolume, 0);
                    }

                }

            } catch (NullPointerException e) {

            }

        }

    }

    @Override
    protected void onStop() {
        try {
            ArticleTtsHelper.stopAll();
        } catch (Exception ignored) {
        }
        super.onStop();
        // Real background (Home / other app) — clear Allow-settled so next open can ask.
        // Leaving for POST_NOTIFICATIONS / app notification Settings keeps settled so
        // return does not immediately re-show the soft dialog.
        if (!expectNotifSettingsOrPermReturn) {
            notificationSoftAllowSettledThisOpen = false;
        }
    }

    private Context context;
    //botoom menu
    private final BottomNavigationView.OnNavigationItemReselectedListener mOnNavigationItemReselectedListener
            = new BottomNavigationView.OnNavigationItemReselectedListener() {
        @Override
        public void onNavigationItemReselected(@NonNull MenuItem item) {
            if (suppressBottomNavCallbacks) {
                return;
            }
            if (ignoreReboundFooterNavigation(item)) {
                return;
            }
            // Calendar stays selected like Special. Reselecting Reload / Special
            // while create-menu is open must still dismiss X + overlay.
            if (item.getItemId() != R.id.navigation_stricker) {
                closeCenterPlusMenu(true);
            }
            if (item.getItemId() == R.id.navigation_home) {
                // User tapped already-selected News — same as cold soft restart.
                if (initialCall) {
                    performFeedReload();
                }
            } else if (item.getItemId() == R.id.navigation_catagiries) {
                // Re-tap Special while already on Special: always restart from article 0.
                performSpecialFeedOpen();
            } else if (item.getItemId() == R.id.navigation_status) {
                performDailyUpdatesOpen();
                if (!isDailyUpdatesMode()) {
                    releaseDailyUpdatesCheckLeftByQuietCard();
                } else {
                    keepDailyUpdatesCovered();
                }
            } else if (item.getItemId() == R.id.navigation_stricker) {
                if (ProfileHubConfigHelper.isFooterShowCalendar(HomePage.this)
                        && isDeviceOnline()) {
                    performCalendarOpen(false);
                }
            }
        }
    };
    private BottomNavigationView.OnNavigationItemSelectedListener mOnNavigationItemSelectedListener
            = new BottomNavigationView.OnNavigationItemSelectedListener() {

        @Override
        public boolean onNavigationItemSelected(@NonNull MenuItem item) {
            if (suppressBottomNavCallbacks) {
                return true;
            }
            if (ignoreReboundFooterNavigation(item)) {
                return false;
            }
            if (suppressFooterClickFromGallerySwipe
                    || SpecialGalleryFlipHelper.isNestedGalleryDriving()) {
                showLog("bottom nav ignored — gallery swipe item=" + item.getItemId());
                return false;
            }
            Intent intent;
            switch (item.getItemId()) {
                // ... implement code here
                case R.id.navigation_home:
                    if (!ProfileHubConfigHelper.isFooterShowReload(HomePage.this)) {
                        return false;
                    }
                    closeCenterPlusMenu(true);
                    showLog("initialCall:::" + initialCall);
                    try {
                        if (languageModelResponse != null && languageModelResponse.getData() != null) {
                            showLog("RELOAD:::" + languageModelResponse.getData().getReload());
                        }
                    } catch (Exception ignored) {
                    }
                    showLog("RELOAD getTitle:::" + item.getTitle().toString());
                    showLog(" layout_with_out_data:::" + layout_with_out_data.getVisibility());
                    showLog(" layout_with_data:::" + layout_with_data.getVisibility());
                    showLog(" txtNoData:::" + txtNoData.getVisibility());
                    if (initialCall || isCalendarMode() || isDailyUpdatesMode()) {
                        // Soft restart: clear push sticky + flip restore + fetch skip=0.
                        // Leaves Special/Calendar/Daily Updates if open and reloads My Feed page 0.
                        // Avoid activity CLEAR_TASK recreate (re-applied flip-restore prefs
                        // and could re-land with stale state).
                        performFeedReload();
                    }
                    return true;
                case R.id.navigation_catagiries:
                    if (!ProfileHubConfigHelper.isFooterShowSpecial(HomePage.this)
                            || !isDeviceOnline()) {
                        return false;
                    }
                    closeCenterPlusMenu(true);
                    // Soft Special open at page 0 — do not recreate activity or keep
                    // main-feed skip/actual_skip/last_post_id / held next page.
                    performSpecialFeedOpen();
                    return true;
                case R.id.navigation_status:
                    // Daily Updates (slot 2). Flash News via page chip.
                    if (!ProfileHubConfigHelper.isFooterShowVideos(HomePage.this)
                            || !isDeviceOnline()) {
                        return false;
                    }
                    closeCenterPlusMenu(true);
                    performDailyUpdatesOpen();
                    if (!isDailyUpdatesMode()) {
                        return false;
                    }
                    keepDailyUpdatesCovered();
                    return true;
                case R.id.navigation_stricker:
                    // Middle column is Share, reporter +, or icon-only WhatsApp.
                    if (isFooterCalendarTabWanted()) {
                        closeCenterPlusMenu(true);
                        performCalendarOpen(false);
                        return true;
                    }
                    if (isMagazineShareFooterShowing()) {
                        return false;
                    }
                    if (isFooterWhatsappShowing()) {
                        onFooterCenterWhatsappClicked();
                        return false;
                    }
                    if (!ProfileHubConfigHelper.isFooterShowCalendar(HomePage.this)
                            || !isDeviceOnline()) {
                        return false;
                    }
                    closeCenterPlusMenu(true);
                    performCalendarOpen(false);
                    return true;
                case R.id.navigation_profile:
                    // Profile is online-only (hidden offline with Special / Video / Calendar).
                    if (!ProfileHubConfigHelper.isFooterShowProfile(HomePage.this)
                            || !isDeviceOnline()) {
                        return false;
                    }
                    if (suppressFooterClickFromGallerySwipe
                            || SpecialGalleryFlipHelper.isNestedGalleryDriving()) {
                        showLog("navigation_profile ignored — gallery swipe");
                        return false;
                    }
                    // Reload's view is the first one released into Material's item pool.
                    // A bar rebuild rebinds that same view as Profile before ACTION_UP,
                    // so a fast Reload tap arrives here. Honor the finger-down item.
                    if (footerGestureDownItemId != 0
                            && footerGestureDownItemId != R.id.navigation_profile) {
                        showLog("navigation_profile ignored — down item="
                                + footerGestureDownItemId);
                        if (footerGestureDownItemId == R.id.navigation_home
                                && ProfileHubConfigHelper.isFooterShowReload(HomePage.this)) {
                            performFeedReload();
                        }
                        return false;
                    }
                    // Keep the selected tab painted under Profile. Tearing down Calendar,
                    // selecting News, or clearing Special/Video mode here exposes News
                    // during the Activity hand-off (especially warm REORDER_TO_FRONT).
                    if (isCenterPlusMenuOpen()) {
                        closeCenterPlusMenu(false);
                    }
                    // Start Profile first (instant); analytics after so it never delays open.
                    openProfileInstant();
                    try {
                        writeButtonClick("User", type_firebase_button, current_time_firebase,
                                draft_id_firebase, device_id_firebase, button_name_profile);
                    } catch (Exception ignored) {
                    }
                    return false;
                default:
                    return false;
            }
        }

    };

