    /**
     * Permanent Special glyph: Material menu icon is ALWAYS {@link View#VISIBLE}
     * with {@code ic_footer_special} when the Special slot is allowed (online + admin).
     * Offline / admin-off: never force-show Special (that reintroduced the offline
     * News+Special leak after rebalance).
     * Overlay is optional blink polish only.
     */
    private void setupSpecialTabBulb() {
        if (bottomNavigationView == null) {
            return;
        }
        if (!isFooterSpecialTabAllowed()) {
            try {
                stopSpecialTabBlinkAnimation();
                if (specialTabBulbOverlay != null) {
                    specialTabBulbOverlay.setVisibility(View.GONE);
                }
                MenuItem special = bottomNavigationView.getMenu().findItem(R.id.navigation_catagiries);
                if (special != null) {
                    special.setVisible(false);
                    special.setEnabled(false);
                }
                forceFooterItemViewsMatchMenuVisibility();
            } catch (Exception ignored) {
            }
            return;
        }
        ensureSpecialMenuIconAlwaysVisible();
        ensureSpecialTabBulbOverlay();
        updateSpecialTabBlinkIndicator();
        // Post one more pass after layout weights settle (rebalance, first measure).
        bottomNavigationView.post(() -> {
            if (!isFooterSpecialTabAllowed()) {
                return;
            }
            ensureSpecialMenuIconAlwaysVisible();
            ensureSpecialTabBulbOverlay();
            if (!specialTabViewedThisSession && !isVisibleFooterQuietCard()) {
                startSpecialTabBlinkAnimation();
            } else if (isVisibleFooterQuietCard()) {
                hideSpecialBlinkForQuietCard();
            }
        });
    }

    /**
     * Re-bind footer menu ImageViews to {@link ColorStateList} so checked items
     * (Special / Profile) show brand orange on icon+label; unchecked stays gray.
     * Must run after programmatic {@code setImageResource} which can drop tint.
     */
    private void applyFooterTabIconTints() {
        if (bottomNavigationView == null) {
            return;
        }
        ColorStateList tint = bottomNavigationView.getItemIconTintList();
        if (tint == null) {
            tint = FooterStyleHelper.resolveIconTextTint(this);
        }
        if (tint == null) {
            tint = ContextCompat.getColorStateList(this, R.color.selector_item_primary_color);
        }
        if (tint == null) {
            return;
        }
        // Keep BNV + any admin colors in sync.
        bottomNavigationView.setItemIconTintList(tint);
        BottomNavigationMenuView menuView =
                (BottomNavigationMenuView) bottomNavigationView.getChildAt(0);
        if (menuView == null) {
            return;
        }
        for (int i = 0; i < menuView.getChildCount(); i++) {
            View item = menuView.getChildAt(i);
            if (!(item instanceof BottomNavigationItemView)) {
                continue;
            }
            View iconView = item.findViewById(
                    com.google.android.material.R.id.navigation_bar_item_icon_view);
            if (iconView instanceof ImageView) {
                ImageView iv = (ImageView) iconView;
                iv.clearColorFilter();
                androidx.core.widget.ImageViewCompat.setImageTintList(iv, tint);
            }
        }
        // Blink overlay is not Material-managed — tint it orange only while pending.
        if (specialTabBulbOverlay != null && specialTabBulbOverlay.getVisibility() == View.VISIBLE
                && !specialTabViewedThisSession) {
            specialTabBulbOverlay.setColorFilter(
                    ContextCompat.getColor(this, R.color.brand_orange), PorterDuff.Mode.SRC_ATOP);
        }
    }

    /**
     * When Special is allowed: keep a non-null icon and its ImageView VISIBLE.
     * When offline / admin-off: force Special hidden — never setVisible(true).
     */
    private void ensureSpecialMenuIconAlwaysVisible() {
        if (bottomNavigationView == null) {
            return;
        }
        final boolean specialAllowed = isFooterSpecialTabAllowed();
        try {
            MenuItem special = bottomNavigationView.getMenu().findItem(R.id.navigation_catagiries);
            if (!specialAllowed) {
                if (special != null) {
                    special.setVisible(false);
                    special.setEnabled(false);
                } else if (bottomNavigationView.getMenu().size() > SPECIAL_TAB_INDEX) {
                    MenuItem byIndex = bottomNavigationView.getMenu().getItem(SPECIAL_TAB_INDEX);
                    if (byIndex != null) {
                        byIndex.setVisible(false);
                        byIndex.setEnabled(false);
                    }
                }
                try {
                    stopSpecialTabBlinkAnimation();
                    if (specialTabBulbOverlay != null) {
                        specialTabBulbOverlay.setVisibility(View.GONE);
                    }
                } catch (Exception ignored) {
                }
                forceFooterItemViewsMatchMenuVisibility();
                // Profile glyph still locked when Profile is shown (online).
                if (isDeviceOnline() && ProfileHubConfigHelper.isFooterShowProfile(this)) {
                    MenuItem profile = bottomNavigationView.getMenu().findItem(R.id.navigation_profile);
                    if (profile != null) {
                        profile.setIcon(R.drawable.ic_nav_profile);
                    }
                    try {
                        BottomNavigationMenuView menuView =
                                (BottomNavigationMenuView) bottomNavigationView.getChildAt(0);
                        if (menuView != null) {
                            for (int i = 0; i < menuView.getChildCount(); i++) {
                                View item = menuView.getChildAt(i);
                                if (!(item instanceof BottomNavigationItemView)) {
                                    continue;
                                }
                                BottomNavigationItemView piv = (BottomNavigationItemView) item;
                                if (piv.getItemData() == null
                                        || piv.getItemData().getItemId() != R.id.navigation_profile) {
                                    continue;
                                }
                                View profileIcon = piv.findViewById(
                                        com.google.android.material.R.id.navigation_bar_item_icon_view);
                                if (profileIcon instanceof ImageView) {
                                    ImageView pivIv = (ImageView) profileIcon;
                                    pivIv.setImageResource(R.drawable.ic_nav_profile);
                                    pivIv.setScaleType(ImageView.ScaleType.FIT_CENTER);
                                    pivIv.setVisibility(View.VISIBLE);
                                    pivIv.setAlpha(1f);
                                }
                                break;
                            }
                        }
                    } catch (Exception ignored) {
                    }
                    applyFooterTabIconTints();
                }
                return;
            }
            if (special != null) {
                special.setIcon(R.drawable.ic_footer_special);
                special.setVisible(true);
                special.setEnabled(true);
            } else if (bottomNavigationView.getMenu().size() > SPECIAL_TAB_INDEX) {
                MenuItem byIndex = bottomNavigationView.getMenu().getItem(SPECIAL_TAB_INDEX);
                if (byIndex != null) {
                    byIndex.setIcon(R.drawable.ic_footer_special);
                    byIndex.setVisible(true);
                    byIndex.setEnabled(true);
                }
            }
            // Also lock footer Profile to the person glyph every rebalance.
            MenuItem profile = bottomNavigationView.getMenu().findItem(R.id.navigation_profile);
            if (profile != null) {
                profile.setIcon(R.drawable.ic_nav_profile);
            }
        } catch (Exception ignored) {
        }
        BottomNavigationItemView itemView = findSpecialTabItemView();
        if (itemView != null) {
            View defaultIcon = itemView.findViewById(
                    com.google.android.material.R.id.navigation_bar_item_icon_view);
            if (defaultIcon != null) {
                // CRITICAL: never leave this INVISIBLE — was the label-only bug after rebalance.
                defaultIcon.setVisibility(View.VISIBLE);
                defaultIcon.setAlpha(1f);
                if (defaultIcon instanceof ImageView) {
                    ImageView iv = (ImageView) defaultIcon;
                    iv.setImageResource(R.drawable.ic_footer_special);
                    iv.setScaleType(ImageView.ScaleType.FIT_CENTER);
                }
            }
        }
        // Profile icon view (same selector tint as reload).
        try {
            BottomNavigationMenuView menuView =
                    (BottomNavigationMenuView) bottomNavigationView.getChildAt(0);
            if (menuView != null) {
                for (int i = 0; i < menuView.getChildCount(); i++) {
                    View item = menuView.getChildAt(i);
                    if (!(item instanceof BottomNavigationItemView)) {
                        continue;
                    }
                    BottomNavigationItemView piv = (BottomNavigationItemView) item;
                    if (piv.getItemData() == null
                            || piv.getItemData().getItemId() != R.id.navigation_profile) {
                        continue;
                    }
                    View profileIcon = piv.findViewById(
                            com.google.android.material.R.id.navigation_bar_item_icon_view);
                    if (profileIcon instanceof ImageView) {
                        ImageView pivIv = (ImageView) profileIcon;
                        pivIv.setImageResource(R.drawable.ic_nav_profile);
                        pivIv.setScaleType(ImageView.ScaleType.FIT_CENTER);
                        pivIv.setVisibility(View.VISIBLE);
                        pivIv.setAlpha(1f);
                    }
                    break;
                }
            }
        } catch (Exception ignored) {
        }
        applyFooterTabIconTints();
    }

    private void ensureSpecialTabBulbOverlay() {
        if (bottomNavigationView == null) {
            return;
        }
        // Offline / admin-off: never attach bulb or force-show Special (in-flight
        // postDelayed retries after network drop must no-op).
        if (!isFooterSpecialTabAllowed()) {
            try {
                stopSpecialTabBlinkAnimation();
                if (specialTabBulbOverlay != null) {
                    specialTabBulbOverlay.setVisibility(View.GONE);
                }
                ensureSpecialMenuIconAlwaysVisible();
            } catch (Exception ignored) {
            }
            return;
        }
        if (isVisibleFooterQuietCard()) {
            hideSpecialBlinkForQuietCard();
            return;
        }
        if (isMagazineShareFooterShowing()) {
            stopSpecialTabBlinkAnimation();
            if (specialTabBulbOverlay != null) {
                specialTabBulbOverlay.setVisibility(View.GONE);
            }
            return;
        }
        // Menu icon first — independent of overlay success.
        ensureSpecialMenuIconAlwaysVisible();

        // Menu rebuild pools item views LIFO. The Special overlay then sits on
        // Daily Updates (menu index 3). Never treat that parent as already set up.
        if (specialTabBulbOverlay != null
                && specialTabBulbOverlay.getParent() != null
                && !isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            detachMisplacedSpecialOverlay();
            stripSpecialPulseFromOtherFooterItems();
        }

        if (specialTabBulbOverlay != null) {
            if (specialTabBulbOverlay.getParent() != null
                    && specialTabBulbOverlay.isAttachedToWindow()
                    && isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
                // After first session open: hide overlay so only one icon shows;
                // while blink pending keep overlay for orange pulse on top of solid icon.
                if (specialTabViewedThisSession) {
                    specialTabBulbOverlay.setVisibility(View.GONE);
                } else {
                    specialTabBulbOverlay.setVisibility(View.VISIBLE);
                    specialTabBulbOverlay.setImageResource(R.drawable.ic_footer_special);
                }
                return;
            }
            specialTabBulbOverlay = null;
        }

        BottomNavigationItemView itemView = findSpecialTabItemView();
        if (itemView == null) {
            if (specialTabBulbSetupRetryCount < 16) {
                specialTabBulbSetupRetryCount++;
                bottomNavigationView.postDelayed(this::ensureSpecialTabBulbOverlay, 50);
            }
            return;
        }
        specialTabBulbSetupRetryCount = 0;

        View existingOverlay = itemView.findViewById(R.id.special_tab_bulb_overlay);
        if (existingOverlay instanceof ImageView) {
            specialTabBulbOverlay = (ImageView) existingOverlay;
        } else {
            LayoutInflater.from(this).inflate(R.layout.badge_layout, itemView, true);
            specialTabBulbOverlay = itemView.findViewById(R.id.special_tab_bulb_overlay);
        }

        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.setImageResource(R.drawable.ic_footer_special);
            specialTabBulbOverlay.setScaleType(ImageView.ScaleType.FIT_CENTER);
            specialTabBulbOverlay.setAlpha(1f);
            // Overlay is blink-only polish; menu Material icon stays VISIBLE underneath.
            specialTabBulbOverlay.setVisibility(
                    specialTabViewedThisSession ? View.GONE : View.VISIBLE);
            specialTabBulbOverlay.bringToFront();
        }
        // Always re-assert Material icon after any overlay attach — never INVISIBLE.
        ensureSpecialMenuIconAlwaysVisible();
    }

    private void updateSpecialTabBlinkIndicator() {
        if (bottomNavigationView == null) {
            return;
        }
        Logone.d("HomePage", "SpecialTabBlink pending:" + !specialTabViewedThisSession);
        if (isVisibleFooterQuietCard()) {
            hideSpecialBlinkForQuietCard();
            return;
        }
        ensureSpecialMenuIconAlwaysVisible();
        ensureSpecialTabBulbOverlay();
        if (!specialTabViewedThisSession) {
            showSpecialTabBlink();
        } else {
            showSpecialTabStaticBulb();
        }
    }

    private void showSpecialTabBlink() {
        if (bottomNavigationView == null) {
            return;
        }
        if (isVisibleFooterQuietCard()) {
            hideSpecialBlinkForQuietCard();
            return;
        }
        if (isMagazineShareFooterShowing()) {
            stopSpecialTabBlinkAnimation();
            return;
        }
        ensureSpecialMenuIconAlwaysVisible();
        ensureSpecialTabBulbOverlay();
        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.setVisibility(View.VISIBLE);
            specialTabBulbOverlay.setImageResource(R.drawable.ic_footer_special);
        }
        // Blink target: overlay if present, else the Material icon itself.
        startSpecialTabBlinkAnimation();
    }

    private void clearSpecialTabBlink() {
        specialTabViewedThisSession = true;
        SharedPrefsData.putBool(HomePage.this, Constants.Event_Status, false, Constants.PREF_NAME);
        showSpecialTabStaticBulb();
    }

    private void showSpecialTabStaticBulb() {
        if (bottomNavigationView == null) {
            return;
        }
        stopSpecialTabBlinkAnimation();
        specialTabBulbSetupRetryCount = 0;
        ensureSpecialMenuIconAlwaysVisible();
        if (specialTabBulbOverlay != null) {
            // Hide overlay post-viewed so only the permanent menu icon shows (no double).
            specialTabBulbOverlay.setVisibility(View.GONE);
            specialTabBulbOverlay.clearColorFilter();
            specialTabBulbOverlay.setAlpha(1f);
        }
        applyFooterTabIconTints();
    }

    private void restoreSpecialTabIcon() {
        if (bottomNavigationView == null) {
            return;
        }
        specialTabBulbSetupRetryCount = 0;
        stopSpecialTabBlinkAnimation();
        ensureSpecialMenuIconAlwaysVisible();
        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.setVisibility(View.GONE);
            specialTabBulbOverlay.clearColorFilter();
            specialTabBulbOverlay.setAlpha(1f);
        }
        applyFooterTabIconTints();
    }

    /**
     * Locates the Material bottom-nav item view for the Special tab so the icon
     * overlay can be centered on it (24dp, matching other footer glyphs).
     */
    @Nullable
    private BottomNavigationItemView findSpecialTabItemView() {
        if (bottomNavigationView == null) {
            return null;
        }
        BottomNavigationMenuView bottomNavigationMenuView =
                (BottomNavigationMenuView) bottomNavigationView.getChildAt(0);
        if (bottomNavigationMenuView == null) {
            return null;
        }
        bottomNavigationMenuView.setClipChildren(false);
        bottomNavigationMenuView.setClipToPadding(false);
        for (int i = 0; i < bottomNavigationMenuView.getChildCount(); i++) {
            View item = bottomNavigationMenuView.getChildAt(i);
            if (!(item instanceof BottomNavigationItemView)) {
                continue;
            }
            BottomNavigationItemView itemView = (BottomNavigationItemView) item;
            if (itemView.getItemData().getItemId() != R.id.navigation_catagiries) {
                continue;
            }
            itemView.setClipChildren(false);
            itemView.setClipToPadding(false);
            return itemView;
        }
        return null;
    }

    private void startSpecialTabBlinkAnimation() {
        if (specialTabViewedThisSession || !isFooterSpecialTabAllowed()) {
            return;
        }
        // Magazine / special-gallery cards blink the center Share slot, never
        // Special (menu index 1) and never Daily Updates (navigation_status).
        // Ads hide the middle column and must not pulse either tab.
        if (isMagazineShareFooterShowing() || isVisibleFooterQuietCard()) {
            if (isVisibleFooterQuietCard()) {
                hideSpecialBlinkForQuietCard();
            } else {
                stopSpecialTabBlinkAnimation();
            }
            return;
        }
        // Do not setIcon / setTitle here. That notifies the menu and refreshes
        // every footer label. The pulse is only the overlay on Special's view.
        bindSpecialPulseOverlayToSpecialItem();
        stripSpecialPulseFromOtherFooterItems();
        View blinkTarget = null;
        if (specialTabBulbOverlay != null
                && specialTabBulbOverlay.getParent() != null
                && isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            specialTabBulbOverlay.setVisibility(View.VISIBLE);
            blinkTarget = specialTabBulbOverlay;
        }
        if (blinkTarget == null
                || !isViewInsideFooterItem(blinkTarget, R.id.navigation_catagiries)) {
            stripSpecialPulseFromOtherFooterItems();
            return;
        }
        if (specialTabBulbAnimator != null) {
            specialTabBulbAnimator.cancel();
            specialTabBulbAnimator = null;
        }
        blinkTarget.setVisibility(View.VISIBLE);
        if (blinkTarget instanceof ImageView) {
            ((ImageView) blinkTarget).setColorFilter(
                    ContextCompat.getColor(this, R.color.brand_orange), PorterDuff.Mode.SRC_ATOP);
        }
        final View pulseTarget = blinkTarget;
        ObjectAnimator animator = ObjectAnimator.ofFloat(pulseTarget, View.ALPHA, 1f, 0.4f);
        animator.setDuration(700);
        animator.setRepeatCount(ValueAnimator.INFINITE);
        animator.setRepeatMode(ValueAnimator.REVERSE);
        animator.setInterpolator(new AccelerateDecelerateInterpolator());
        animator.addUpdateListener(animation -> {
            if (specialPulseSuppressReanchor || specialPulseReanchorGuard) {
                return;
            }
            if (pulseTarget == specialTabBulbOverlay
                    && isViewInsideFooterItem(pulseTarget, R.id.navigation_catagiries)) {
                return;
            }
            // Animation runs before draw. Drop the lightning here so this frame
            // cannot paint it on Daily Updates. A posted clear is one frame late.
            animation.cancel();
            if (specialTabBulbAnimator == animation) {
                specialTabBulbAnimator = null;
            }
            if (pulseTarget != null
                    && !isViewInsideFooterItem(pulseTarget, R.id.navigation_catagiries)) {
                pulseTarget.setVisibility(View.GONE);
                pulseTarget.clearAnimation();
                pulseTarget.setAlpha(1f);
                if (pulseTarget instanceof ImageView) {
                    ((ImageView) pulseTarget).clearColorFilter();
                }
                clearCheckedHighlightIfMenuDisagrees(pulseTarget);
                if (pulseTarget.getParent() instanceof ViewGroup) {
                    ((ViewGroup) pulseTarget.getParent()).removeView(pulseTarget);
                }
                if (specialTabBulbOverlay == pulseTarget) {
                    specialTabBulbOverlay = null;
                }
            }
            reanchorSpecialTabPulse();
        });
        specialTabBulbAnimator = animator;
        animator.start();
    }

    private void stopSpecialTabBlinkAnimation() {
        if (specialTabBulbAnimator != null) {
            specialTabBulbAnimator.cancel();
            specialTabBulbAnimator = null;
        }
        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.clearAnimation();
            specialTabBulbOverlay.clearColorFilter();
            specialTabBulbOverlay.setAlpha(1f);
        }
        BottomNavigationItemView itemView = findSpecialTabItemView();
        if (itemView != null) {
            View defaultIcon = itemView.findViewById(
                    com.google.android.material.R.id.navigation_bar_item_icon_view);
            if (defaultIcon != null) {
                defaultIcon.clearAnimation();
                defaultIcon.setAlpha(1f);
                defaultIcon.setVisibility(View.VISIBLE);
                if (defaultIcon instanceof ImageView) {
                    ((ImageView) defaultIcon).clearColorFilter();
                }
            }
        }
        // Re-apply ColorStateList so selected Special/Profile stay brand orange.
        applyFooterTabIconTints();
        // Pooled item views move the orange filter onto Daily Updates.
        stripSpecialPulseFromOtherFooterItems();
    }

    /**
     * Ads and invite cards: no orange pulse on Special or Daily Updates.
     * Does not reload the feed.
     */
    private void hideSpecialBlinkForQuietCard() {
        stopSpecialTabBlinkAnimation();
        if (specialTabBulbOverlay != null
                && !isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            detachMisplacedSpecialOverlay();
        }
        if (specialTabBulbOverlay != null) {
            specialTabBulbOverlay.setVisibility(View.GONE);
            specialTabBulbOverlay.clearColorFilter();
            specialTabBulbOverlay.setAlpha(1f);
        }
        stripSpecialPulseFromOtherFooterItems();
        clearFooterItemIconPulse(R.id.navigation_catagiries);
        releaseDailyUpdatesCheckLeftByQuietCard();
    }

    private boolean isViewInsideFooterItem(@Nullable View view, int itemId) {
        View current = view;
        while (current != null) {
            if (current instanceof BottomNavigationItemView) {
                MenuItem data = ((BottomNavigationItemView) current).getItemData();
                return data != null && data.getItemId() == itemId;
            }
            if (!(current.getParent() instanceof View)) {
                return false;
            }
            current = (View) current.getParent();
        }
        return false;
    }

    /** Drop a special-blink overlay that a menu rebuild rebound onto another tab. */
    private void detachMisplacedSpecialOverlay() {
        if (specialTabBulbOverlay == null) {
            return;
        }
        if (isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            return;
        }
        specialTabBulbOverlay.clearAnimation();
        specialTabBulbOverlay.clearColorFilter();
        specialTabBulbOverlay.setAlpha(1f);
        if (specialTabBulbOverlay.getParent() instanceof ViewGroup) {
            ((ViewGroup) specialTabBulbOverlay.getParent()).removeView(specialTabBulbOverlay);
        }
        specialTabBulbOverlay = null;
    }

    /**
     * Take the Special lightning off its item view before {@code setVisible}
     * can {@code buildMenuView}. The pool is last-in, so that view is the next
     * Daily Updates item. Clearing after the rebuild draws the blink there once.
     */
    private void liftSpecialPulseBeforeFooterRebind() {
        specialPulseSuppressReanchor = true;
        try {
            if (specialTabBulbAnimator != null) {
                Animator running = specialTabBulbAnimator;
                specialTabBulbAnimator = null;
                running.cancel();
            }
            if (specialTabBulbOverlay != null) {
                ImageView overlay = specialTabBulbOverlay;
                specialTabBulbOverlay = null;
                overlay.clearAnimation();
                overlay.animate().cancel();
                overlay.clearColorFilter();
                overlay.setAlpha(1f);
                overlay.setVisibility(View.GONE);
                clearCheckedHighlightIfMenuDisagrees(overlay);
                if (overlay.getParent() instanceof ViewGroup) {
                    ((ViewGroup) overlay.getParent()).removeView(overlay);
                }
            }
        } finally {
            specialPulseSuppressReanchor = false;
        }
    }

    /** Checked orange belongs to the menu item, not to a view the pool just reused. */
    private void clearCheckedHighlightIfMenuDisagrees(@Nullable View start) {
        View current = start;
        while (current != null) {
            if (current instanceof BottomNavigationItemView) {
                BottomNavigationItemView itemView = (BottomNavigationItemView) current;
                MenuItem data = itemView.getItemData();
                if (data != null && itemView.isSelected() && !data.isChecked()) {
                    itemView.setChecked(false);
                }
                return;
            }
            if (!(current.getParent() instanceof View)) {
                return;
            }
            current = (View) current.getParent();
        }
    }

    /**
     * Put the Special pulse back on Special only.
     * Does not call {@code setIcon}, {@code setTitle}, or {@code updateMenuView},
     * so the four labels are not redrawn. Runs before the next draw.
     */
    private void reanchorSpecialTabPulse() {
        if (bottomNavigationView == null
                || specialPulseSuppressReanchor
                || specialPulseReanchorGuard) {
            return;
        }
        specialPulseReanchorGuard = true;
        try {
            reanchorSpecialTabPulseBody();
        } finally {
            specialPulseReanchorGuard = false;
        }
    }

    private void reanchorSpecialTabPulseBody() {
        if (bottomNavigationView == null) {
            return;
        }
        if (isVisibleFooterQuietCard()) {
            hideSpecialBlinkForQuietCard();
            return;
        }
        if (isMagazineShareFooterShowing()) {
            stopSpecialTabBlinkAnimation();
            return;
        }
        View pulseTarget = specialPulseAnimatorTarget();
        boolean pulseOnSpecial = pulseTarget != null
                && isViewInsideFooterItem(pulseTarget, R.id.navigation_catagiries)
                && specialTabBulbAnimator != null
                && specialTabBulbAnimator.isRunning();
        if (!pulseOnSpecial && specialTabBulbAnimator != null) {
            specialTabBulbAnimator.cancel();
            specialTabBulbAnimator = null;
        }
        if (specialTabBulbOverlay != null
                && !isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            detachMisplacedSpecialOverlay();
        }
        stripSpecialPulseFromOtherFooterItems();
        if (!isFooterSpecialTabAllowed() || specialTabViewedThisSession) {
            if (specialTabBulbAnimator != null) {
                specialTabBulbAnimator.cancel();
                specialTabBulbAnimator = null;
            }
            if (specialTabBulbOverlay != null) {
                specialTabBulbOverlay.clearColorFilter();
                specialTabBulbOverlay.setAlpha(1f);
                specialTabBulbOverlay.setVisibility(View.GONE);
            }
            return;
        }
        if (pulseOnSpecial
                && specialTabBulbOverlay != null
                && isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            return;
        }
        startSpecialTabBlinkAnimation();
    }

    @Nullable
    private View specialPulseAnimatorTarget() {
        if (!(specialTabBulbAnimator instanceof ObjectAnimator)) {
            return null;
        }
        Object target = ((ObjectAnimator) specialTabBulbAnimator).getTarget();
        return target instanceof View ? (View) target : null;
    }

    /**
     * Overlay only, on the item whose menu id is Special. A recycled item view
     * keeps this child, which is how the lightning landed on Daily Updates.
     */
    private void bindSpecialPulseOverlayToSpecialItem() {
        if (bottomNavigationView == null || !isFooterSpecialTabAllowed()) {
            return;
        }
        if (specialTabBulbOverlay != null
                && specialTabBulbOverlay.getParent() != null
                && !isViewInsideFooterItem(specialTabBulbOverlay, R.id.navigation_catagiries)) {
            detachMisplacedSpecialOverlay();
        }
        BottomNavigationItemView itemView = findSpecialTabItemView();
        if (itemView == null) {
            return;
        }
        if (specialTabBulbOverlay != null && specialTabBulbOverlay.getParent() == itemView) {
            specialTabBulbOverlay.setVisibility(View.VISIBLE);
            return;
        }
        View existingOverlay = itemView.findViewById(R.id.special_tab_bulb_overlay);
        if (existingOverlay instanceof ImageView) {
            specialTabBulbOverlay = (ImageView) existingOverlay;
        } else {
            LayoutInflater.from(this).inflate(R.layout.badge_layout, itemView, true);
            specialTabBulbOverlay = itemView.findViewById(R.id.special_tab_bulb_overlay);
        }
        if (specialTabBulbOverlay == null) {
            return;
        }
        specialTabBulbOverlay.setImageResource(R.drawable.ic_footer_special);
        specialTabBulbOverlay.setScaleType(ImageView.ScaleType.FIT_CENTER);
        specialTabBulbOverlay.setAlpha(1f);
        specialTabBulbOverlay.setVisibility(View.VISIBLE);
        specialTabBulbOverlay.bringToFront();
    }

    /**
     * Clear the Special lightning and its alpha pulse from News, Daily Updates,
     * Profile, and the WhatsApp slot. Leaves the Special item and magazine Share
     * alone. Icon restore is on the ImageView only, so labels are not refreshed.
     */
    private void stripSpecialPulseFromOtherFooterItems() {
        if (bottomNavigationView == null) {
            return;
        }
        View menuChild = bottomNavigationView.getChildAt(0);
        if (!(menuChild instanceof BottomNavigationMenuView)) {
            return;
        }
        BottomNavigationMenuView menuView = (BottomNavigationMenuView) menuChild;
        for (int i = 0; i < menuView.getChildCount(); i++) {
            View child = menuView.getChildAt(i);
            if (!(child instanceof BottomNavigationItemView)) {
                continue;
            }
            BottomNavigationItemView itemView = (BottomNavigationItemView) child;
            MenuItem data = itemView.getItemData();
            if (data == null || data.getItemId() == R.id.navigation_catagiries) {
                continue;
            }
            cancelSpecialPulseIfInside(itemView);
            removeSpecialOverlays(itemView);
            View icon = itemView.findViewById(
                    com.google.android.material.R.id.navigation_bar_item_icon_view);
            if (icon != null) {
                icon.clearAnimation();
                icon.setAlpha(1f);
                if (icon instanceof ImageView) {
                    ImageView iv = (ImageView) icon;
                    iv.clearColorFilter();
                    int iconRes = footerIconResForItem(data.getItemId());
                    if (iconRes != 0) {
                        iv.setImageResource(iconRes);
                        ColorStateList tint = bottomNavigationView.getItemIconTintList();
                        if (tint != null) {
                            androidx.core.widget.ImageViewCompat.setImageTintList(iv, tint);
                        }
                    }
                }
            }
            if (itemView.isSelected() && !data.isChecked()) {
                itemView.setSelected(false);
            }
        }
        if (imageVIewShareWhatsapp != null) {
            imageVIewShareWhatsapp.clearAnimation();
            imageVIewShareWhatsapp.animate().cancel();
            imageVIewShareWhatsapp.setAlpha(1f);
        }
    }

    private void cancelSpecialPulseIfInside(@Nullable View item) {
        View target = specialPulseAnimatorTarget();
        if (target == null || item == null || specialTabBulbAnimator == null) {
            return;
        }
        View current = target;
        while (current != null) {
            if (current == item) {
                specialTabBulbAnimator.cancel();
                specialTabBulbAnimator = null;
                return;
            }
            if (!(current.getParent() instanceof View)) {
                return;
            }
            current = (View) current.getParent();
        }
    }

    private void removeSpecialOverlays(@Nullable ViewGroup item) {
        if (item == null) {
            return;
        }
        for (int i = item.getChildCount() - 1; i >= 0; i--) {
            View child = item.getChildAt(i);
            if (child.getId() != R.id.special_tab_bulb_overlay) {
                continue;
            }
            child.clearAnimation();
            child.setAlpha(1f);
            if (child instanceof ImageView) {
                ((ImageView) child).clearColorFilter();
            }
            item.removeViewAt(i);
            if (child == specialTabBulbOverlay) {
                specialTabBulbOverlay = null;
            }
        }
    }

    /** Menu glyph for a non-Special tab. 0 leaves the current drawable (WhatsApp slot). */
    private static int footerIconResForItem(int itemId) {
        if (itemId == R.id.navigation_home) {
            return R.drawable.refresh_icon;
        }
        if (itemId == R.id.navigation_status) {
            return R.drawable.ic_footer_daily_updates;
        }
        if (itemId == R.id.navigation_profile) {
            return R.drawable.ic_nav_profile;
        }
        return 0;
    }

    /** Stop an orange pulse left on a footer icon after the bar is rebuilt. */
    private void clearFooterItemIconPulse(int itemId) {
        View item = findFooterMenuItemView(itemId);
        if (item == null) {
            return;
        }
        View stray = item.findViewById(R.id.special_tab_bulb_overlay);
        if (stray != null && stray != specialTabBulbOverlay) {
            stray.clearAnimation();
            stray.setAlpha(1f);
            if (stray instanceof ImageView) {
                ((ImageView) stray).clearColorFilter();
            }
            if (stray.getParent() instanceof ViewGroup) {
                ((ViewGroup) stray.getParent()).removeView(stray);
            }
        }
        View icon = item.findViewById(
                com.google.android.material.R.id.navigation_bar_item_icon_view);
        if (icon != null) {
            icon.clearAnimation();
            icon.setAlpha(1f);
            if (icon instanceof ImageView) {
                ((ImageView) icon).clearColorFilter();
            }
        }
        if (item.isSelected() && item instanceof BottomNavigationItemView) {
            MenuItem data = ((BottomNavigationItemView) item).getItemData();
            if (data != null && !data.isChecked()) {
                item.setSelected(false);
            }
        }
    }

    /**
     * Hiding the middle slot rebuilds BottomNavigationView. The checked index
     * can land on Daily Updates (menu index 3, the next visible tab). Put the
     * check back on News without opening Daily Updates or reloading the feed.
     */
    private void releaseDailyUpdatesCheckLeftByQuietCard() {
        if (bottomNavigationView == null || bottomNavigationView.getMenu() == null) {
            return;
        }
        if (isDailyUpdatesMode() || isCalendarMode()) {
            return;
        }
        MenuItem daily = bottomNavigationView.getMenu().findItem(R.id.navigation_status);
        int selected = bottomNavigationView.getSelectedItemId();
        boolean dailyChecked = (daily != null && daily.isChecked())
                || selected == R.id.navigation_status;
        boolean middleChecked = selected == R.id.navigation_stricker;
        if (!dailyChecked && !middleChecked) {
            return;
        }
        if (selected == R.id.navigation_catagiries && isSpecialFeedMode()) {
            return;
        }
        try {
            selectFooterTabWithoutMotion(R.id.navigation_home);
        } catch (Exception ignored) {
        } finally {
            suppressBottomNavCallbacks = false;
        }
    }

